# ============================================================
# ICDM RQ4 Synthetic Benchmark v5
# Tuned-β Balanced Second-Order Graph-Position Recovery
#
# New fixes in this version:
#   1. Tune β for VGIB instead of using a fixed bottleneck strength.
#   2. Use max_risk_f1 threshold selection instead of recall-first thresholding.
#   3. Increase the second-order graph-position signal gap while still applying
#      species identity leakage control.
#
# Core second-order mechanism:
#   Anchor patients = patients with high brain vulnerability.
#   species_anchor_density(s) = anchor-neighbor count of species s / degree(s)
#   second_order_score(i) = mean species_anchor_density(s) over i's species neighbors
#
# Relational-only high-risk patients:
#   low-brain-score patients with high second_order_score.
#
# Main baselines:
#   BrainOnly, LocalMicroSummary, EarlyFusionLocalSummary
#   These do not observe full species identity columns.
#
# Diagnostic baselines:
#   DIAGNOSTIC-*-EarlyFusionSpeciesIdentity
#   These observe full species columns and are used only to check species identity leakage.
#
# Expected Colab files:
#   /content/data.csv
#   /content/micro.csv
#   /content/all_brain_result_1(3).csv
#
# Output:
#   /content/icdm_second_order_tuned_beta_outputs/
#
# Run:
#   !pip install -q numpy pandas scikit-learn scipy torch
#   !python icdm_second_order_tuned_beta_synthetic_benchmark.py
# ============================================================

