# ============================================================
# 2. Utilities
# ============================================================

def set_seed(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    torch.cuda.manual_seed_all(seed)


def get_device(cfg: Config):
    return torch.device("cuda" if cfg.use_cuda_if_available and torch.cuda.is_available() else "cpu")


def ensure_dir(path: str):
    os.makedirs(path, exist_ok=True)


def save_csv(df: pd.DataFrame, path: str):
    df.to_csv(path, index=False, encoding="utf-8-sig")
    print("Saved:", path)


def extract_tpmic_id(x):
    m = re.search(r"TPMIC\d+", str(x))
    return m.group(0) if m else None


def replace_missing_codes(df: pd.DataFrame):
    return df.replace([999, 999.0, "999", "999.0", "NA", "N/A", "", "nan", "None"], np.nan)


def encode_sex_like(series: pd.Series):
    if pd.api.types.is_numeric_dtype(series):
        return pd.to_numeric(series, errors="coerce")
    mapping = {
        "m": 1, "male": 1, "man": 1, "男": 1, "男性": 1, "1": 1,
        "f": 0, "female": 0, "woman": 0, "女": 0, "女性": 0, "0": 0,
    }
    return series.astype(str).str.strip().str.lower().map(mapping)


def safe_numeric(df: pd.DataFrame):
    out = df.copy()
    for c in out.columns:
        if c.lower() in ["sex", "gender"]:
            out[c] = encode_sex_like(out[c])
        else:
            out[c] = pd.to_numeric(out[c], errors="coerce")
    return out


def standardize_np(X):
    X = pd.DataFrame(X).replace([np.inf, -np.inf], np.nan)
    X = SimpleImputer(strategy="median").fit_transform(X)
    return StandardScaler().fit_transform(X)


def choose_threshold(y_val, prob_val, cfg: Config):
    y_val = np.asarray(y_val).astype(int)
    prob_val = np.asarray(prob_val).astype(float)
    best_t, best_score = 0.5, -np.inf

    for t in np.linspace(0.02, 0.98, cfg.threshold_grid_size):
        pred = (prob_val >= t).astype(int)
        if cfg.threshold_policy == "max_risk_f1":
            score = f1_score(y_val, pred, zero_division=0)
        elif cfg.threshold_policy == "max_macro_f1":
            score = f1_score(y_val, pred, average="macro", zero_division=0)
        else:
            rec = recall_score(y_val, pred, zero_division=0)
            prec = precision_score(y_val, pred, zero_division=0)
            score = rec if prec >= 0.5 else -1
        if score > best_score:
            best_score = score
            best_t = float(t)
    return best_t


def binary_metrics(y_true, prob, pred=None, threshold=0.5):
    y_true = np.asarray(y_true).astype(int)
    prob = np.asarray(prob).astype(float)
    if pred is None:
        pred = (prob >= threshold).astype(int)

    out = {
        "auc": np.nan,
        "pr_auc": np.nan,
        "risk_recall": recall_score(y_true, pred, zero_division=0),
        "risk_precision": precision_score(y_true, pred, zero_division=0),
        "risk_f1": f1_score(y_true, pred, zero_division=0),
        "macro_f1": f1_score(y_true, pred, average="macro", zero_division=0),
        "balanced_acc": balanced_accuracy_score(y_true, pred),
        "acc": accuracy_score(y_true, pred),
        "predicted_risk_rate": float(np.mean(pred == 1)),
        "brier": np.nan,
    }
    if len(np.unique(y_true)) == 2:
        out["auc"] = roc_auc_score(y_true, prob)
        out["pr_auc"] = average_precision_score(y_true, prob)
        out["brier"] = brier_score_loss(y_true, np.clip(prob, 1e-6, 1 - 1e-6))
    return out


def split_indices(y, seed):
    idx = np.arange(len(y))
    train_val, test = train_test_split(idx, test_size=0.25, stratify=y, random_state=seed)
    train, val = train_test_split(train_val, test_size=0.22, stratify=y[train_val], random_state=seed + 100)
    return train, val, test


def sample_without_replacement(rng, pool, k):
    pool = np.asarray(pool, dtype=int)
    if len(pool) == 0 or k <= 0:
        return []
    return rng.choice(pool, size=min(k, len(pool)), replace=False).tolist()


# ============================================================
# 3. Real-data calibration
# ============================================================

def load_real_data_for_calibration(cfg: Config):
    if not (os.path.exists(cfg.basic_path) and os.path.exists(cfg.micro_path) and os.path.exists(cfg.brain_path)):
        raise FileNotFoundError(
            "Expected files not found. Upload these files to Colab:\n"
            f"  {cfg.basic_path}\n"
            f"  {cfg.micro_path}\n"
            f"  {cfg.brain_path}"
        )

    basic = replace_missing_codes(pd.read_csv(cfg.basic_path))
    micro = replace_missing_codes(pd.read_csv(cfg.micro_path))
    brain = replace_missing_codes(pd.read_csv(cfg.brain_path))

    brain["ID"] = brain[cfg.id_col_brain].apply(extract_tpmic_id)
    brain = brain.dropna(subset=["ID"]).copy()

    keep_labels = ["Normal", "MCI", "Dementia"]
    basic[cfg.label_col] = basic[cfg.label_col].astype(str)
    basic = basic[basic[cfg.label_col].isin(keep_labels)].copy()

    merged = (
        basic.merge(micro, on="ID", how="inner", suffixes=("", "_micro"))
             .merge(brain, on="ID", how="inner", suffixes=("", "_brain"))
    )

    print("========== Real Data Calibration Summary ==========")
    print("basic:", basic.shape, "micro:", micro.shape, "brain:", brain.shape)
    print("merged:", merged.shape)
    print(merged[cfg.label_col].value_counts())
    print("===================================================\n")
    return basic, micro, brain, merged


def build_basic_features(df: pd.DataFrame):
    cols = ["Sex", "Age", "edu_yr", "BMI", "smoking", "drinking", "exercise_days"]
    cols = [c for c in cols if c in df.columns]
    return safe_numeric(df[cols]).reset_index(drop=True)


def build_brain_features(df: pd.DataFrame):
    candidate_cols = [
        "Left-Hippocampus", "Right-Hippocampus",
        "Left-Amygdala", "Right-Amygdala",
        "lh-entorhinal", "rh-entorhinal",
    ]
    brain_cols = [c for c in candidate_cols if c in df.columns]
    out = pd.DataFrame(index=df.index)

    for c in brain_cols:
        out[c] = pd.to_numeric(df[c], errors="coerce")

    pairs = {
        "Hippocampus": ("Left-Hippocampus", "Right-Hippocampus"),
        "Amygdala": ("Left-Amygdala", "Right-Amygdala"),
        "Entorhinal": ("lh-entorhinal", "rh-entorhinal"),
    }
    for name, (lcol, rcol) in pairs.items():
        if lcol in df.columns and rcol in df.columns:
            L = pd.to_numeric(df[lcol], errors="coerce")
            R = pd.to_numeric(df[rcol], errors="coerce")
            mean = (L + R) / 2.0
            out[f"{name}_mean"] = mean
            out[f"{name}_diff"] = L - R
            out[f"{name}_asymmetry"] = (L - R).abs() / (mean.abs() + 1e-8)

    norm_col = "Total_Labeled_Brain_Volume_mm3"
    if norm_col in df.columns:
        total = pd.to_numeric(df[norm_col], errors="coerce")
        for c in brain_cols:
            out[f"{c}_norm"] = pd.to_numeric(df[c], errors="coerce") / (total + 1e-8)

    return out.reset_index(drop=True)


def get_micro_raw_aligned(merged: pd.DataFrame, micro_original: pd.DataFrame, cfg: Config):
    aligned = merged[["ID"]].merge(micro_original, on="ID", how="left")
    exclude = {"ID", cfg.label_col}
    micro_cols = [c for c in aligned.columns if c not in exclude]
    X = safe_numeric(aligned[micro_cols]).dropna(axis=1, how="all").fillna(0.0).clip(lower=0)
    return X.reset_index(drop=True)


def select_topk_micro_global(X_raw: pd.DataFrame, cfg: Config):
    prevalence = (X_raw > 0).mean(axis=0)
    keep = prevalence[prevalence >= cfg.min_prevalence].index.tolist()
    if len(keep) == 0:
        keep = X_raw.columns.tolist()
    X = X_raw[keep]
    selected = X.var(axis=0).sort_values(ascending=False).head(min(cfg.top_k_species, X.shape[1])).index.tolist()
    return selected


def build_calibration(merged, micro, cfg: Config):
    basic_x = build_basic_features(merged)
    brain_x = build_brain_features(merged)
    patient_x = pd.concat([basic_x, brain_x], axis=1).reset_index(drop=True)

    micro_raw = get_micro_raw_aligned(merged, micro, cfg)
    selected_species = select_topk_micro_global(micro_raw, cfg)
    micro_sel = micro_raw[selected_species].copy().fillna(0.0).clip(lower=0)

    y_real = merged[cfg.label_col].map({"Normal": 0, "MCI": 1, "Dementia": 1}).astype(int).values

    prev = (micro_sel > 0).mean(axis=0).values
    mean_positive = []
    for c in selected_species:
        vals = micro_sel.loc[micro_sel[c] > 0, c]
        mean_positive.append(float(vals.mean()) if len(vals) else 1.0)

    return {
        "real_N": int(len(merged)),
        "synthetic_N": int(max(cfg.n_patients_min, len(merged))),
        "patient_dim": int(patient_x.shape[1]),
        "basic_dim": int(basic_x.shape[1]),
        "brain_dim": int(brain_x.shape[1]),
        "n_species": int(len(selected_species)),
        "selected_species": selected_species,
        "real_risk_rate": float(y_real.mean()),
        "species_prevalence": np.asarray(prev, dtype=float),
        "species_mean_positive": np.asarray(mean_positive, dtype=float),
        "real_patient_feature_mean": np.nanmean(patient_x.values.astype(float), axis=0),
        "real_patient_feature_std": np.nanstd(patient_x.values.astype(float), axis=0) + 1e-6,
        "patient_feature_columns": list(patient_x.columns),
    }


# ============================================================
# 4. Synthetic generation
# ============================================================

def assign_edges_by_composition(rng, nodes, species_groups, composition, S, D):
    A_sub = np.zeros((len(nodes), S), dtype=np.float32)
    for row_idx, _ in enumerate(nodes):
        chosen = []
        for group_name, k in composition.items():
            chosen += sample_without_replacement(rng, species_groups[group_name], k)
        chosen = list(dict.fromkeys(chosen))
        if len(chosen) < D:
            remaining = np.setdiff1d(np.arange(S), np.asarray(chosen, dtype=int))
            chosen += sample_without_replacement(rng, remaining, D - len(chosen))
        chosen = chosen[:D]
        A_sub[row_idx, chosen] = 1.0
    return A_sub


def swap_edge_preserve_degree(A, i_remove_from, i_add_to, s, rng):
    if A[i_remove_from, s] != 1 or A[i_add_to, s] != 0:
        return False
    candidates = np.where((A[i_add_to] == 1) & (A[i_remove_from] == 0))[0]
    if len(candidates) == 0:
        return False
    t = int(rng.choice(candidates))
    A[i_remove_from, s] = 0
    A[i_add_to, s] = 1
    A[i_add_to, t] = 0
    A[i_remove_from, t] = 1
    return True


def balance_species_prevalence(A, y, cfg: Config, rng):
    A = A.copy()
    pos_idx = np.where(y == 1)[0]
    neg_idx = np.where(y == 0)[0]

    for _ in range(cfg.balance_iterations):
        pos_prev = A[pos_idx].mean(axis=0)
        neg_prev = A[neg_idx].mean(axis=0)
        diff = pos_prev - neg_prev
        species_order = np.argsort(-np.abs(diff))

        for s in species_order:
            current = A[pos_idx, s].mean() - A[neg_idx, s].mean()
            if abs(current) <= cfg.target_max_species_prev_diff:
                continue

            if current > 0:
                remove_candidates = pos_idx[A[pos_idx, s] == 1]
                add_candidates = neg_idx[A[neg_idx, s] == 0]
            else:
                remove_candidates = neg_idx[A[neg_idx, s] == 1]
                add_candidates = pos_idx[A[pos_idx, s] == 0]

            if len(remove_candidates) == 0 or len(add_candidates) == 0:
                continue

            n_moves = int(np.ceil((abs(current) - cfg.target_max_species_prev_diff) * min(len(pos_idx), len(neg_idx)) * 0.4))
            rng.shuffle(remove_candidates)
            rng.shuffle(add_candidates)

            moved = 0
            for r, a in zip(remove_candidates, add_candidates):
                if swap_edge_preserve_degree(A, int(r), int(a), int(s), rng):
                    moved += 1
                if moved >= n_moves:
                    break

        # Stop early if mean leakage is acceptable.
        pos_prev = A[pos_idx].mean(axis=0)
        neg_prev = A[neg_idx].mean(axis=0)
        if np.mean(np.abs(pos_prev - neg_prev)) <= cfg.target_mean_species_prev_diff:
            break

    return A


def compute_anchor_density(A, is_anchor, brain_score):
    deg = A.sum(axis=0) + 1e-8
    anchor_count = A[is_anchor == 1].sum(axis=0)
    anchor_density = anchor_count / deg

    anchor_brain = np.maximum(brain_score, 0) * is_anchor
    species_anchor_brain = (A.T @ anchor_brain) / (anchor_count + 1e-8)

    context = (
        0.80 * anchor_density
        + 0.20 * (species_anchor_brain - species_anchor_brain.mean()) / (species_anchor_brain.std() + 1e-8)
    )
    context = (context - context.mean()) / (context.std() + 1e-8)
    return anchor_density, context


def generate_tuned_beta_synthetic(calib: Dict, cfg: Config, seed: int):
    set_seed(seed)
    rng = np.random.default_rng(seed)

    N = int(calib["synthetic_N"])
    S = int(calib["n_species"])
    D = int(cfg.fixed_degree)
    patient_dim = int(calib["patient_dim"])

    # Latent spaces
    z_brain = rng.normal(0, 1, size=(N, cfg.latent_dim))
    z_micro_private = rng.normal(0, 1, size=(N, cfg.latent_dim))
    z_micro = (
        cfg.cross_modal_leakage * z_brain
        + np.sqrt(max(1e-8, 1 - cfg.cross_modal_leakage ** 2)) * z_micro_private
    )

    # Patient features
    Wp = rng.normal(0, 1, size=(cfg.latent_dim, patient_dim))
    X_patient = z_brain @ Wp + rng.normal(0, cfg.brain_noise, size=(N, patient_dim))

    real_mean = np.asarray(calib["real_patient_feature_mean"], dtype=float)
    real_std = np.asarray(calib["real_patient_feature_std"], dtype=float)
    if len(real_mean) == patient_dim:
        X_patient = StandardScaler().fit_transform(X_patient)
        X_patient = X_patient * real_std + real_mean
    X_patient = standardize_np(X_patient).astype(np.float32)

    brain_score = (
        -0.85 * z_brain[:, 0]
        + 0.60 * z_brain[:, 1]
        - 0.40 * z_brain[:, 2]
        + 0.20 * np.sin(z_brain[:, 3])
        + rng.normal(0, 0.75, size=N)
    )
    brain_score = (brain_score - brain_score.mean()) / (brain_score.std() + 1e-8)

    # Species groups
    species = np.arange(S)
    rng.shuffle(species)
    n_high = max(D + 2, int(round(cfg.high_context_fraction * S)))
    n_med = max(D + 2, int(round(cfg.medium_context_fraction * S)))
    n_high = min(n_high, S - 2 * D)
    n_med = min(n_med, S - n_high - D)

    high_species = species[:n_high]
    medium_species = species[n_high:n_high + n_med]
    low_species = species[n_high + n_med:]
    if len(low_species) < D:
        low_species = species[-D:]

    species_groups = {"high": high_species, "medium": medium_species, "low": low_species}

    # Anchors
    n_anchor = int(round(cfg.anchor_fraction * N))
    anchor_idx = np.argsort(-brain_score)[:n_anchor]
    is_anchor = np.zeros(N, dtype=int)
    is_anchor[anchor_idx] = 1

    A = np.zeros((N, S), dtype=np.float32)

    # Anchor edges: mostly high-context species
    anchor_comp = {
        "high": min(cfg.anchor_high_edges, D),
        "medium": min(cfg.anchor_medium_edges, max(0, D - cfg.anchor_high_edges)),
        "low": max(0, D - cfg.anchor_high_edges - cfg.anchor_medium_edges),
    }
    A[anchor_idx] = assign_edges_by_composition(rng, anchor_idx, species_groups, anchor_comp, S, D)

    non_anchor_idx = np.setdiff1d(np.arange(N), anchor_idx)

    # Initial non-anchor edges: mixed
    neutral_comp = {"high": 2, "medium": 2, "low": max(0, D - 4)}
    A[non_anchor_idx] = assign_edges_by_composition(rng, non_anchor_idx, species_groups, neutral_comp, S, D)

    # Preliminary anchor density
    anchor_density, _ = compute_anchor_density(A, is_anchor, brain_score)
    second_order = (A @ anchor_density) / np.clip(A.sum(axis=1), 1.0, None)

    n_pos = int(round(cfg.risk_rate * N))
    n_rel_pos = int(round(cfg.relational_positive_fraction * n_pos))
    n_brain_pos = n_pos - n_rel_pos

    # Relational candidates: low-brain non-anchors
    low_brain_pool = np.where(brain_score < np.quantile(brain_score, cfg.target_low_brain_quantile))[0]
    low_brain_pool = np.setdiff1d(low_brain_pool, anchor_idx)

    # Force a stronger gap:
    # relational positives are wired to high-context species;
    # obvious negatives are wired to medium/low species.
    rel_pos_idx = pd.Series(second_order[low_brain_pool], index=low_brain_pool).sort_values(ascending=False).index.values[:n_rel_pos]
    brain_pos_idx = pd.Series(second_order[anchor_idx], index=anchor_idx).sort_values(ascending=False).index.values[:n_brain_pos]

    y = np.zeros(N, dtype=int)
    y[brain_pos_idx] = 1
    y[rel_pos_idx] = 1
    relational_only = np.zeros(N, dtype=int)
    relational_only[rel_pos_idx] = 1

    # Rewire relational positives to maximize second-order exposure.
    rel_comp = {
        "high": min(cfg.rel_high_edges, D),
        "medium": min(cfg.rel_medium_edges, max(0, D - cfg.rel_high_edges)),
        "low": max(0, D - cfg.rel_high_edges - cfg.rel_medium_edges),
    }
    A[rel_pos_idx] = assign_edges_by_composition(rng, rel_pos_idx, species_groups, rel_comp, S, D)

    # Rewire negatives to reduce exposure but include high decoys.
    neg_idx = np.where(y == 0)[0]
    neg_comp = {
        "high": min(cfg.neg_high_edges, D),
        "medium": min(cfg.neg_medium_edges, max(0, D - cfg.neg_high_edges)),
        "low": max(0, D - cfg.neg_high_edges - cfg.neg_medium_edges),
    }
    A[neg_idx] = assign_edges_by_composition(rng, neg_idx, species_groups, neg_comp, S, D)

    # Recompute true anchor-density score and reselect labels strictly by anchor density.
    anchor_density, species_context = compute_anchor_density(A, is_anchor, brain_score)
    second_order = (A @ anchor_density) / np.clip(A.sum(axis=1), 1.0, None)

    low_brain_pool = np.where(brain_score < np.quantile(brain_score, cfg.target_low_brain_quantile))[0]
    low_brain_pool = np.setdiff1d(low_brain_pool, anchor_idx)

    rel_pos_idx = pd.Series(second_order[low_brain_pool], index=low_brain_pool).sort_values(ascending=False).index.values[:n_rel_pos]
    brain_pos_idx = pd.Series(second_order[anchor_idx], index=anchor_idx).sort_values(ascending=False).index.values[:n_brain_pos]

    y = np.zeros(N, dtype=int)
    y[brain_pos_idx] = 1
    y[rel_pos_idx] = 1
    relational_only = np.zeros(N, dtype=int)
    relational_only[rel_pos_idx] = 1
    relational_only[brain_pos_idx] = 0

    # Leakage balancing while preserving degree. This reduces species identity leakage,
    # but does not erase the graph-position signal as aggressively as v4.
    A = balance_species_prevalence(A, y, cfg, rng)

    # Final second-order score after balancing
    anchor_density, species_context = compute_anchor_density(A, is_anchor, brain_score)
    second_order = (A @ anchor_density) / np.clip(A.sum(axis=1), 1.0, None)

    # Final labels: graph-position-defined again.
    low_brain_pool = np.where(brain_score < np.quantile(brain_score, cfg.target_low_brain_quantile))[0]
    low_brain_pool = np.setdiff1d(low_brain_pool, anchor_idx)
    rel_pos_idx = pd.Series(second_order[low_brain_pool], index=low_brain_pool).sort_values(ascending=False).index.values[:n_rel_pos]
    brain_pos_idx = pd.Series(second_order[anchor_idx], index=anchor_idx).sort_values(ascending=False).index.values[:n_brain_pos]

    y = np.zeros(N, dtype=int)
    y[brain_pos_idx] = 1
    y[rel_pos_idx] = 1
    relational_only = np.zeros(N, dtype=int)
    relational_only[rel_pos_idx] = 1
    relational_only[brain_pos_idx] = 0

    # Abundance: fixed and nearly useless for local summaries
    abundance = A * (
        cfg.constant_abundance
        + rng.normal(0, cfg.abundance_noise, size=A.shape)
        + 0.02 * (z_micro @ rng.normal(0, 0.03, size=(cfg.latent_dim, S)))
    )
    abundance = np.clip(abundance, 0.0, None)
    A_log = np.log1p(abundance).astype(np.float32)

    A_presence = (A > 0).astype(np.float32)
    A_norm = A_presence / np.clip(A_presence.sum(axis=1, keepdims=True), 1.0, None)

    A_rand = A_presence.copy()
    for s in range(S):
        rng.shuffle(A_rand[:, s])
    A_rand_norm = A_rand / np.clip(A_rand.sum(axis=1, keepdims=True), 1.0, None)

    # Local summary: degree fixed, abundance near-constant
    degree = A_presence.sum(axis=1)
    abund_sum = A_log.sum(axis=1)
    abund_mean = abund_sum / np.clip(degree, 1.0, None)
    abund_std = np.array([
        A_log[i, A_presence[i] > 0].std() if (A_presence[i] > 0).sum() > 1 else 0.0
        for i in range(N)
    ])
    entropy = []
    for i in range(N):
        vals = A_log[i].clip(min=0)
        p = vals / (vals.sum() + 1e-8)
        entropy.append(float(-(p * np.log(p + 1e-8)).sum()))

    X_micro_summary = standardize_np(np.vstack([degree, abund_sum, abund_mean, abund_std, np.asarray(entropy)]).T).astype(np.float32)
    X_micro_identity = standardize_np(A_log).astype(np.float32)

    X_early_summary = np.concatenate([X_patient, X_micro_summary], axis=1).astype(np.float32)
    X_early_identity = np.concatenate([X_patient, X_micro_identity], axis=1).astype(np.float32)

    selected_species = calib["selected_species"]
    high_set, med_set = set(high_species.tolist()), set(medium_species.tolist())
    species_rows = []
    for s in range(S):
        if s in high_set:
            group = "high_anchor_density_design"
        elif s in med_set:
            group = "medium_anchor_density_design"
        else:
            group = "low_anchor_density_design"
        prev_y1 = float(A_presence[y == 1, s].mean())
        prev_y0 = float(A_presence[y == 0, s].mean())
        species_rows.append({
            "seed": seed,
            "species_index": int(s),
            "species_name": selected_species[s] if s < len(selected_species) else f"species_{s}",
            "design_group": group,
            "anchor_density": float(anchor_density[s]),
            "context_score": float(species_context[s]),
            "prevalence_y1": prev_y1,
            "prevalence_y0": prev_y0,
            "abs_prev_diff": abs(prev_y1 - prev_y0),
        })

    return {
        "X_patient": X_patient.astype(np.float32),
        "X_micro_summary": X_micro_summary.astype(np.float32),
        "X_micro_identity": X_micro_identity.astype(np.float32),
        "X_early_summary": X_early_summary.astype(np.float32),
        "X_early_identity": X_early_identity.astype(np.float32),
        "A_norm": A_norm.astype(np.float32),
        "A_rand_norm": A_rand_norm.astype(np.float32),
        "A_presence": A_presence.astype(np.float32),
        "A_log": A_log.astype(np.float32),
        "y": y.astype(int),
        "is_anchor": is_anchor.astype(int),
        "relational_only": relational_only.astype(int),
        "brain_score": brain_score.astype(np.float32),
        "second_order_score": second_order.astype(np.float32),
        "species_context_score": species_context.astype(np.float32),
        "species_anchor_density": anchor_density.astype(np.float32),
        "species_info": pd.DataFrame(species_rows),
        "meta": {
            "seed": seed,
            "N": int(N),
            "S": int(S),
            "fixed_degree": int(D),
            "risk_count": int(y.sum()),
            "risk_rate": float(y.mean()),
            "relational_only_count": int(relational_only.sum()),
            "relational_only_rate": float(relational_only.mean()),
            "brain_positive_count": int(y.sum() - relational_only.sum()),
            "anchor_count": int(is_anchor.sum()),
            "anchor_fraction": float(is_anchor.mean()),
            "second_order_score_pos_mean": float(second_order[y == 1].mean()),
            "second_order_score_neg_mean": float(second_order[y == 0].mean()),
            "second_order_score_rel_mean": float(second_order[relational_only == 1].mean()) if relational_only.sum() else np.nan,
            "second_order_score_nonrel_mean": float(second_order[relational_only == 0].mean()),
        },
    }


# ============================================================
# 5. Diagnostics
# ============================================================

def cross_modal_cv_r2(A, B, seed=42, n_components=8, n_splits=5):
    n_comp = min(n_components, A.shape[1], B.shape[1], A.shape[0] - 2)
    A_p = PCA(n_components=n_comp, random_state=seed).fit_transform(standardize_np(A))
    B_p = PCA(n_components=n_comp, random_state=seed).fit_transform(standardize_np(B))

    idx = np.arange(A.shape[0])
    rng = np.random.default_rng(seed)
    rng.shuffle(idx)
    folds = np.array_split(idx, n_splits)

    def cv_score(X, Y):
        scores = []
        for te in folds:
            tr = np.setdiff1d(idx, te)
            model = Ridge(alpha=10.0)
            model.fit(X[tr], Y[tr])
            pred = model.predict(X[te])
            sse = ((Y[te] - pred) ** 2).sum()
            sst = ((Y[te] - Y[tr].mean(axis=0)) ** 2).sum()
            scores.append(1 - sse / (sst + 1e-8))
        return float(np.mean(scores))

    return cv_score(A_p, B_p), cv_score(B_p, A_p)


def cca_corrs(A, B, seed=42, n_components=3):
    A_s = standardize_np(A)
    B_s = standardize_np(B)
    A_p = PCA(n_components=min(12, A_s.shape[1], A_s.shape[0] - 2), random_state=seed).fit_transform(A_s)
    B_p = PCA(n_components=min(12, B_s.shape[1], B_s.shape[0] - 2), random_state=seed).fit_transform(B_s)
    n_comp = min(n_components, A_p.shape[1], B_p.shape[1])
    cca = CCA(n_components=n_comp, max_iter=3000)
    U, V = cca.fit_transform(A_p, B_p)
    return [float(np.corrcoef(U[:, i], V[:, i])[0, 1]) for i in range(n_comp)]


def neighbor_overlap(A, B, ks=(5, 10, 20)):
    A_s = standardize_np(A)
    B_s = standardize_np(B)
    out = {}
    for k in ks:
        k_eff = min(k, A.shape[0] - 1)
        nn_a = NearestNeighbors(n_neighbors=k_eff + 1).fit(A_s).kneighbors(A_s, return_distance=False)[:, 1:]
        nn_b = NearestNeighbors(n_neighbors=k_eff + 1).fit(B_s).kneighbors(B_s, return_distance=False)[:, 1:]
        vals = []
        for i in range(A.shape[0]):
            vals.append(len(set(nn_a[i]).intersection(set(nn_b[i]))) / k_eff)
        out[f"neighbor_overlap@{k}"] = float(np.mean(vals))
    return out


def run_diagnostics(data, seed):
    b2m, m2b = cross_modal_cv_r2(data["X_patient"], data["X_micro_identity"], seed=seed)
    cca = cca_corrs(data["X_patient"], data["X_micro_identity"], seed=seed)

    pres = data["A_presence"]
    y = data["y"]
    pos_prev = pres[y == 1].mean(axis=0)
    neg_prev = pres[y == 0].mean(axis=0)
    diff = np.abs(pos_prev - neg_prev)

    local_signal = {}
    for j, name in enumerate(["degree", "sum", "mean", "std", "entropy"]):
        try:
            rho, _ = spearmanr(data["X_micro_summary"][:, j], y)
        except Exception:
            rho = np.nan
        local_signal[f"spearman_local_{name}_vs_y"] = float(rho) if np.isfinite(rho) else np.nan

    rho_brain_second, _ = spearmanr(data["brain_score"], data["second_order_score"])
    rho_y_second, _ = spearmanr(y, data["second_order_score"])

    rel = data["relational_only"] == 1
    non_rel = data["relational_only"] == 0
    rel_gap = float(data["second_order_score"][rel].mean() - data["second_order_score"][non_rel].mean()) if rel.sum() else np.nan

    return {
        "seed": seed,
        "brain_to_micro_cv_r2": b2m,
        "micro_to_brain_cv_r2": m2b,
        "cca_1": cca[0] if len(cca) > 0 else np.nan,
        "cca_2": cca[1] if len(cca) > 1 else np.nan,
        "cca_3": cca[2] if len(cca) > 2 else np.nan,
        **neighbor_overlap(data["X_patient"], data["X_micro_identity"]),
        "spearman_brain_vs_second_order_score": float(rho_brain_second),
        "spearman_y_vs_second_order_score": float(rho_y_second),
        "max_abs_species_prevalence_diff": float(np.max(diff)),
        "mean_abs_species_prevalence_diff": float(np.mean(diff)),
        "median_abs_species_prevalence_diff": float(np.median(diff)),
        "second_order_score_gap_relational_vs_other": rel_gap,
        **local_signal,
    }


# ============================================================
# 6. Models
# ============================================================

class FocalLossBinary(nn.Module):
    def __init__(self, alpha_pos=0.72, gamma=2.0):
        super().__init__()
        self.alpha_pos = alpha_pos
        self.gamma = gamma

    def forward(self, logits, target):
        target = target.float()
        bce = F.binary_cross_entropy_with_logits(logits, target, reduction="none")
        prob = torch.sigmoid(logits)
        pt = torch.where(target == 1, prob, 1 - prob)
        alpha = torch.where(
            target == 1,
            torch.tensor(self.alpha_pos, device=logits.device),
            torch.tensor(1 - self.alpha_pos, device=logits.device),
        )
        return (alpha * (1 - pt).pow(self.gamma) * bce).mean()


class MLPBinary(nn.Module):
    def __init__(self, in_dim, hidden_dim=96, dropout=0.35):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden_dim),
            nn.BatchNorm1d(hidden_dim),
            nn.ReLU(),
            nn.Dropout(dropout),
            nn.Linear(hidden_dim, hidden_dim // 2),
            nn.BatchNorm1d(hidden_dim // 2),
            nn.ReLU(),
            nn.Dropout(dropout),
            nn.Linear(hidden_dim // 2, 1),
        )

    def forward(self, x):
        return self.net(x).squeeze(-1)


class SecondOrderHGNN(nn.Module):
    def __init__(self, patient_dim, n_species, hidden_dim=96, latent_dim=32, dropout=0.35, use_gaussian=False):
        super().__init__()
        self.use_gaussian = use_gaussian
        self.patient_proj = nn.Linear(patient_dim, hidden_dim)
        self.species_emb = nn.Parameter(torch.randn(n_species, hidden_dim) * 0.03)

        self.species_update = nn.Sequential(
            nn.Linear(hidden_dim * 2, hidden_dim),
            nn.ReLU(),
            nn.Dropout(dropout),
        )

        self.patient_update = nn.Sequential(
            nn.Linear(hidden_dim * 3, hidden_dim),
            nn.ReLU(),
            nn.Dropout(dropout),
        )

        self.context_gate = nn.Sequential(
            nn.Linear(hidden_dim, hidden_dim),
            nn.ReLU(),
            nn.Linear(hidden_dim, hidden_dim),
            nn.Sigmoid(),
        )

        if use_gaussian:
            self.mu = nn.Linear(hidden_dim, latent_dim)
            self.logvar = nn.Linear(hidden_dim, latent_dim)
        else:
            self.det = nn.Linear(hidden_dim, latent_dim)

        self.classifier = nn.Sequential(
            nn.Linear(latent_dim, hidden_dim // 2),
            nn.ReLU(),
            nn.Dropout(dropout),
            nn.Linear(hidden_dim // 2, 1),
        )

    def forward(self, x_patient, A_ps):
        h_p = F.relu(self.patient_proj(x_patient))
        h_s0 = self.species_emb

        # patient -> species: species learns neighboring patients' brain context
        A_sp = A_ps.t()
        deg_s = A_sp.sum(dim=1, keepdim=True).clamp(min=1.0)
        msg_s = (A_sp @ h_p) / deg_s
        h_s = self.species_update(torch.cat([h_s0, msg_s], dim=1))

        # species -> patient: target patient receives contextualized species signal
        msg_p = A_ps @ h_s
        gated = msg_p * self.context_gate(msg_p)
        h = self.patient_update(torch.cat([h_p, msg_p, gated], dim=1))

        if self.use_gaussian:
            mu = self.mu(h)
            logvar = self.logvar(h).clamp(-8, 6)
            if self.training:
                eps = torch.randn_like(mu)
                z = mu + torch.exp(0.5 * logvar) * eps
            else:
                z = mu
            kl = -0.5 * torch.mean(torch.sum(1 + logvar - mu.pow(2) - logvar.exp(), dim=1))
        else:
            z = self.det(h)
            mu = z
            kl = torch.tensor(0.0, device=x_patient.device)

        logits = self.classifier(z).squeeze(-1)
        return logits, kl, mu


# ============================================================
# 7. Training / evaluation
# ============================================================

def fit_sklearn_model(model, X, y, train_idx, val_idx, test_idx, cfg: Config):
    imp = SimpleImputer(strategy="median")
    scaler = StandardScaler()

    X_train = scaler.fit_transform(imp.fit_transform(X[train_idx]))
    X_val = scaler.transform(imp.transform(X[val_idx]))
    X_test = scaler.transform(imp.transform(X[test_idx]))

    model.fit(X_train, y[train_idx])
    p_val = model.predict_proba(X_val)[:, 1]
    p_test = model.predict_proba(X_test)[:, 1]
    th = choose_threshold(y[val_idx], p_val, cfg)
    pred = (p_test >= th).astype(int)
    return p_test, pred, th


def fit_mlp_model(X, y, train_idx, val_idx, test_idx, cfg: Config, seed: int):
    set_seed(seed)
    dev = get_device(cfg)

    imp = SimpleImputer(strategy="median")
    scaler = StandardScaler()
    X_train = scaler.fit_transform(imp.fit_transform(X[train_idx]))
    X_val = scaler.transform(imp.transform(X[val_idx]))
    X_test = scaler.transform(imp.transform(X[test_idx]))

    xt = torch.tensor(X_train, dtype=torch.float32, device=dev)
    xv = torch.tensor(X_val, dtype=torch.float32, device=dev)
    xe = torch.tensor(X_test, dtype=torch.float32, device=dev)
    yt = torch.tensor(y[train_idx], dtype=torch.float32, device=dev)
    yv = torch.tensor(y[val_idx], dtype=torch.float32, device=dev)

    model = MLPBinary(X_train.shape[1], cfg.hidden_dim, cfg.dropout).to(dev)
    opt = torch.optim.AdamW(model.parameters(), lr=cfg.lr, weight_decay=cfg.weight_decay)
    criterion = FocalLossBinary(cfg.alpha_pos, cfg.gamma)

    best_state, best_val, bad = None, np.inf, 0
    for epoch in range(cfg.epochs):
        model.train()
        opt.zero_grad()
        loss = criterion(model(xt), yt)
        loss.backward()
        torch.nn.utils.clip_grad_norm_(model.parameters(), 5.0)
        opt.step()

        model.eval()
        with torch.no_grad():
            val_loss = criterion(model(xv), yv).item()

        if val_loss < best_val:
            best_val = val_loss
            best_state = {k: v.detach().cpu().clone() for k, v in model.state_dict().items()}
            bad = 0
        else:
            bad += 1
            if bad >= cfg.patience:
                break

    if best_state is not None:
        model.load_state_dict({k: v.to(dev) for k, v in best_state.items()})

    model.eval()
    with torch.no_grad():
        p_val = torch.sigmoid(model(xv)).detach().cpu().numpy()
        p_test = torch.sigmoid(model(xe)).detach().cpu().numpy()

    th = choose_threshold(y[val_idx], p_val, cfg)
    pred = (p_test >= th).astype(int)
    return p_test, pred, th


def train_hgnn_and_return_probs(X_patient, A_norm, y, train_idx, val_idx, test_idx, cfg: Config, seed: int, use_gaussian=False, beta=0.0):
    set_seed(seed)
    dev = get_device(cfg)

    X_scaled = standardize_np(X_patient).astype(np.float32)
    x = torch.tensor(X_scaled, dtype=torch.float32, device=dev)
    A = torch.tensor(A_norm, dtype=torch.float32, device=dev)
    yt = torch.tensor(y, dtype=torch.float32, device=dev)

    train_t = torch.tensor(train_idx, dtype=torch.long, device=dev)
    val_t = torch.tensor(val_idx, dtype=torch.long, device=dev)

    model = SecondOrderHGNN(
        patient_dim=X_patient.shape[1],
        n_species=A_norm.shape[1],
        hidden_dim=cfg.hidden_dim,
        latent_dim=cfg.latent_dim_model,
        dropout=cfg.dropout,
        use_gaussian=use_gaussian,
    ).to(dev)

    opt = torch.optim.AdamW(model.parameters(), lr=cfg.lr, weight_decay=cfg.weight_decay)
    criterion = FocalLossBinary(cfg.alpha_pos, cfg.gamma)

    best_state, best_val, bad = None, np.inf, 0
    for epoch in range(cfg.epochs):
        model.train()
        opt.zero_grad()
        logits, kl, _ = model(x, A)
        loss = criterion(logits[train_t], yt[train_t])
        if use_gaussian and beta > 0:
            loss = loss + beta * kl
        loss.backward()
        torch.nn.utils.clip_grad_norm_(model.parameters(), 5.0)
        opt.step()

        model.eval()
        with torch.no_grad():
            logits_v, kl_v, _ = model(x, A)
            val_loss = criterion(logits_v[val_t], yt[val_t])
            if use_gaussian and beta > 0:
                val_loss = val_loss + beta * kl_v
            val_loss = float(val_loss.item())

        if val_loss < best_val:
            best_val = val_loss
            best_state = {k: v.detach().cpu().clone() for k, v in model.state_dict().items()}
            bad = 0
        else:
            bad += 1
            if bad >= cfg.patience:
                break

    if best_state is not None:
        model.load_state_dict({k: v.to(dev) for k, v in best_state.items()})

    model.eval()
    with torch.no_grad():
        logits_all, _, emb = model(x, A)
        p_all = torch.sigmoid(logits_all).detach().cpu().numpy()

    p_val = p_all[val_idx]
    p_test = p_all[test_idx]
    th = choose_threshold(y[val_idx], p_val, cfg)
    pred_test = (p_test >= th).astype(int)
    val_pred = (p_val >= th).astype(int)
    val_metrics = binary_metrics(y[val_idx], p_val, pred=val_pred)

    return {
        "p_test": p_test,
        "pred_test": pred_test,
        "threshold": th,
        "p_val": p_val,
        "val_metrics": val_metrics,
        "p_all": p_all,
        "embedding": emb.detach().cpu().numpy(),
        "epochs_used": epoch + 1,
        "best_val_loss": best_val,
    }


def tune_beta_vgib(X_patient, A_norm, y, train_idx, val_idx, test_idx, cfg: Config, seed: int):
    rows = []
    best = None

    for beta in cfg.beta_grid:
        result = train_hgnn_and_return_probs(
            X_patient, A_norm, y, train_idx, val_idx, test_idx,
            cfg, seed + int(beta * 1e7) + 777,
            use_gaussian=True,
            beta=float(beta),
        )
        vm = result["val_metrics"]
        row = {
            "seed": seed,
            "beta": float(beta),
            "val_auc": vm["auc"],
            "val_pr_auc": vm["pr_auc"],
            "val_risk_recall": vm["risk_recall"],
            "val_risk_precision": vm["risk_precision"],
            "val_risk_f1": vm["risk_f1"],
            "threshold": result["threshold"],
            "best_val_loss": result["best_val_loss"],
            "epochs_used": result["epochs_used"],
        }
        rows.append(row)

        # Selection criterion: validation Risk F1, then PR-AUC, then AUC.
        key = (vm["risk_f1"], vm["pr_auc"], vm["auc"])
        if best is None or key > best["key"]:
            best = {"key": key, "beta": float(beta), "result": result}

    return best["beta"], best["result"], pd.DataFrame(rows)


def evaluate_one_seed(data, cfg: Config, seed: int):
    y = data["y"]
    train_idx, val_idx, test_idx = split_indices(y, seed)

    rows = []
    beta_tuning_rows = []

    def add_row(model_name, p_test, pred, th, seconds, extra=None):
        m = binary_metrics(y[test_idx], p_test, pred=pred)
        rel_mask = data["relational_only"][test_idx] == 1
        brain_pos_mask = (y[test_idx] == 1) & (data["relational_only"][test_idx] == 0)
        anchor_mask = data["is_anchor"][test_idx] == 1

        m.update({
            "seed": seed,
            "model": model_name,
            "threshold": th,
            "seconds": seconds,
            "relational_only_recall": float(pred[rel_mask].mean()) if rel_mask.sum() else np.nan,
            "relational_only_n_test": int(rel_mask.sum()),
            "brain_positive_recall": float(pred[brain_pos_mask].mean()) if brain_pos_mask.sum() else np.nan,
            "anchor_predicted_risk_rate": float(pred[anchor_mask].mean()) if anchor_mask.sum() else np.nan,
        })
        if extra:
            m.update(extra)
        rows.append(m)

    # Main baselines
    sklearn_specs = [
        ("LogReg-BrainOnly", LogisticRegression(max_iter=2500, class_weight="balanced"), data["X_patient"]),
        ("LogReg-LocalMicroSummary", LogisticRegression(max_iter=2500, class_weight="balanced"), data["X_micro_summary"]),
        ("LogReg-EarlyFusionLocalSummary", LogisticRegression(max_iter=2500, class_weight="balanced"), data["X_early_summary"]),
        ("RF-BrainOnly", RandomForestClassifier(n_estimators=500, random_state=seed, class_weight="balanced_subsample", min_samples_leaf=2), data["X_patient"]),
        ("RF-LocalMicroSummary", RandomForestClassifier(n_estimators=500, random_state=seed, class_weight="balanced_subsample", min_samples_leaf=2), data["X_micro_summary"]),
        ("RF-EarlyFusionLocalSummary", RandomForestClassifier(n_estimators=500, random_state=seed, class_weight="balanced_subsample", min_samples_leaf=2), data["X_early_summary"]),
    ]

    # Diagnostic identity baselines
    sklearn_specs += [
        ("DIAGNOSTIC-LogReg-EarlyFusionSpeciesIdentity", LogisticRegression(max_iter=2500, class_weight="balanced"), data["X_early_identity"]),
        ("DIAGNOSTIC-RF-EarlyFusionSpeciesIdentity", RandomForestClassifier(n_estimators=500, random_state=seed, class_weight="balanced_subsample", min_samples_leaf=2), data["X_early_identity"]),
    ]

    for name, model, X in sklearn_specs:
        t0 = time.time()
        p, pred, th = fit_sklearn_model(model, X, y, train_idx, val_idx, test_idx, cfg)
        add_row(name, p, pred, th, time.time() - t0)

    mlp_specs = [
        ("MLP-Focal-BrainOnly", data["X_patient"]),
        ("MLP-Focal-LocalMicroSummary", data["X_micro_summary"]),
        ("MLP-Focal-EarlyFusionLocalSummary", data["X_early_summary"]),
        ("DIAGNOSTIC-MLP-Focal-EarlyFusionSpeciesIdentity", data["X_early_identity"]),
    ]

    for name, X in mlp_specs:
        t0 = time.time()
        p, pred, th = fit_mlp_model(X, y, train_idx, val_idx, test_idx, cfg, seed)
        add_row(name, p, pred, th, time.time() - t0)

    # Graph baselines
    graph_specs = [
        ("HGNN-Focal-RandomizedEdges", data["A_rand_norm"], False, 0.0),
        ("HGNN-Focal-RealEdges", data["A_norm"], False, 0.0),
        ("HGNN-Gaussian-Focal-RealEdges", data["A_norm"], True, 0.0),
    ]

    for name, A_mat, use_g, beta in graph_specs:
        t0 = time.time()
        result = train_hgnn_and_return_probs(
            data["X_patient"], A_mat, y, train_idx, val_idx, test_idx,
            cfg, seed, use_gaussian=use_g, beta=beta
        )
        add_row(name, result["p_test"], result["pred_test"], result["threshold"], time.time() - t0, extra={"beta": beta})

    # Tuned VGIB
    t0 = time.time()
    selected_beta, result, beta_df = tune_beta_vgib(
        data["X_patient"], data["A_norm"], y, train_idx, val_idx, test_idx, cfg, seed
    )
    beta_df["selected_beta"] = selected_beta
    beta_tuning_rows.append(beta_df)

    add_row(
        "VGIB-HGNN-Focal-TunedBeta-Proposed",
        result["p_test"],
        result["pred_test"],
        result["threshold"],
        time.time() - t0,
        extra={"beta": selected_beta}
    )

    return pd.DataFrame(rows), pd.concat(beta_tuning_rows, ignore_index=True)


# ============================================================
# 8. Summary and bootstrap
# ============================================================

def summarize_mean_std(df: pd.DataFrame):
    metrics = [
        "auc", "pr_auc", "risk_recall", "risk_precision", "risk_f1",
        "macro_f1", "balanced_acc", "predicted_risk_rate",
        "relational_only_recall", "brain_positive_recall",
        "anchor_predicted_risk_rate", "seconds"
    ]
    rows = []
    for model, sub in df.groupby("model"):
        row = {"model": model}
        for c in metrics:
            row[c + "_mean"] = float(sub[c].mean())
            row[c + "_std"] = float(sub[c].std(ddof=0))
            row[c + "_mean_std"] = f"{sub[c].mean():.3f} ± {sub[c].std(ddof=0):.3f}"
        if "beta" in sub.columns:
            row["beta_selected_or_used_mean"] = float(pd.to_numeric(sub["beta"], errors="coerce").mean())
        rows.append(row)
    return pd.DataFrame(rows).sort_values("risk_f1_mean", ascending=False)


def paired_seed_bootstrap(df: pd.DataFrame, proposed="VGIB-HGNN-Focal-TunedBeta-Proposed"):
    metrics = ["auc", "pr_auc", "risk_recall", "risk_precision", "risk_f1", "relational_only_recall", "brain_positive_recall"]
    baselines = [m for m in df["model"].unique() if m != proposed]
    rng = np.random.default_rng(42)
    rows = []

    for b in baselines:
        for metric in metrics:
            pivot = df.pivot_table(index="seed", columns="model", values=metric)
            if proposed not in pivot.columns or b not in pivot.columns:
                continue
            common = pivot[[proposed, b]].dropna()
            if len(common) < 2:
                continue
            av = common[proposed].values
            bv = common[b].values
            n = len(av)
            diffs = []
            for _ in range(5000):
                idx = rng.integers(0, n, size=n)
                diffs.append((av[idx] - bv[idx]).mean())
            diffs = np.asarray(diffs)
            rows.append({
                "model_A": proposed,
                "model_B": b,
                "metric": metric,
                "mean_diff_A_minus_B": float((av - bv).mean()),
                "ci_lower": float(np.quantile(diffs, 0.025)),
                "ci_upper": float(np.quantile(diffs, 0.975)),
                "p_two_sided": float(min(1.0, 2 * min((diffs <= 0).mean(), (diffs >= 0).mean()))),
                "n_seeds": int(n),
            })
    return pd.DataFrame(rows)


# ============================================================
# 9. Main
# ============================================================

def main(cfg: Config = CFG):
    ensure_dir(cfg.output_dir)

    with open(os.path.join(cfg.output_dir, "00_config.json"), "w", encoding="utf-8") as f:
        json.dump(asdict(cfg), f, indent=2, ensure_ascii=False)

    basic, micro, brain, merged = load_real_data_for_calibration(cfg)
    calib = build_calibration(merged, micro, cfg)

    pd.DataFrame([{
        "real_N": calib["real_N"],
        "synthetic_N": calib["synthetic_N"],
        "patient_dim": calib["patient_dim"],
        "basic_dim": calib["basic_dim"],
        "brain_dim": calib["brain_dim"],
        "n_species": calib["n_species"],
        "real_risk_rate": calib["real_risk_rate"],
        "synthetic_risk_rate": cfg.risk_rate,
        "fixed_degree": cfg.fixed_degree,
        "threshold_policy": cfg.threshold_policy,
        "beta_grid": str(cfg.beta_grid),
    }]).to_csv(os.path.join(cfg.output_dir, "00_real_calibration_inventory.csv"), index=False, encoding="utf-8-sig")

    pd.DataFrame({
        "species_index": np.arange(len(calib["selected_species"])),
        "species_name": calib["selected_species"],
        "real_prevalence": calib["species_prevalence"],
        "real_mean_positive_abundance": calib["species_mean_positive"],
    }).to_csv(os.path.join(cfg.output_dir, "00_selected_species_from_real_data.csv"), index=False, encoding="utf-8-sig")

    print("Running tuned-β second-order benchmark on:", get_device(cfg))
    print("Threshold policy:", cfg.threshold_policy)
    print("Beta grid:", cfg.beta_grid)

    all_perf = []
    all_diag = []
    all_meta = []
    all_species = []
    all_beta = []

    for seed in cfg.seeds:
        print(f"\n================ Seed {seed} ================")
        data = generate_tuned_beta_synthetic(calib, cfg, seed)
        diag = run_diagnostics(data, seed)
        perf, beta_df = evaluate_one_seed(data, cfg, seed)

        print("\nDiagnostics:")
        for k, v in diag.items():
            if k != "seed":
                print(f"  {k}: {v:.4f}" if isinstance(v, float) and np.isfinite(v) else f"  {k}: {v}")

        show_cols = ["model", "auc", "pr_auc", "risk_recall", "risk_precision", "risk_f1", "relational_only_recall"]
        print("\nPerformance:")
        print(perf[show_cols].sort_values("risk_f1", ascending=False).to_string(index=False))

        all_perf.append(perf)
        all_diag.append(pd.DataFrame([diag]))
        all_meta.append(pd.DataFrame([data["meta"]]))
        all_species.append(data["species_info"])
        all_beta.append(beta_df)

    perf_df = pd.concat(all_perf, ignore_index=True)
    diag_df = pd.concat(all_diag, ignore_index=True)
    meta_df = pd.concat(all_meta, ignore_index=True)
    species_df = pd.concat(all_species, ignore_index=True)
    beta_df = pd.concat(all_beta, ignore_index=True)

    summary_df = summarize_mean_std(perf_df)
    boot_df = paired_seed_bootstrap(perf_df)

    save_csv(perf_df, os.path.join(cfg.output_dir, "RQ4_tuned_beta_all_seed_performance.csv"))
    save_csv(summary_df, os.path.join(cfg.output_dir, "RQ4_tuned_beta_summary_mean_std.csv"))
    save_csv(diag_df, os.path.join(cfg.output_dir, "RQ4_tuned_beta_diagnostics_by_seed.csv"))
    save_csv(pd.DataFrame([diag_df.drop(columns=["seed"]).mean(numeric_only=True).to_dict()]), os.path.join(cfg.output_dir, "RQ4_tuned_beta_diagnostics_summary.csv"))
    save_csv(meta_df, os.path.join(cfg.output_dir, "RQ4_tuned_beta_meta_by_seed.csv"))
    save_csv(species_df, os.path.join(cfg.output_dir, "RQ4_tuned_beta_species_context_info.csv"))
    save_csv(beta_df, os.path.join(cfg.output_dir, "RQ4_tuned_beta_grid_results.csv"))
    save_csv(boot_df, os.path.join(cfg.output_dir, "RQ4_tuned_beta_paired_bootstrap_over_seeds.csv"))

    print("\n================ FINAL SUMMARY ================")
    print(summary_df[[
        "model",
        "auc_mean_std", "pr_auc_mean_std", "risk_recall_mean_std",
        "risk_precision_mean_std", "risk_f1_mean_std", "relational_only_recall_mean_std"
    ]].to_string(index=False))

    print("\nOutputs saved to:", cfg.output_dir)
    print("Key files:")
    print("  - RQ4_tuned_beta_summary_mean_std.csv")
    print("  - RQ4_tuned_beta_diagnostics_summary.csv")
    print("  - RQ4_tuned_beta_grid_results.csv")
    print("  - RQ4_tuned_beta_paired_bootstrap_over_seeds.csv")
    print("  - RQ4_tuned_beta_all_seed_performance.csv")


if __name__ == "__main__":
    main(CFG)

"""# **synthetic benchmark_v4**"""

# ============================================================
# ICDM RQ4 Synthetic Benchmark v4
# Balanced Second-Order Graph-Position High-Risk Recovery
#
# Fixes requested:
#   修正 1：進一步壓低 species identity leakage
#   修正 2：讓 local summary 不含 second-order proxy
#   修正 3：讓 label 完全由「species anchor density」決定，但 species identity 平衡
#
# Core design
# -----------
# The high-risk signal is NOT a function of each patient's own microbiome
# species identity alone. Instead, it is generated from:
#
#   patient -> species -> brain-vulnerable anchor patients
#
# For each species s:
#   anchor_density(s) = # anchor patients connected to s / # all patients connected to s
#
# For each patient i:
#   second_order_score(i) = mean anchor_density(s) over species connected to i
#
# Relational-only high-risk patients are low-brain-score patients with high
# second_order_score. This means their high-risk status is determined by
# graph position, not by their own brain features.
#
# Leakage control
# ---------------
# 1. All patients have FIXED graph degree D. Therefore local summaries such as
#    degree, abundance sum, mean abundance, entropy are almost constant/noisy.
# 2. We balance species prevalence between y=1 and y=0 by adding/removing
#    decoy edges while preserving fixed degree.
# 3. Diagnostic species-identity baselines are included. If they are still too
#    strong, inspect max_abs_species_prevalence_diff and
#    mean_abs_species_prevalence_diff.
#
# Expected Colab files
# --------------------
#   /content/data.csv
#   /content/micro.csv
#   /content/all_brain_result_1(3).csv
#
# Output folder
# -------------
#   /content/icdm_second_order_balanced_outputs/
#
# Colab command
# -------------
#   !python icdm_second_order_balanced_synthetic_benchmark.py
#
# Dependencies
# ------------
#   pip install -q numpy pandas scikit-learn scipy torch
#
# No torch-geometric is required.
# ============================================================

import os
import re
import json
import time
import random
import warnings
from dataclasses import dataclass, asdict
from typing import Dict, List, Tuple

import numpy as np
import pandas as pd

from sklearn.impute import SimpleImputer
from sklearn.preprocessing import StandardScaler
from sklearn.model_selection import train_test_split
from sklearn.metrics import (
    roc_auc_score,
    average_precision_score,
    f1_score,
    recall_score,
    precision_score,
    balanced_accuracy_score,
    accuracy_score,
    brier_score_loss,
)
from sklearn.linear_model import LogisticRegression, Ridge
from sklearn.ensemble import RandomForestClassifier
from sklearn.decomposition import PCA
from sklearn.cross_decomposition import CCA
from sklearn.neighbors import NearestNeighbors

from scipy.stats import spearmanr

import torch
import torch.nn as nn
import torch.nn.functional as F

warnings.filterwarnings("ignore")


# ============================================================
# 1. Config
# ============================================================

@dataclass
class Config:
    # Real-data paths
    basic_path: str = "/content/data.csv"
    micro_path: str = "/content/micro.csv"
    brain_path: str = "/content/all_brain_result_1(3).csv"
    output_dir: str = "/content/icdm_second_order_balanced_outputs"

    id_col_brain: str = "Subject_ID"
    label_col: str = "Diagnosis"

    # Real calibration
    top_k_species: int = 50
    min_prevalence: float = 0.02
    n_patients_min: int = 760

    # Synthetic repetitions
    seeds: Tuple[int, ...] = (11, 22, 33, 44, 55, 66, 77)

    # Target proportions
    risk_rate: float = 0.24
    relational_positive_fraction: float = 0.62
    brain_positive_fraction: float = 0.38

    # Weak alignment controls
    latent_dim: int = 8
    cross_modal_leakage: float = 0.015
    brain_noise: float = 1.25
    micro_noise: float = 0.75

    # Graph generation
    fixed_degree: int = 6
    anchor_fraction: float = 0.22
    target_low_brain_quantile: float = 0.60

    # Species groups for anchor density
    high_context_fraction: float = 0.36
    medium_context_fraction: float = 0.34

    # Anchor edges create species anchor density.
    anchor_high_edges: int = 4
    anchor_medium_edges: int = 2

    # Relational target edge composition before balancing.
    rel_high_edges: int = 4
    rel_medium_edges: int = 1
    rel_low_edges: int = 1

    # Negative edge composition before balancing.
    neg_high_edges: int = 2
    neg_medium_edges: int = 2
    neg_low_edges: int = 2

    # Prevalence balancing
    balance_iterations: int = 6
    target_max_species_prev_diff: float = 0.075
    target_mean_species_prev_diff: float = 0.025
    hard_balance_top_species: bool = True

    # Local summary design:
    # Keep abundance nearly constant so local summaries cannot proxy graph position.
    constant_abundance: float = 1.0
    abundance_noise: float = 0.015

    # Training
    hidden_dim: int = 96
    latent_dim_model: int = 32
    dropout: float = 0.35
    lr: float = 2e-3
    weight_decay: float = 1e-4
    epochs: int = 420
    patience: int = 65

    # Focal / VGIB
    gamma: float = 2.0
    alpha_pos: float = 0.72
    beta: float = 5e-4

    # Threshold
    precision_floor: float = 0.50
    threshold_grid_size: int = 181

    # Device
    use_cuda_if_available: bool = True


CFG = Config()

# Local fallback for sandbox / local testing
if os.path.exists("/mnt/data/data.csv"):
    CFG.basic_path = "/mnt/data/data.csv"
    CFG.micro_path = "/mnt/data/micro.csv"
    CFG.brain_path = "/mnt/data/all_brain_result_1(3).csv"
    CFG.output_dir = "/mnt/data/icdm_second_order_balanced_outputs"


# ============================================================
# 2. Utilities
# ============================================================

def set_seed(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    torch.cuda.manual_seed_all(seed)


def get_device(cfg: Config):
    return torch.device("cuda" if cfg.use_cuda_if_available and torch.cuda.is_available() else "cpu")


def ensure_dir(path: str):
    os.makedirs(path, exist_ok=True)


def save_csv(df: pd.DataFrame, path: str):
    df.to_csv(path, index=False, encoding="utf-8-sig")
    print("Saved:", path)


def extract_tpmic_id(x):
    m = re.search(r"TPMIC\d+", str(x))
    return m.group(0) if m else None


def replace_missing_codes(df: pd.DataFrame):
    return df.replace([999, 999.0, "999", "999.0", "NA", "N/A", "", "nan", "None"], np.nan)


def encode_sex_like(series: pd.Series):
    if pd.api.types.is_numeric_dtype(series):
        return pd.to_numeric(series, errors="coerce")
    mapping = {
        "m": 1, "male": 1, "man": 1, "男": 1, "男性": 1, "1": 1,
        "f": 0, "female": 0, "woman": 0, "女": 0, "女性": 0, "0": 0,
    }
    return series.astype(str).str.strip().str.lower().map(mapping)


def safe_numeric(df: pd.DataFrame):
    out = df.copy()
    for c in out.columns:
        if c.lower() in ["sex", "gender"]:
            out[c] = encode_sex_like(out[c])
        else:
            out[c] = pd.to_numeric(out[c], errors="coerce")
    return out


def standardize_np(X):
    X = pd.DataFrame(X).replace([np.inf, -np.inf], np.nan)
    X = SimpleImputer(strategy="median").fit_transform(X)
    return StandardScaler().fit_transform(X)


def choose_threshold(y_val, prob_val, cfg: Config, policy="max_recall_precision_floor"):
    y_val = np.asarray(y_val).astype(int)
    prob_val = np.asarray(prob_val).astype(float)
    candidates = np.linspace(0.02, 0.98, cfg.threshold_grid_size)

    best_t, best_tuple = 0.5, None
    for t in candidates:
        pred = (prob_val >= t).astype(int)
        rec = recall_score(y_val, pred, zero_division=0)
        prec = precision_score(y_val, pred, zero_division=0)
        f1 = f1_score(y_val, pred, zero_division=0)
        mf1 = f1_score(y_val, pred, average="macro", zero_division=0)

        if policy == "max_recall_precision_floor":
            if prec >= cfg.precision_floor:
                score_tuple = (rec, f1, prec)
            else:
                score_tuple = (-1, f1, prec)
        elif policy == "max_risk_f1":
            score_tuple = (f1, rec, prec)
        else:
            score_tuple = (mf1, f1, rec)

        if best_tuple is None or score_tuple > best_tuple:
            best_tuple = score_tuple
            best_t = t

    if best_tuple is not None and best_tuple[0] < 0:
        return choose_threshold(y_val, prob_val, cfg, policy="max_risk_f1")
    return float(best_t)


def binary_metrics(y_true, prob, pred=None, threshold=0.5):
    y_true = np.asarray(y_true).astype(int)
    prob = np.asarray(prob).astype(float)
    if pred is None:
        pred = (prob >= threshold).astype(int)

    out = {
        "auc": np.nan,
        "pr_auc": np.nan,
        "risk_recall": recall_score(y_true, pred, zero_division=0),
        "risk_precision": precision_score(y_true, pred, zero_division=0),
        "risk_f1": f1_score(y_true, pred, zero_division=0),
        "macro_f1": f1_score(y_true, pred, average="macro", zero_division=0),
        "balanced_acc": balanced_accuracy_score(y_true, pred),
        "acc": accuracy_score(y_true, pred),
        "predicted_risk_rate": float(np.mean(pred == 1)),
        "brier": np.nan,
    }
    if len(np.unique(y_true)) == 2:
        out["auc"] = roc_auc_score(y_true, prob)
        out["pr_auc"] = average_precision_score(y_true, prob)
        out["brier"] = brier_score_loss(y_true, np.clip(prob, 1e-6, 1 - 1e-6))
    return out


def split_indices(y, seed):
    idx = np.arange(len(y))
    train_val, test = train_test_split(idx, test_size=0.25, stratify=y, random_state=seed)
    train, val = train_test_split(train_val, test_size=0.22, stratify=y[train_val], random_state=seed + 100)
    return train, val, test


def sample_without_replacement(rng, pool, k):
    pool = np.asarray(pool, dtype=int)
    if len(pool) == 0 or k <= 0:
        return []
    k = min(k, len(pool))
    return rng.choice(pool, size=k, replace=False).tolist()


# ============================================================
# 3. Real-data calibration
# ============================================================

def load_real_data_for_calibration(cfg: Config):
    if not (os.path.exists(cfg.basic_path) and os.path.exists(cfg.micro_path) and os.path.exists(cfg.brain_path)):
        raise FileNotFoundError(
            "Expected files not found. Upload these files to Colab:\n"
            f"  {cfg.basic_path}\n"
            f"  {cfg.micro_path}\n"
            f"  {cfg.brain_path}"
        )

    basic = replace_missing_codes(pd.read_csv(cfg.basic_path))
    micro = replace_missing_codes(pd.read_csv(cfg.micro_path))
    brain = replace_missing_codes(pd.read_csv(cfg.brain_path))

    brain["ID"] = brain[cfg.id_col_brain].apply(extract_tpmic_id)
    brain = brain.dropna(subset=["ID"]).copy()

    keep_labels = ["Normal", "MCI", "Dementia"]
    basic[cfg.label_col] = basic[cfg.label_col].astype(str)
    basic = basic[basic[cfg.label_col].isin(keep_labels)].copy()

    merged = (
        basic.merge(micro, on="ID", how="inner", suffixes=("", "_micro"))
             .merge(brain, on="ID", how="inner", suffixes=("", "_brain"))
    )

    print("========== Real Data Calibration Summary ==========")
    print("basic:", basic.shape, "micro:", micro.shape, "brain:", brain.shape)
    print("merged:", merged.shape)
    print(merged[cfg.label_col].value_counts())
    print("===================================================\n")
    return basic, micro, brain, merged


def build_basic_features(df: pd.DataFrame):
    cols = ["Sex", "Age", "edu_yr", "BMI", "smoking", "drinking", "exercise_days"]
    cols = [c for c in cols if c in df.columns]
    return safe_numeric(df[cols]).reset_index(drop=True)


def build_brain_features(df: pd.DataFrame):
    candidate_cols = [
        "Left-Hippocampus", "Right-Hippocampus",
        "Left-Amygdala", "Right-Amygdala",
        "lh-entorhinal", "rh-entorhinal",
    ]
    brain_cols = [c for c in candidate_cols if c in df.columns]
    out = pd.DataFrame(index=df.index)

    for c in brain_cols:
        out[c] = pd.to_numeric(df[c], errors="coerce")

    pairs = {
        "Hippocampus": ("Left-Hippocampus", "Right-Hippocampus"),
        "Amygdala": ("Left-Amygdala", "Right-Amygdala"),
        "Entorhinal": ("lh-entorhinal", "rh-entorhinal"),
    }
    for name, (lcol, rcol) in pairs.items():
        if lcol in df.columns and rcol in df.columns:
            L = pd.to_numeric(df[lcol], errors="coerce")
            R = pd.to_numeric(df[rcol], errors="coerce")
            mean = (L + R) / 2.0
            out[f"{name}_mean"] = mean
            out[f"{name}_diff"] = L - R
            out[f"{name}_asymmetry"] = (L - R).abs() / (mean.abs() + 1e-8)

    norm_col = "Total_Labeled_Brain_Volume_mm3"
    if norm_col in df.columns:
        total = pd.to_numeric(df[norm_col], errors="coerce")
        for c in brain_cols:
            out[f"{c}_norm"] = pd.to_numeric(df[c], errors="coerce") / (total + 1e-8)

    return out.reset_index(drop=True)


def get_micro_raw_aligned(merged: pd.DataFrame, micro_original: pd.DataFrame, cfg: Config):
    aligned = merged[["ID"]].merge(micro_original, on="ID", how="left")
    exclude = {"ID", cfg.label_col}
    micro_cols = [c for c in aligned.columns if c not in exclude]
    X = safe_numeric(aligned[micro_cols]).dropna(axis=1, how="all").fillna(0.0).clip(lower=0)
    return X.reset_index(drop=True)


def select_topk_micro_global(X_raw: pd.DataFrame, cfg: Config):
    prevalence = (X_raw > 0).mean(axis=0)
    keep = prevalence[prevalence >= cfg.min_prevalence].index.tolist()
    if len(keep) == 0:
        keep = X_raw.columns.tolist()
    X = X_raw[keep]
    selected = X.var(axis=0).sort_values(ascending=False).head(min(cfg.top_k_species, X.shape[1])).index.tolist()
    return selected


def build_calibration(merged, micro, cfg: Config):
    basic_x = build_basic_features(merged)
    brain_x = build_brain_features(merged)
    patient_x = pd.concat([basic_x, brain_x], axis=1).reset_index(drop=True)

    micro_raw = get_micro_raw_aligned(merged, micro, cfg)
    selected_species = select_topk_micro_global(micro_raw, cfg)
    micro_sel = micro_raw[selected_species].copy().fillna(0.0).clip(lower=0)

    y_real = merged[cfg.label_col].map({"Normal": 0, "MCI": 1, "Dementia": 1}).astype(int).values

    prev = (micro_sel > 0).mean(axis=0).values
    mean_positive = []
    for c in selected_species:
        vals = micro_sel.loc[micro_sel[c] > 0, c]
        mean_positive.append(float(vals.mean()) if len(vals) else 1.0)

    return {
        "real_N": int(len(merged)),
        "synthetic_N": int(max(cfg.n_patients_min, len(merged))),
        "patient_dim": int(patient_x.shape[1]),
        "basic_dim": int(basic_x.shape[1]),
        "brain_dim": int(brain_x.shape[1]),
        "n_species": int(len(selected_species)),
        "selected_species": selected_species,
        "real_risk_rate": float(y_real.mean()),
        "species_prevalence": np.asarray(prev, dtype=float),
        "species_mean_positive": np.asarray(mean_positive, dtype=float),
        "real_patient_feature_mean": np.nanmean(patient_x.values.astype(float), axis=0),
        "real_patient_feature_std": np.nanstd(patient_x.values.astype(float), axis=0) + 1e-6,
        "patient_feature_columns": list(patient_x.columns),
    }


# ============================================================
# 4. Balanced second-order graph-position synthetic data
# ============================================================

def assign_fixed_degree_edges_for_group(rng, nodes, species_groups, composition, S, D):
    """
    Assign exactly D species edges per node according to group composition.
    composition: dict group_name -> count
    species_groups: dict group_name -> array of species ids
    """
    A_sub = np.zeros((len(nodes), S), dtype=np.float32)
    for row_idx, _ in enumerate(nodes):
        chosen = []
        for group_name, k in composition.items():
            pool = species_groups[group_name]
            chosen += sample_without_replacement(rng, pool, k)
        # Fill remaining if duplicates or pool shortage.
        chosen = list(dict.fromkeys(chosen))
        if len(chosen) < D:
            remaining_pool = np.setdiff1d(np.arange(S), np.asarray(chosen, dtype=int))
            chosen += sample_without_replacement(rng, remaining_pool, D - len(chosen))
        chosen = chosen[:D]
        A_sub[row_idx, chosen] = 1.0
    return A_sub


def swap_edge_preserve_degree(A, i_remove_from, i_add_to, s, rng):
    """
    Move species s edge from i_remove_from to i_add_to, while preserving both
    patients' fixed degrees by swapping another species in the opposite direction.
    """
    S = A.shape[1]
    if A[i_remove_from, s] != 1 or A[i_add_to, s] != 0:
        return False

    candidates = np.where((A[i_add_to] == 1) & (A[i_remove_from] == 0))[0]
    if len(candidates) == 0:
        return False

    t = rng.choice(candidates)
    A[i_remove_from, s] = 0
    A[i_add_to, s] = 1
    A[i_add_to, t] = 0
    A[i_remove_from, t] = 1
    return True


def balance_species_prevalence_by_label(A, y, cfg: Config, rng):
    """
    Reduce species identity leakage while preserving fixed degree.

    For species s:
      if prevalence in positives > negatives, move some s edges from positive
      patients to negative patients via degree-preserving swaps.
      if prevalence in negatives > positives, move some s edges from negative
      patients to positive patients.
    """
    A = A.copy()
    pos_idx = np.where(y == 1)[0]
    neg_idx = np.where(y == 0)[0]
    S = A.shape[1]

    for _ in range(cfg.balance_iterations):
        pos_prev = A[pos_idx].mean(axis=0)
        neg_prev = A[neg_idx].mean(axis=0)
        diff = pos_prev - neg_prev

        # Sort from worst leakage to smallest.
        species_order = np.argsort(-np.abs(diff))

        for s in species_order:
            current_diff = A[pos_idx, s].mean() - A[neg_idx, s].mean()
            if abs(current_diff) <= cfg.target_max_species_prev_diff:
                continue

            if current_diff > 0:
                # s too frequent in positives: move s from positives to negatives.
                remove_candidates = pos_idx[A[pos_idx, s] == 1]
                add_candidates = neg_idx[A[neg_idx, s] == 0]
                n_moves = int(np.ceil((abs(current_diff) - cfg.target_max_species_prev_diff) * min(len(pos_idx), len(neg_idx)) * 0.5))
            else:
                # s too frequent in negatives: move s from negatives to positives.
                remove_candidates = neg_idx[A[neg_idx, s] == 1]
                add_candidates = pos_idx[A[pos_idx, s] == 0]
                n_moves = int(np.ceil((abs(current_diff) - cfg.target_max_species_prev_diff) * min(len(pos_idx), len(neg_idx)) * 0.5))

            if len(remove_candidates) == 0 or len(add_candidates) == 0 or n_moves <= 0:
                continue

            rng.shuffle(remove_candidates)
            rng.shuffle(add_candidates)
            moves_done = 0
            for r, a in zip(remove_candidates, add_candidates):
                if swap_edge_preserve_degree(A, int(r), int(a), int(s), rng):
                    moves_done += 1
                if moves_done >= n_moves:
                    break

    return A


def compute_species_anchor_density(A, is_anchor, brain_score):
    species_degree = A.sum(axis=0) + 1e-8
    species_anchor_count = A[is_anchor == 1].sum(axis=0)
    anchor_density = species_anchor_count / species_degree

    anchor_brain_positive = np.maximum(brain_score, 0) * is_anchor
    species_anchor_brain = (A.T @ anchor_brain_positive) / (species_anchor_count + 1e-8)

    context = (
        0.75 * anchor_density
        + 0.25 * (species_anchor_brain - species_anchor_brain.mean()) / (species_anchor_brain.std() + 1e-8)
    )
    context = (context - context.mean()) / (context.std() + 1e-8)
    return anchor_density, context


def generate_second_order_balanced_synthetic(calib: Dict, cfg: Config, seed: int):
    set_seed(seed)
    rng = np.random.default_rng(seed)

    N = int(calib["synthetic_N"])
    S = int(calib["n_species"])
    D = int(cfg.fixed_degree)
    patient_dim = int(calib["patient_dim"])

    # --------------------------------------------------------
    # 1. Weakly aligned latent spaces and patient features
    # --------------------------------------------------------
    z_brain = rng.normal(0, 1, size=(N, cfg.latent_dim))
    z_micro_private = rng.normal(0, 1, size=(N, cfg.latent_dim))
    z_micro = (
        cfg.cross_modal_leakage * z_brain
        + np.sqrt(max(1e-8, 1 - cfg.cross_modal_leakage ** 2)) * z_micro_private
    )

    Wp = rng.normal(0, 1, size=(cfg.latent_dim, patient_dim))
    X_patient = z_brain @ Wp + rng.normal(0, cfg.brain_noise, size=(N, patient_dim))

    real_mean = np.asarray(calib["real_patient_feature_mean"], dtype=float)
    real_std = np.asarray(calib["real_patient_feature_std"], dtype=float)
    if len(real_mean) == patient_dim:
        X_patient = StandardScaler().fit_transform(X_patient)
        X_patient = X_patient * real_std + real_mean
    X_patient = standardize_np(X_patient).astype(np.float32)

    brain_score = (
        -0.85 * z_brain[:, 0]
        + 0.60 * z_brain[:, 1]
        - 0.40 * z_brain[:, 2]
        + 0.20 * np.sin(z_brain[:, 3])
        + rng.normal(0, 0.75, size=N)
    )
    brain_score = (brain_score - brain_score.mean()) / (brain_score.std() + 1e-8)

    # --------------------------------------------------------
    # 2. Define species groups
    # --------------------------------------------------------
    species = np.arange(S)
    rng.shuffle(species)
    n_high = max(D + 2, int(round(cfg.high_context_fraction * S)))
    n_med = max(D + 2, int(round(cfg.medium_context_fraction * S)))
    n_high = min(n_high, S - 2 * D)
    n_med = min(n_med, S - n_high - D)

    high_species = species[:n_high]
    medium_species = species[n_high:n_high + n_med]
    low_species = species[n_high + n_med:]

    species_groups = {
        "high": high_species,
        "medium": medium_species,
        "low": low_species if len(low_species) > 0 else species[n_high:n_high + n_med],
    }

    # --------------------------------------------------------
    # 3. Anchor patients and base graph
    # --------------------------------------------------------
    n_anchor = int(round(cfg.anchor_fraction * N))
    anchor_idx = np.argsort(-brain_score)[:n_anchor]
    is_anchor = np.zeros(N, dtype=int)
    is_anchor[anchor_idx] = 1

    # Initialize every patient with fixed degree.
    A = np.zeros((N, S), dtype=np.float32)

    # Anchor nodes connect more to high-context species; this creates anchor density.
    anchor_comp = {
        "high": min(cfg.anchor_high_edges, D),
        "medium": min(cfg.anchor_medium_edges, max(0, D - min(cfg.anchor_high_edges, D))),
        "low": max(0, D - min(cfg.anchor_high_edges, D) - min(cfg.anchor_medium_edges, max(0, D - min(cfg.anchor_high_edges, D)))),
    }
    A_anchor = assign_fixed_degree_edges_for_group(rng, anchor_idx, species_groups, anchor_comp, S, D)
    A[anchor_idx] = A_anchor

    non_anchor_idx = np.setdiff1d(np.arange(N), anchor_idx)

    # Temporary neutral assignment for non-anchors, later labels are determined from anchor density.
    neutral_comp = {
        "high": cfg.neg_high_edges,
        "medium": cfg.neg_medium_edges,
        "low": max(0, D - cfg.neg_high_edges - cfg.neg_medium_edges),
    }
    A_non = assign_fixed_degree_edges_for_group(rng, non_anchor_idx, species_groups, neutral_comp, S, D)
    A[non_anchor_idx] = A_non

    # Compute preliminary context.
    anchor_density, species_context_score = compute_species_anchor_density(A, is_anchor, brain_score)

    # --------------------------------------------------------
    # 4. Assign labels COMPLETELY from species anchor density / second-order score
    # --------------------------------------------------------
    # Brain positives are anchors with high second-order context, but their risk
    # is still graph-position-defined because anchors create and occupy high-density neighborhoods.
    second_order_score = (A @ anchor_density) / np.clip(A.sum(axis=1), 1.0, None)

    n_pos = int(round(cfg.risk_rate * N))
    n_rel_pos = int(round(cfg.relational_positive_fraction * n_pos))
    n_brain_pos = n_pos - n_rel_pos

    # Brain-positive group: top second-order score among anchors.
    anchor_scores = pd.Series(second_order_score[anchor_idx], index=anchor_idx)
    brain_pos_idx = anchor_scores.sort_values(ascending=False).index.values[:n_brain_pos]

    # Relational-only group: low-brain non-anchor patients with high second-order score.
    low_brain_pool = np.where(brain_score < np.quantile(brain_score, cfg.target_low_brain_quantile))[0]
    low_brain_pool = np.setdiff1d(low_brain_pool, anchor_idx)
    low_brain_scores = pd.Series(second_order_score[low_brain_pool], index=low_brain_pool)
    rel_pos_idx = low_brain_scores.sort_values(ascending=False).index.values[:n_rel_pos]

    # Now rewire relational-only positives to have stronger graph-position context:
    # high anchor-density species but fixed degree.
    rel_comp = {
        "high": cfg.rel_high_edges,
        "medium": cfg.rel_medium_edges,
        "low": max(0, D - cfg.rel_high_edges - cfg.rel_medium_edges),
    }
    A_rel = assign_fixed_degree_edges_for_group(rng, rel_pos_idx, species_groups, rel_comp, S, D)
    A[rel_pos_idx] = A_rel

    # Assign non-risk non-anchors to balanced decoy composition.
    y = np.zeros(N, dtype=int)
    y[brain_pos_idx] = 1
    y[rel_pos_idx] = 1

    relational_only = np.zeros(N, dtype=int)
    relational_only[rel_pos_idx] = 1

    # Make non-risk patients include high species decoys so identity leakage is reduced.
    neg_idx = np.where(y == 0)[0]
    neg_comp = {
        "high": cfg.neg_high_edges,
        "medium": cfg.neg_medium_edges,
        "low": max(0, D - cfg.neg_high_edges - cfg.neg_medium_edges),
    }
    A_neg = assign_fixed_degree_edges_for_group(rng, neg_idx, species_groups, neg_comp, S, D)
    A[neg_idx] = A_neg

    # Recompute context after label-aware rewiring.
    anchor_density, species_context_score = compute_species_anchor_density(A, is_anchor, brain_score)
    second_order_score = (A @ anchor_density) / np.clip(A.sum(axis=1), 1.0, None)

    # Update relational positives purely by second-order score among low-brain non-anchors.
    # This enforces label = high anchor-density graph position.
    low_brain_pool = np.where(brain_score < np.quantile(brain_score, cfg.target_low_brain_quantile))[0]
    low_brain_pool = np.setdiff1d(low_brain_pool, anchor_idx)
    low_brain_scores = pd.Series(second_order_score[low_brain_pool], index=low_brain_pool)
    rel_pos_idx = low_brain_scores.sort_values(ascending=False).index.values[:n_rel_pos]

    anchor_scores = pd.Series(second_order_score[anchor_idx], index=anchor_idx)
    brain_pos_idx = anchor_scores.sort_values(ascending=False).index.values[:n_brain_pos]

    y = np.zeros(N, dtype=int)
    y[brain_pos_idx] = 1
    y[rel_pos_idx] = 1
    relational_only = np.zeros(N, dtype=int)
    relational_only[rel_pos_idx] = 1
    relational_only[brain_pos_idx] = 0

    # --------------------------------------------------------
    # 5. Balance species prevalence by label while preserving degree
    # --------------------------------------------------------
    A = balance_species_prevalence_by_label(A, y, cfg, rng)

    # Recompute final context and score.
    anchor_density, species_context_score = compute_species_anchor_density(A, is_anchor, brain_score)
    second_order_score = (A @ anchor_density) / np.clip(A.sum(axis=1), 1.0, None)

    # Final labels are STILL defined by second-order score.
    # We reselect final positives after balancing, preserving required proportions.
    anchor_scores = pd.Series(second_order_score[anchor_idx], index=anchor_idx)
    brain_pos_idx = anchor_scores.sort_values(ascending=False).index.values[:n_brain_pos]

    low_brain_pool = np.where(brain_score < np.quantile(brain_score, cfg.target_low_brain_quantile))[0]
    low_brain_pool = np.setdiff1d(low_brain_pool, anchor_idx)
    low_brain_scores = pd.Series(second_order_score[low_brain_pool], index=low_brain_pool)
    rel_pos_idx = low_brain_scores.sort_values(ascending=False).index.values[:n_rel_pos]

    y = np.zeros(N, dtype=int)
    y[brain_pos_idx] = 1
    y[rel_pos_idx] = 1
    relational_only = np.zeros(N, dtype=int)
    relational_only[rel_pos_idx] = 1
    relational_only[brain_pos_idx] = 0

    # One final balance pass with final labels.
    A = balance_species_prevalence_by_label(A, y, cfg, rng)
    anchor_density, species_context_score = compute_species_anchor_density(A, is_anchor, brain_score)
    second_order_score = (A @ anchor_density) / np.clip(A.sum(axis=1), 1.0, None)

    # --------------------------------------------------------
    # 6. Build microbiome abundance and features
    # --------------------------------------------------------
    # Constant abundance removes local summary proxy.
    abundance = A * (
        cfg.constant_abundance
        + rng.normal(0, cfg.abundance_noise, size=A.shape)
        + 0.03 * (z_micro @ rng.normal(0, 0.05, size=(cfg.latent_dim, S)))
    )
    abundance = np.clip(abundance, 0.0, None)
    A_log = np.log1p(abundance).astype(np.float32)

    A_presence = (A > 0).astype(np.float32)

    # Normalized graph matrix.
    A_norm = A_presence / np.clip(A_presence.sum(axis=1, keepdims=True), 1.0, None)

    # Randomized graph preserving species prevalence but destroying patient-position.
    A_rand = A_presence.copy()
    for s in range(S):
        rng.shuffle(A_rand[:, s])
    A_rand_norm = A_rand / np.clip(A_rand.sum(axis=1, keepdims=True), 1.0, None)

    # Local microbiome summary deliberately contains no second-order proxy.
    # Degree is fixed; abundance is constant/noisy.
    micro_degree = A_presence.sum(axis=1)
    micro_abund_sum = A_log.sum(axis=1)
    micro_abund_mean = micro_abund_sum / np.clip(micro_degree, 1.0, None)
    micro_abund_std = np.array([
        A_log[i, A_presence[i] > 0].std() if (A_presence[i] > 0).sum() > 1 else 0.0
        for i in range(N)
    ])
    micro_entropy = []
    for i in range(N):
        vals = A_log[i].clip(min=0)
        p = vals / (vals.sum() + 1e-8)
        micro_entropy.append(float(-(p * np.log(p + 1e-8)).sum()))
    X_micro_summary = np.vstack([
        micro_degree,
        micro_abund_sum,
        micro_abund_mean,
        micro_abund_std,
        np.asarray(micro_entropy),
    ]).T.astype(np.float32)
    X_micro_summary = standardize_np(X_micro_summary).astype(np.float32)

    # Diagnostic species identity baseline.
    X_micro_identity = standardize_np(A_log).astype(np.float32)

    X_early_summary = np.concatenate([X_patient, X_micro_summary], axis=1).astype(np.float32)
    X_early_identity = np.concatenate([X_patient, X_micro_identity], axis=1).astype(np.float32)

    selected_species = calib["selected_species"]
    species_rows = []
    high_set, med_set = set(high_species.tolist()), set(medium_species.tolist())
    for s in range(S):
        if s in high_set:
            group = "high_anchor_density_design"
        elif s in med_set:
            group = "medium_anchor_density_design"
        else:
            group = "low_anchor_density_design"
        species_rows.append({
            "seed": seed,
            "species_index": int(s),
            "species_name": selected_species[s] if s < len(selected_species) else f"species_{s}",
            "design_group": group,
            "anchor_density": float(anchor_density[s]),
            "context_score": float(species_context_score[s]),
            "prevalence_y1": float(A_presence[y == 1, s].mean()) if (y == 1).sum() else np.nan,
            "prevalence_y0": float(A_presence[y == 0, s].mean()) if (y == 0).sum() else np.nan,
            "abs_prev_diff": float(abs(
                (A_presence[y == 1, s].mean() if (y == 1).sum() else 0)
                - (A_presence[y == 0, s].mean() if (y == 0).sum() else 0)
            )),
        })

    return {
        "X_patient": X_patient.astype(np.float32),
        "X_micro_summary": X_micro_summary.astype(np.float32),
        "X_micro_identity": X_micro_identity.astype(np.float32),
        "X_early_summary": X_early_summary.astype(np.float32),
        "X_early_identity": X_early_identity.astype(np.float32),
        "A_norm": A_norm.astype(np.float32),
        "A_rand_norm": A_rand_norm.astype(np.float32),
        "A_presence": A_presence.astype(np.float32),
        "A_log": A_log.astype(np.float32),
        "y": y.astype(int),
        "is_anchor": is_anchor.astype(int),
        "relational_only": relational_only.astype(int),
        "brain_score": brain_score.astype(np.float32),
        "second_order_score": second_order_score.astype(np.float32),
        "species_context_score": species_context_score.astype(np.float32),
        "species_anchor_density": anchor_density.astype(np.float32),
        "species_info": pd.DataFrame(species_rows),
        "meta": {
            "seed": seed,
            "N": int(N),
            "S": int(S),
            "fixed_degree": int(D),
            "risk_count": int(y.sum()),
            "risk_rate": float(y.mean()),
            "relational_only_count": int(relational_only.sum()),
            "relational_only_rate": float(relational_only.mean()),
            "brain_positive_count": int(y.sum() - relational_only.sum()),
            "anchor_count": int(is_anchor.sum()),
            "anchor_fraction": float(is_anchor.mean()),
            "second_order_score_pos_mean": float(second_order_score[y == 1].mean()),
            "second_order_score_neg_mean": float(second_order_score[y == 0].mean()),
            "second_order_score_rel_mean": float(second_order_score[relational_only == 1].mean()) if relational_only.sum() else np.nan,
        },
    }


# ============================================================
# 5. Diagnostics
# ============================================================

def cross_modal_cv_r2(A, B, seed=42, n_components=8, n_splits=5):
    n_comp = min(n_components, A.shape[1], B.shape[1], A.shape[0] - 2)
    A_p = PCA(n_components=n_comp, random_state=seed).fit_transform(standardize_np(A))
    B_p = PCA(n_components=n_comp, random_state=seed).fit_transform(standardize_np(B))

    idx = np.arange(A.shape[0])
    rng = np.random.default_rng(seed)
    rng.shuffle(idx)
    folds = np.array_split(idx, n_splits)

    def cv_score(X, Y):
        scores = []
        for te in folds:
            tr = np.setdiff1d(idx, te)
            model = Ridge(alpha=10.0)
            model.fit(X[tr], Y[tr])
            pred = model.predict(X[te])
            sse = ((Y[te] - pred) ** 2).sum()
            sst = ((Y[te] - Y[tr].mean(axis=0)) ** 2).sum()
            scores.append(1 - sse / (sst + 1e-8))
        return float(np.mean(scores))

    return cv_score(A_p, B_p), cv_score(B_p, A_p)


def cca_corrs(A, B, seed=42, n_components=3):
    A_s = standardize_np(A)
    B_s = standardize_np(B)
    A_p = PCA(n_components=min(12, A_s.shape[1], A_s.shape[0] - 2), random_state=seed).fit_transform(A_s)
    B_p = PCA(n_components=min(12, B_s.shape[1], B_s.shape[0] - 2), random_state=seed).fit_transform(B_s)
    n_comp = min(n_components, A_p.shape[1], B_p.shape[1])
    cca = CCA(n_components=n_comp, max_iter=3000)
    U, V = cca.fit_transform(A_p, B_p)
    return [float(np.corrcoef(U[:, i], V[:, i])[0, 1]) for i in range(n_comp)]


def neighbor_overlap(A, B, ks=(5, 10, 20)):
    A_s = standardize_np(A)
    B_s = standardize_np(B)
    out = {}
    for k in ks:
        k_eff = min(k, A.shape[0] - 1)
        nn_a = NearestNeighbors(n_neighbors=k_eff + 1).fit(A_s).kneighbors(A_s, return_distance=False)[:, 1:]
        nn_b = NearestNeighbors(n_neighbors=k_eff + 1).fit(B_s).kneighbors(B_s, return_distance=False)[:, 1:]
        vals = []
        for i in range(A.shape[0]):
            vals.append(len(set(nn_a[i]).intersection(set(nn_b[i]))) / k_eff)
        out[f"neighbor_overlap@{k}"] = float(np.mean(vals))
    return out


def run_diagnostics(data, seed):
    # Weak alignment between patient brain features and microbiome identity matrix.
    b2m, m2b = cross_modal_cv_r2(data["X_patient"], data["X_micro_identity"], seed=seed)
    cca = cca_corrs(data["X_patient"], data["X_micro_identity"], seed=seed)

    # Species identity leakage
    pres = data["A_presence"]
    y = data["y"]
    pos_prev = pres[y == 1].mean(axis=0)
    neg_prev = pres[y == 0].mean(axis=0)
    diff = np.abs(pos_prev - neg_prev)

    # Local summary leakage
    local_summary_signal = {}
    for j, name in enumerate(["degree", "sum", "mean", "std", "entropy"]):
        try:
            rho, _ = spearmanr(data["X_micro_summary"][:, j], y)
        except Exception:
            rho = np.nan
        local_summary_signal[f"spearman_local_{name}_vs_y"] = float(rho)

    rho_brain_second, _ = spearmanr(data["brain_score"], data["second_order_score"])
    rho_y_second, _ = spearmanr(y, data["second_order_score"])

    rel = data["relational_only"] == 1
    non_rel = data["relational_only"] == 0
    rel_gap = float(data["second_order_score"][rel].mean() - data["second_order_score"][non_rel].mean()) if rel.sum() else np.nan

    return {
        "seed": seed,
        "brain_to_micro_cv_r2": b2m,
        "micro_to_brain_cv_r2": m2b,
        "cca_1": cca[0] if len(cca) > 0 else np.nan,
        "cca_2": cca[1] if len(cca) > 1 else np.nan,
        "cca_3": cca[2] if len(cca) > 2 else np.nan,
        **neighbor_overlap(data["X_patient"], data["X_micro_identity"]),
        "spearman_brain_vs_second_order_score": float(rho_brain_second),
        "spearman_y_vs_second_order_score": float(rho_y_second),
        "max_abs_species_prevalence_diff": float(np.max(diff)),
        "mean_abs_species_prevalence_diff": float(np.mean(diff)),
        "median_abs_species_prevalence_diff": float(np.median(diff)),
        "second_order_score_gap_relational_vs_other": rel_gap,
        **local_summary_signal,
    }


# ============================================================
# 6. Models
# ============================================================

class FocalLossBinary(nn.Module):
    def __init__(self, alpha_pos=0.72, gamma=2.0):
        super().__init__()
        self.alpha_pos = alpha_pos
        self.gamma = gamma

    def forward(self, logits, target):
        target = target.float()
        bce = F.binary_cross_entropy_with_logits(logits, target, reduction="none")
        prob = torch.sigmoid(logits)
        pt = torch.where(target == 1, prob, 1 - prob)
        alpha = torch.where(
            target == 1,
            torch.tensor(self.alpha_pos, device=logits.device),
            torch.tensor(1 - self.alpha_pos, device=logits.device),
        )
        return (alpha * (1 - pt).pow(self.gamma) * bce).mean()


class MLPBinary(nn.Module):
    def __init__(self, in_dim, hidden_dim=96, dropout=0.35):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden_dim),
            nn.BatchNorm1d(hidden_dim),
            nn.ReLU(),
            nn.Dropout(dropout),
            nn.Linear(hidden_dim, hidden_dim // 2),
            nn.BatchNorm1d(hidden_dim // 2),
            nn.ReLU(),
            nn.Dropout(dropout),
            nn.Linear(hidden_dim // 2, 1),
        )

    def forward(self, x):
        return self.net(x).squeeze(-1)


class SecondOrderHGNN(nn.Module):
    """
    Patient-species HGNN.

    species_update receives patient feature messages from neighboring patients.
    Therefore, if a species is connected to many brain-vulnerable anchors,
    its embedding contains anchor-density context. That context is then passed
    to low-brain target patients through species -> patient aggregation.
    """
    def __init__(self, patient_dim, n_species, hidden_dim=96, latent_dim=32, dropout=0.35, use_gaussian=False):
        super().__init__()
        self.use_gaussian = use_gaussian
        self.dropout = dropout

        self.patient_proj = nn.Linear(patient_dim, hidden_dim)
        self.species_emb = nn.Parameter(torch.randn(n_species, hidden_dim) * 0.03)

        self.species_update = nn.Sequential(
            nn.Linear(hidden_dim * 2, hidden_dim),
            nn.ReLU(),
            nn.Dropout(dropout),
        )

        self.patient_update = nn.Sequential(
            nn.Linear(hidden_dim * 3, hidden_dim),
            nn.ReLU(),
            nn.Dropout(dropout),
        )

        self.context_gate = nn.Sequential(
            nn.Linear(hidden_dim, hidden_dim),
            nn.ReLU(),
            nn.Linear(hidden_dim, hidden_dim),
            nn.Sigmoid(),
        )

        if use_gaussian:
            self.mu = nn.Linear(hidden_dim, latent_dim)
            self.logvar = nn.Linear(hidden_dim, latent_dim)
        else:
            self.det = nn.Linear(hidden_dim, latent_dim)

        self.classifier = nn.Sequential(
            nn.Linear(latent_dim, hidden_dim // 2),
            nn.ReLU(),
            nn.Dropout(dropout),
            nn.Linear(hidden_dim // 2, 1),
        )

    def forward(self, x_patient, A_ps):
        # A_ps: row-normalized patient-species matrix [N, S]
        h_p = F.relu(self.patient_proj(x_patient))
        h_s0 = self.species_emb

        # patient -> species
        A_sp = A_ps.t()
        deg_s = A_sp.sum(dim=1, keepdim=True).clamp(min=1.0)
        msg_s = (A_sp @ h_p) / deg_s
        h_s = self.species_update(torch.cat([h_s0, msg_s], dim=1))

        # species -> patient
        msg_p = A_ps @ h_s
        gated = msg_p * self.context_gate(msg_p)
        h = self.patient_update(torch.cat([h_p, msg_p, gated], dim=1))

        if self.use_gaussian:
            mu = self.mu(h)
            logvar = self.logvar(h).clamp(-8, 6)
            if self.training:
                eps = torch.randn_like(mu)
                z = mu + torch.exp(0.5 * logvar) * eps
            else:
                z = mu
            kl = -0.5 * torch.mean(torch.sum(1 + logvar - mu.pow(2) - logvar.exp(), dim=1))
        else:
            z = self.det(h)
            mu = z
            kl = torch.tensor(0.0, device=x_patient.device)

        logits = self.classifier(z).squeeze(-1)
        return logits, kl, mu


# ============================================================
# 7. Training / evaluation
# ============================================================

def fit_sklearn_model(model, X, y, train_idx, val_idx, test_idx, cfg: Config):
    imp = SimpleImputer(strategy="median")
    scaler = StandardScaler()

    X_train = scaler.fit_transform(imp.fit_transform(X[train_idx]))
    X_val = scaler.transform(imp.transform(X[val_idx]))
    X_test = scaler.transform(imp.transform(X[test_idx]))

    model.fit(X_train, y[train_idx])
    p_val = model.predict_proba(X_val)[:, 1]
    p_test = model.predict_proba(X_test)[:, 1]
    th = choose_threshold(y[val_idx], p_val, cfg)
    pred = (p_test >= th).astype(int)
    return p_test, pred, th


def fit_mlp_model(X, y, train_idx, val_idx, test_idx, cfg: Config, seed: int):
    set_seed(seed)
    dev = get_device(cfg)

    imp = SimpleImputer(strategy="median")
    scaler = StandardScaler()
    X_train = scaler.fit_transform(imp.fit_transform(X[train_idx]))
    X_val = scaler.transform(imp.transform(X[val_idx]))
    X_test = scaler.transform(imp.transform(X[test_idx]))

    xt = torch.tensor(X_train, dtype=torch.float32, device=dev)
    xv = torch.tensor(X_val, dtype=torch.float32, device=dev)
    xe = torch.tensor(X_test, dtype=torch.float32, device=dev)
    yt = torch.tensor(y[train_idx], dtype=torch.float32, device=dev)
    yv = torch.tensor(y[val_idx], dtype=torch.float32, device=dev)

    model = MLPBinary(X_train.shape[1], cfg.hidden_dim, cfg.dropout).to(dev)
    opt = torch.optim.AdamW(model.parameters(), lr=cfg.lr, weight_decay=cfg.weight_decay)
    criterion = FocalLossBinary(cfg.alpha_pos, cfg.gamma)

    best_state, best_val, bad = None, np.inf, 0
    for epoch in range(cfg.epochs):
        model.train()
        opt.zero_grad()
        loss = criterion(model(xt), yt)
        loss.backward()
        torch.nn.utils.clip_grad_norm_(model.parameters(), 5.0)
        opt.step()

        model.eval()
        with torch.no_grad():
            val_loss = criterion(model(xv), yv).item()

        if val_loss < best_val:
            best_val = val_loss
            best_state = {k: v.detach().cpu().clone() for k, v in model.state_dict().items()}
            bad = 0
        else:
            bad += 1
            if bad >= cfg.patience:
                break

    if best_state is not None:
        model.load_state_dict({k: v.to(dev) for k, v in best_state.items()})

    model.eval()
    with torch.no_grad():
        p_val = torch.sigmoid(model(xv)).detach().cpu().numpy()
        p_test = torch.sigmoid(model(xe)).detach().cpu().numpy()

    th = choose_threshold(y[val_idx], p_val, cfg)
    pred = (p_test >= th).astype(int)
    return p_test, pred, th


def fit_hgnn_model(X_patient, A_norm, y, train_idx, val_idx, test_idx, cfg: Config, seed: int, use_gaussian=False, use_ib=False):
    set_seed(seed)
    dev = get_device(cfg)

    X_scaled = standardize_np(X_patient).astype(np.float32)
    x = torch.tensor(X_scaled, dtype=torch.float32, device=dev)
    A = torch.tensor(A_norm, dtype=torch.float32, device=dev)
    yt = torch.tensor(y, dtype=torch.float32, device=dev)

    train_t = torch.tensor(train_idx, dtype=torch.long, device=dev)
    val_t = torch.tensor(val_idx, dtype=torch.long, device=dev)

    model = SecondOrderHGNN(
        patient_dim=X_patient.shape[1],
        n_species=A_norm.shape[1],
        hidden_dim=cfg.hidden_dim,
        latent_dim=cfg.latent_dim_model,
        dropout=cfg.dropout,
        use_gaussian=use_gaussian,
    ).to(dev)

    opt = torch.optim.AdamW(model.parameters(), lr=cfg.lr, weight_decay=cfg.weight_decay)
    criterion = FocalLossBinary(cfg.alpha_pos, cfg.gamma)

    best_state, best_val, bad = None, np.inf, 0
    for epoch in range(cfg.epochs):
        model.train()
        opt.zero_grad()
        logits, kl, _ = model(x, A)
        loss = criterion(logits[train_t], yt[train_t])
        if use_ib and use_gaussian:
            loss = loss + cfg.beta * kl
        loss.backward()
        torch.nn.utils.clip_grad_norm_(model.parameters(), 5.0)
        opt.step()

        model.eval()
        with torch.no_grad():
            logits_v, kl_v, _ = model(x, A)
            val_loss = criterion(logits_v[val_t], yt[val_t])
            if use_ib and use_gaussian:
                val_loss = val_loss + cfg.beta * kl_v
            val_loss = val_loss.item()

        if val_loss < best_val:
            best_val = val_loss
            best_state = {k: v.detach().cpu().clone() for k, v in model.state_dict().items()}
            bad = 0
        else:
            bad += 1
            if bad >= cfg.patience:
                break

    if best_state is not None:
        model.load_state_dict({k: v.to(dev) for k, v in best_state.items()})

    model.eval()
    with torch.no_grad():
        logits_all, _, emb = model(x, A)
        p_all = torch.sigmoid(logits_all).detach().cpu().numpy()

    p_val = p_all[val_idx]
    p_test = p_all[test_idx]
    th = choose_threshold(y[val_idx], p_val, cfg)
    pred = (p_test >= th).astype(int)
    return p_test, pred, th, p_all, emb.detach().cpu().numpy()


def evaluate_one_seed(data, cfg: Config, seed: int):
    y = data["y"]
    train_idx, val_idx, test_idx = split_indices(y, seed)

    rows = []

    def add_row(model_name, p_test, pred, th, seconds):
        m = binary_metrics(y[test_idx], p_test, pred=pred)
        rel_mask = data["relational_only"][test_idx] == 1
        brain_pos_mask = (y[test_idx] == 1) & (data["relational_only"][test_idx] == 0)
        anchor_mask = data["is_anchor"][test_idx] == 1

        m.update({
            "seed": seed,
            "model": model_name,
            "threshold": th,
            "seconds": seconds,
            "relational_only_recall": float(pred[rel_mask].mean()) if rel_mask.sum() else np.nan,
            "relational_only_n_test": int(rel_mask.sum()),
            "brain_positive_recall": float(pred[brain_pos_mask].mean()) if brain_pos_mask.sum() else np.nan,
            "anchor_predicted_risk_rate": float(pred[anchor_mask].mean()) if anchor_mask.sum() else np.nan,
        })
        rows.append(m)

    # Main non-graph baselines: local-only info, no graph-neighborhood context.
    sklearn_specs = [
        ("LogReg-BrainOnly", LogisticRegression(max_iter=2500, class_weight="balanced"), data["X_patient"]),
        ("LogReg-LocalMicroSummary", LogisticRegression(max_iter=2500, class_weight="balanced"), data["X_micro_summary"]),
        ("LogReg-EarlyFusionLocalSummary", LogisticRegression(max_iter=2500, class_weight="balanced"), data["X_early_summary"]),
        ("RF-BrainOnly", RandomForestClassifier(n_estimators=500, random_state=seed, class_weight="balanced_subsample", min_samples_leaf=2), data["X_patient"]),
        ("RF-LocalMicroSummary", RandomForestClassifier(n_estimators=500, random_state=seed, class_weight="balanced_subsample", min_samples_leaf=2), data["X_micro_summary"]),
        ("RF-EarlyFusionLocalSummary", RandomForestClassifier(n_estimators=500, random_state=seed, class_weight="balanced_subsample", min_samples_leaf=2), data["X_early_summary"]),
    ]

    # Diagnostic baselines: species identity leakage check.
    sklearn_specs += [
        ("DIAGNOSTIC-LogReg-EarlyFusionSpeciesIdentity", LogisticRegression(max_iter=2500, class_weight="balanced"), data["X_early_identity"]),
        ("DIAGNOSTIC-RF-EarlyFusionSpeciesIdentity", RandomForestClassifier(n_estimators=500, random_state=seed, class_weight="balanced_subsample", min_samples_leaf=2), data["X_early_identity"]),
    ]

    for name, model, X in sklearn_specs:
        t0 = time.time()
        p, pred, th = fit_sklearn_model(model, X, y, train_idx, val_idx, test_idx, cfg)
        add_row(name, p, pred, th, time.time() - t0)

    mlp_specs = [
        ("MLP-Focal-BrainOnly", data["X_patient"]),
        ("MLP-Focal-LocalMicroSummary", data["X_micro_summary"]),
        ("MLP-Focal-EarlyFusionLocalSummary", data["X_early_summary"]),
        ("DIAGNOSTIC-MLP-Focal-EarlyFusionSpeciesIdentity", data["X_early_identity"]),
    ]

    for name, X in mlp_specs:
        t0 = time.time()
        p, pred, th = fit_mlp_model(X, y, train_idx, val_idx, test_idx, cfg, seed)
        add_row(name, p, pred, th, time.time() - t0)

    graph_specs = [
        ("HGNN-Focal-RandomizedEdges", data["A_rand_norm"], False, False),
        ("HGNN-Focal-RealEdges", data["A_norm"], False, False),
        ("HGNN-Gaussian-Focal-RealEdges", data["A_norm"], True, False),
        ("VGIB-HGNN-Focal-Proposed", data["A_norm"], True, True),
    ]

    for name, A_mat, use_g, use_ib in graph_specs:
        t0 = time.time()
        p, pred, th, p_all, emb = fit_hgnn_model(
            data["X_patient"], A_mat, y,
            train_idx, val_idx, test_idx,
            cfg, seed, use_gaussian=use_g, use_ib=use_ib
        )
        add_row(name, p, pred, th, time.time() - t0)

    return pd.DataFrame(rows)


# ============================================================
# 8. Summary and bootstrap
# ============================================================

def summarize_mean_std(df: pd.DataFrame):
    metrics = [
        "auc", "pr_auc", "risk_recall", "risk_precision", "risk_f1",
        "macro_f1", "balanced_acc", "predicted_risk_rate",
        "relational_only_recall", "brain_positive_recall",
        "anchor_predicted_risk_rate", "seconds"
    ]
    rows = []
    for model, sub in df.groupby("model"):
        row = {"model": model}
        for c in metrics:
            row[c + "_mean"] = float(sub[c].mean())
            row[c + "_std"] = float(sub[c].std(ddof=0))
            row[c + "_mean_std"] = f"{sub[c].mean():.3f} ± {sub[c].std(ddof=0):.3f}"
        rows.append(row)
    return pd.DataFrame(rows).sort_values("risk_f1_mean", ascending=False)


def paired_seed_bootstrap(df: pd.DataFrame, proposed="VGIB-HGNN-Focal-Proposed"):
    metrics = [
        "auc", "pr_auc", "risk_recall", "risk_precision", "risk_f1",
        "relational_only_recall", "brain_positive_recall"
    ]
    baselines = [m for m in df["model"].unique() if m != proposed]
    rng = np.random.default_rng(42)
    rows = []

    for b in baselines:
        for metric in metrics:
            pivot = df.pivot_table(index="seed", columns="model", values=metric)
            if proposed not in pivot.columns or b not in pivot.columns:
                continue
            common = pivot[[proposed, b]].dropna()
            if len(common) < 2:
                continue
            av = common[proposed].values
            bv = common[b].values
            n = len(av)
            diffs = []
            for _ in range(5000):
                idx = rng.integers(0, n, size=n)
                diffs.append((av[idx] - bv[idx]).mean())
            diffs = np.asarray(diffs)
            rows.append({
                "model_A": proposed,
                "model_B": b,
                "metric": metric,
                "mean_diff_A_minus_B": float((av - bv).mean()),
                "ci_lower": float(np.quantile(diffs, 0.025)),
                "ci_upper": float(np.quantile(diffs, 0.975)),
                "p_two_sided": float(min(1.0, 2 * min((diffs <= 0).mean(), (diffs >= 0).mean()))),
                "n_seeds": int(n),
            })
    return pd.DataFrame(rows)


# ============================================================
# 9. Main
# ============================================================

def main(cfg: Config = CFG):
    ensure_dir(cfg.output_dir)

    with open(os.path.join(cfg.output_dir, "00_config.json"), "w", encoding="utf-8") as f:
        json.dump(asdict(cfg), f, indent=2, ensure_ascii=False)

    basic, micro, brain, merged = load_real_data_for_calibration(cfg)
    calib = build_calibration(merged, micro, cfg)

    pd.DataFrame([{
        "real_N": calib["real_N"],
        "synthetic_N": calib["synthetic_N"],
        "patient_dim": calib["patient_dim"],
        "basic_dim": calib["basic_dim"],
        "brain_dim": calib["brain_dim"],
        "n_species": calib["n_species"],
        "real_risk_rate": calib["real_risk_rate"],
        "synthetic_risk_rate": cfg.risk_rate,
        "fixed_degree": cfg.fixed_degree,
    }]).to_csv(os.path.join(cfg.output_dir, "00_real_calibration_inventory.csv"), index=False, encoding="utf-8-sig")

    pd.DataFrame({
        "species_index": np.arange(len(calib["selected_species"])),
        "species_name": calib["selected_species"],
        "real_prevalence": calib["species_prevalence"],
        "real_mean_positive_abundance": calib["species_mean_positive"],
    }).to_csv(os.path.join(cfg.output_dir, "00_selected_species_from_real_data.csv"), index=False, encoding="utf-8-sig")

    print("Running balanced second-order graph-position benchmark on:", get_device(cfg))

    all_perf = []
    all_diag = []
    all_meta = []
    all_species_info = []

    for seed in cfg.seeds:
        print(f"\n================ Seed {seed} ================")
        data = generate_second_order_balanced_synthetic(calib, cfg, seed)
        diag = run_diagnostics(data, seed)
        perf = evaluate_one_seed(data, cfg, seed)

        print("\nDiagnostics:")
        for k, v in diag.items():
            if k != "seed":
                print(f"  {k}: {v:.4f}" if isinstance(v, float) else f"  {k}: {v}")

        show_cols = ["model", "auc", "pr_auc", "risk_recall", "risk_precision", "risk_f1", "relational_only_recall"]
        print("\nPerformance:")
        print(perf[show_cols].sort_values("risk_f1", ascending=False).to_string(index=False))

        all_perf.append(perf)
        all_diag.append(pd.DataFrame([diag]))
        all_meta.append(pd.DataFrame([data["meta"]]))
        all_species_info.append(data["species_info"])

    perf_df = pd.concat(all_perf, ignore_index=True)
    diag_df = pd.concat(all_diag, ignore_index=True)
    meta_df = pd.concat(all_meta, ignore_index=True)
    species_df = pd.concat(all_species_info, ignore_index=True)

    summary_df = summarize_mean_std(perf_df)
    boot_df = paired_seed_bootstrap(perf_df)

    save_csv(perf_df, os.path.join(cfg.output_dir, "RQ4_balanced_second_order_all_seed_performance.csv"))
    save_csv(summary_df, os.path.join(cfg.output_dir, "RQ4_balanced_second_order_summary_mean_std.csv"))
    save_csv(diag_df, os.path.join(cfg.output_dir, "RQ4_balanced_second_order_diagnostics_by_seed.csv"))
    save_csv(pd.DataFrame([diag_df.drop(columns=["seed"]).mean(numeric_only=True).to_dict()]), os.path.join(cfg.output_dir, "RQ4_balanced_second_order_diagnostics_summary.csv"))
    save_csv(meta_df, os.path.join(cfg.output_dir, "RQ4_balanced_second_order_meta_by_seed.csv"))
    save_csv(species_df, os.path.join(cfg.output_dir, "RQ4_balanced_second_order_species_context_info.csv"))
    save_csv(boot_df, os.path.join(cfg.output_dir, "RQ4_balanced_second_order_paired_bootstrap_over_seeds.csv"))

    print("\n================ FINAL SUMMARY ================")
    print(summary_df[[
        "model",
        "auc_mean_std", "pr_auc_mean_std",
        "risk_recall_mean_std", "risk_precision_mean_std", "risk_f1_mean_std",
        "relational_only_recall_mean_std"
    ]].to_string(index=False))

    print("\nOutputs saved to:", cfg.output_dir)
    print("Key files:")
    print("  - RQ4_balanced_second_order_summary_mean_std.csv")
    print("  - RQ4_balanced_second_order_diagnostics_summary.csv")
    print("  - RQ4_balanced_second_order_paired_bootstrap_over_seeds.csv")
    print("  - RQ4_balanced_second_order_all_seed_performance.csv")


if __name__ == "__main__":
    main(CFG)

"""# **synthetic benchmark_v3**"""

# ============================================================
# ICDM RQ4 Synthetic Benchmark v3
# SECOND-ORDER GRAPH-POSITION High-Risk Recovery
#
# Core idea
# ---------
# This version no longer makes high-risk a direct function of a patient's own
# species vector. Instead, a relational-only patient is high-risk when:
#
#   the species connected to this patient are themselves connected to many
#   brain-vulnerable anchor patients.
#
# That is, the target signal is a second-order graph-position signal:
#
#   target patient -> species -> anchor patients with vulnerable brain features
#
# Why this fixes the previous benchmark
# -------------------------------------
# Previous versions still allowed RF/MLP to learn species co-occurrence directly
# from the flattened microbiome vector. This version introduces a benchmark where
# the label is driven by the neighborhood context of the connected species.
#
# The graph model can update species nodes from anchor patient features and then
# pass the contextualized species message back to target patients.
#
# Non-graph baselines are evaluated in two ways:
#   1. Main non-graph baselines:
#        BrainOnly / LocalMicroSummary / EarlyFusionLocalSummary
#      These do NOT observe graph neighborhood context.
#   2. Diagnostic species-identity baselines:
#        EarlyFusionSpeciesIdentity
#      These see raw species columns. They are included as a leakage diagnostic.
#      If they win, it means species identity is still too predictive.
#
# Expected Colab files
# --------------------
#   /content/data.csv
#   /content/micro.csv
#   /content/all_brain_result_1(3).csv
#
# Output folder
# -------------
#   /content/icdm_second_order_graph_position_outputs/
#
# Colab command
# -------------
#   !python icdm_second_order_graph_position_synthetic_benchmark.py
#
# Dependencies
# ------------
#   pip install -q numpy pandas scikit-learn scipy torch
#
# No torch-geometric is required.
# ============================================================

import os
import re
import json
import time
import random
import warnings
from dataclasses import dataclass, asdict
from typing import Dict, List, Tuple

import numpy as np
import pandas as pd

from sklearn.impute import SimpleImputer
from sklearn.preprocessing import StandardScaler
from sklearn.model_selection import train_test_split
from sklearn.metrics import (
    roc_auc_score,
    average_precision_score,
    f1_score,
    recall_score,
    precision_score,
    balanced_accuracy_score,
    accuracy_score,
    brier_score_loss,
)
from sklearn.linear_model import LogisticRegression, Ridge
from sklearn.ensemble import RandomForestClassifier
from sklearn.decomposition import PCA
from sklearn.cross_decomposition import CCA
from sklearn.neighbors import NearestNeighbors

from scipy.stats import spearmanr

import torch
import torch.nn as nn
import torch.nn.functional as F

warnings.filterwarnings("ignore")


# ============================================================
# 1. Config
# ============================================================

@dataclass
class Config:
    # Real data paths
    basic_path: str = "/content/data.csv"
    micro_path: str = "/content/micro.csv"
    brain_path: str = "/content/all_brain_result_1(3).csv"
    output_dir: str = "/content/icdm_second_order_graph_position_outputs"

    id_col_brain: str = "Subject_ID"
    label_col: str = "Diagnosis"

    # Real calibration
    top_k_species: int = 50
    min_prevalence: float = 0.02
    n_patients_min: int = 720

    # Seeds
    seeds: Tuple[int, ...] = (11, 22, 33, 44, 55, 66, 77)

    # Synthetic target proportions
    risk_rate: float = 0.24
    relational_positive_fraction: float = 0.62
    brain_positive_fraction: float = 0.38

    # Weak alignment controls
    latent_dim: int = 8
    cross_modal_leakage: float = 0.02
    brain_noise: float = 1.20
    micro_noise: float = 1.00

    # Graph-position construction
    anchor_fraction: float = 0.22       # brain-vulnerable anchor patients
    target_low_brain_quantile: float = 0.60
    edges_per_patient_min: int = 4
    edges_per_patient_max: int = 8
    anchor_extra_edges_min: int = 3
    anchor_extra_edges_max: int = 6

    # Species context
    high_context_species_fraction: float = 0.35
    medium_context_species_fraction: float = 0.35

    # Margin control: balance species prevalence across y to reduce identity leakage
    prevalence_balance_strength: float = 0.85

    # Training
    hidden_dim: int = 96
    latent_dim_model: int = 32
    dropout: float = 0.35
    lr: float = 2e-3
    weight_decay: float = 1e-4
    epochs: int = 400
    patience: int = 60

    # Focal / VGIB
    gamma: float = 2.0
    alpha_pos: float = 0.72
    beta: float = 5e-4

    # Threshold
    precision_floor: float = 0.50
    threshold_grid_size: int = 181

    # Device
    use_cuda_if_available: bool = True


CFG = Config()

# Local fallback for this environment
if os.path.exists("/mnt/data/data.csv"):
    CFG.basic_path = "/mnt/data/data.csv"
    CFG.micro_path = "/mnt/data/micro.csv"
    CFG.brain_path = "/mnt/data/all_brain_result_1(3).csv"
    CFG.output_dir = "/mnt/data/icdm_second_order_graph_position_outputs"


# ============================================================
# 2. Utilities
# ============================================================

def set_seed(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    torch.cuda.manual_seed_all(seed)


def get_device(cfg: Config):
    return torch.device("cuda" if cfg.use_cuda_if_available and torch.cuda.is_available() else "cpu")


def ensure_dir(path: str):
    os.makedirs(path, exist_ok=True)


def save_csv(df: pd.DataFrame, path: str):
    df.to_csv(path, index=False, encoding="utf-8-sig")
    print("Saved:", path)


def extract_tpmic_id(x):
    m = re.search(r"TPMIC\d+", str(x))
    return m.group(0) if m else None


def replace_missing_codes(df: pd.DataFrame):
    return df.replace([999, 999.0, "999", "999.0", "NA", "N/A", "", "nan", "None"], np.nan)


def encode_sex_like(series: pd.Series):
    if pd.api.types.is_numeric_dtype(series):
        return pd.to_numeric(series, errors="coerce")
    mapping = {
        "m": 1, "male": 1, "man": 1, "男": 1, "男性": 1, "1": 1,
        "f": 0, "female": 0, "woman": 0, "女": 0, "女性": 0, "0": 0,
    }
    return series.astype(str).str.strip().str.lower().map(mapping)


def safe_numeric(df: pd.DataFrame):
    out = df.copy()
    for c in out.columns:
        if c.lower() in ["sex", "gender"]:
            out[c] = encode_sex_like(out[c])
        else:
            out[c] = pd.to_numeric(out[c], errors="coerce")
    return out


def standardize_np(X):
    X = pd.DataFrame(X).replace([np.inf, -np.inf], np.nan)
    X = SimpleImputer(strategy="median").fit_transform(X)
    return StandardScaler().fit_transform(X)


def choose_threshold(y_val, prob_val, cfg: Config, policy="max_recall_precision_floor"):
    y_val = np.asarray(y_val).astype(int)
    prob_val = np.asarray(prob_val).astype(float)
    candidates = np.linspace(0.02, 0.98, cfg.threshold_grid_size)

    best_t, best_tuple = 0.5, None
    for t in candidates:
        pred = (prob_val >= t).astype(int)
        rec = recall_score(y_val, pred, zero_division=0)
        prec = precision_score(y_val, pred, zero_division=0)
        f1 = f1_score(y_val, pred, zero_division=0)
        mf1 = f1_score(y_val, pred, average="macro", zero_division=0)

        if policy == "max_recall_precision_floor":
            if prec >= cfg.precision_floor:
                score_tuple = (rec, f1, prec)
            else:
                score_tuple = (-1, f1, prec)
        elif policy == "max_risk_f1":
            score_tuple = (f1, rec, prec)
        else:
            score_tuple = (mf1, f1, rec)

        if best_tuple is None or score_tuple > best_tuple:
            best_tuple = score_tuple
            best_t = t

    if best_tuple is not None and best_tuple[0] < 0:
        return choose_threshold(y_val, prob_val, cfg, policy="max_risk_f1")
    return float(best_t)


def binary_metrics(y_true, prob, pred=None, threshold=0.5):
    y_true = np.asarray(y_true).astype(int)
    prob = np.asarray(prob).astype(float)
    if pred is None:
        pred = (prob >= threshold).astype(int)

    out = {
        "auc": np.nan,
        "pr_auc": np.nan,
        "risk_recall": recall_score(y_true, pred, zero_division=0),
        "risk_precision": precision_score(y_true, pred, zero_division=0),
        "risk_f1": f1_score(y_true, pred, zero_division=0),
        "macro_f1": f1_score(y_true, pred, average="macro", zero_division=0),
        "balanced_acc": balanced_accuracy_score(y_true, pred),
        "acc": accuracy_score(y_true, pred),
        "predicted_risk_rate": float(np.mean(pred == 1)),
        "brier": np.nan,
    }
    if len(np.unique(y_true)) == 2:
        out["auc"] = roc_auc_score(y_true, prob)
        out["pr_auc"] = average_precision_score(y_true, prob)
        out["brier"] = brier_score_loss(y_true, np.clip(prob, 1e-6, 1 - 1e-6))
    return out


def split_indices(y, seed):
    idx = np.arange(len(y))
    train_val, test = train_test_split(idx, test_size=0.25, stratify=y, random_state=seed)
    train, val = train_test_split(train_val, test_size=0.22, stratify=y[train_val], random_state=seed + 100)
    return train, val, test


# ============================================================
# 3. Real-data calibration
# ============================================================

def load_real_data_for_calibration(cfg: Config):
    if not (os.path.exists(cfg.basic_path) and os.path.exists(cfg.micro_path) and os.path.exists(cfg.brain_path)):
        raise FileNotFoundError(
            "Expected files not found. Upload these files to Colab:\n"
            f"  {cfg.basic_path}\n"
            f"  {cfg.micro_path}\n"
            f"  {cfg.brain_path}"
        )

    basic = replace_missing_codes(pd.read_csv(cfg.basic_path))
    micro = replace_missing_codes(pd.read_csv(cfg.micro_path))
    brain = replace_missing_codes(pd.read_csv(cfg.brain_path))

    brain["ID"] = brain[cfg.id_col_brain].apply(extract_tpmic_id)
    brain = brain.dropna(subset=["ID"]).copy()

    keep_labels = ["Normal", "MCI", "Dementia"]
    basic[cfg.label_col] = basic[cfg.label_col].astype(str)
    basic = basic[basic[cfg.label_col].isin(keep_labels)].copy()

    merged = (
        basic.merge(micro, on="ID", how="inner", suffixes=("", "_micro"))
             .merge(brain, on="ID", how="inner", suffixes=("", "_brain"))
    )

    print("========== Real Data Calibration Summary ==========")
    print("basic:", basic.shape, "micro:", micro.shape, "brain:", brain.shape)
    print("merged:", merged.shape)
    print(merged[cfg.label_col].value_counts())
    print("===================================================\n")
    return basic, micro, brain, merged


def build_basic_features(df: pd.DataFrame):
    cols = ["Sex", "Age", "edu_yr", "BMI", "smoking", "drinking", "exercise_days"]
    cols = [c for c in cols if c in df.columns]
    return safe_numeric(df[cols]).reset_index(drop=True)


def build_brain_features(df: pd.DataFrame):
    candidate_cols = [
        "Left-Hippocampus", "Right-Hippocampus",
        "Left-Amygdala", "Right-Amygdala",
        "lh-entorhinal", "rh-entorhinal",
    ]
    brain_cols = [c for c in candidate_cols if c in df.columns]
    out = pd.DataFrame(index=df.index)

    for c in brain_cols:
        out[c] = pd.to_numeric(df[c], errors="coerce")

    pairs = {
        "Hippocampus": ("Left-Hippocampus", "Right-Hippocampus"),
        "Amygdala": ("Left-Amygdala", "Right-Amygdala"),
        "Entorhinal": ("lh-entorhinal", "rh-entorhinal"),
    }
    for name, (lcol, rcol) in pairs.items():
        if lcol in df.columns and rcol in df.columns:
            L = pd.to_numeric(df[lcol], errors="coerce")
            R = pd.to_numeric(df[rcol], errors="coerce")
            mean = (L + R) / 2.0
            out[f"{name}_mean"] = mean
            out[f"{name}_diff"] = L - R
            out[f"{name}_asymmetry"] = (L - R).abs() / (mean.abs() + 1e-8)

    norm_col = "Total_Labeled_Brain_Volume_mm3"
    if norm_col in df.columns:
        total = pd.to_numeric(df[norm_col], errors="coerce")
        for c in brain_cols:
            out[f"{c}_norm"] = pd.to_numeric(df[c], errors="coerce") / (total + 1e-8)

    return out.reset_index(drop=True)


def get_micro_raw_aligned(merged: pd.DataFrame, micro_original: pd.DataFrame, cfg: Config):
    aligned = merged[["ID"]].merge(micro_original, on="ID", how="left")
    exclude = {"ID", cfg.label_col}
    micro_cols = [c for c in aligned.columns if c not in exclude]
    X = safe_numeric(aligned[micro_cols]).dropna(axis=1, how="all").fillna(0.0).clip(lower=0)
    return X.reset_index(drop=True)


def select_topk_micro_global(X_raw: pd.DataFrame, cfg: Config):
    prevalence = (X_raw > 0).mean(axis=0)
    keep = prevalence[prevalence >= cfg.min_prevalence].index.tolist()
    if len(keep) == 0:
        keep = X_raw.columns.tolist()
    X = X_raw[keep]
    selected = X.var(axis=0).sort_values(ascending=False).head(min(cfg.top_k_species, X.shape[1])).index.tolist()
    return selected


def build_calibration(merged, micro, cfg: Config):
    basic_x = build_basic_features(merged)
    brain_x = build_brain_features(merged)
    patient_x = pd.concat([basic_x, brain_x], axis=1).reset_index(drop=True)

    micro_raw = get_micro_raw_aligned(merged, micro, cfg)
    selected_species = select_topk_micro_global(micro_raw, cfg)
    micro_sel = micro_raw[selected_species].copy().fillna(0.0).clip(lower=0)

    y_real = merged[cfg.label_col].map({"Normal": 0, "MCI": 1, "Dementia": 1}).astype(int).values

    prev = (micro_sel > 0).mean(axis=0).values
    mean_positive = []
    for c in selected_species:
        vals = micro_sel.loc[micro_sel[c] > 0, c]
        mean_positive.append(float(vals.mean()) if len(vals) else 1.0)

    return {
        "real_N": int(len(merged)),
        "synthetic_N": int(max(cfg.n_patients_min, len(merged))),
        "patient_dim": int(patient_x.shape[1]),
        "basic_dim": int(basic_x.shape[1]),
        "brain_dim": int(brain_x.shape[1]),
        "n_species": int(len(selected_species)),
        "selected_species": selected_species,
        "real_risk_rate": float(y_real.mean()),
        "species_prevalence": np.asarray(prev, dtype=float),
        "species_mean_positive": np.asarray(mean_positive, dtype=float),
        "real_patient_feature_mean": np.nanmean(patient_x.values.astype(float), axis=0),
        "real_patient_feature_std": np.nanstd(patient_x.values.astype(float), axis=0) + 1e-6,
        "patient_feature_columns": list(patient_x.columns),
    }


# ============================================================
# 4. Second-order graph-position synthetic data
# ============================================================

def generate_second_order_synthetic(calib: Dict, cfg: Config, seed: int):
    """
    Generate synthetic data where relational-only high risk depends on:
      patient -> species -> brain-vulnerable anchor patients

    Important:
      - relational-only target patients are not brain-vulnerable themselves.
      - species identity leakage is controlled by prevalence balancing.
      - graph models can use anchor patient features through species aggregation.
    """
    set_seed(seed)
    rng = np.random.default_rng(seed)

    N = int(calib["synthetic_N"])
    S = int(calib["n_species"])
    patient_dim = int(calib["patient_dim"])

    # --------------------------------------------------------
    # 1. Weakly aligned latent spaces
    # --------------------------------------------------------
    z_brain = rng.normal(0, 1, size=(N, cfg.latent_dim))
    z_micro_private = rng.normal(0, 1, size=(N, cfg.latent_dim))
    z_micro = (
        cfg.cross_modal_leakage * z_brain
        + np.sqrt(max(1e-8, 1 - cfg.cross_modal_leakage ** 2)) * z_micro_private
    )

    # Patient features follow brain latent space.
    Wp = rng.normal(0, 1, size=(cfg.latent_dim, patient_dim))
    X_patient = z_brain @ Wp + rng.normal(0, cfg.brain_noise, size=(N, patient_dim))

    # Calibrate scale to real patient features.
    real_mean = np.asarray(calib["real_patient_feature_mean"], dtype=float)
    real_std = np.asarray(calib["real_patient_feature_std"], dtype=float)
    if len(real_mean) == patient_dim:
        X_patient = StandardScaler().fit_transform(X_patient)
        X_patient = X_patient * real_std + real_mean
    X_patient = standardize_np(X_patient).astype(np.float32)

    # Brain vulnerability score.
    brain_score = (
        -0.85 * z_brain[:, 0]
        + 0.60 * z_brain[:, 1]
        - 0.40 * z_brain[:, 2]
        + 0.20 * np.sin(z_brain[:, 3])
        + rng.normal(0, 0.75, size=N)
    )
    brain_score = (brain_score - brain_score.mean()) / (brain_score.std() + 1e-8)

    # Anchor patients: high brain vulnerability, used only through graph context.
    n_anchor = int(round(cfg.anchor_fraction * N))
    anchor_idx = np.argsort(-brain_score)[:n_anchor]
    is_anchor = np.zeros(N, dtype=int)
    is_anchor[anchor_idx] = 1

    # --------------------------------------------------------
    # 2. Construct bipartite graph
    # --------------------------------------------------------
    real_prev = np.asarray(calib["species_prevalence"], dtype=float)
    if len(real_prev) != S:
        real_prev = np.full(S, 0.08)

    # Background edges.
    bg_prev = np.clip(0.35 * real_prev + 0.65 * 0.07, 0.015, 0.18)
    A = rng.binomial(1, bg_prev.reshape(1, -1), size=(N, S)).astype(float)

    # Assign species context categories.
    all_species = np.arange(S)
    rng.shuffle(all_species)
    n_high = max(3, int(round(cfg.high_context_species_fraction * S)))
    n_med = max(3, int(round(cfg.medium_context_species_fraction * S)))
    high_context_species = all_species[:n_high]
    medium_context_species = all_species[n_high:n_high + n_med]
    low_context_species = all_species[n_high + n_med:]

    # Anchor patients connect more strongly to high-context species.
    for i in anchor_idx:
        k = rng.integers(cfg.anchor_extra_edges_min, cfg.anchor_extra_edges_max + 1)
        chosen_high = rng.choice(high_context_species, size=min(k, len(high_context_species)), replace=False)
        A[i, chosen_high] = 1

        # Some anchors also connect to medium species.
        if len(medium_context_species) > 0 and rng.random() < 0.40:
            chosen_med = rng.choice(medium_context_species, size=min(2, len(medium_context_species)), replace=False)
            A[i, chosen_med] = 1

    # Non-anchor patients receive a controlled number of edges.
    non_anchor_idx = np.setdiff1d(np.arange(N), anchor_idx)
    for i in non_anchor_idx:
        k = rng.integers(cfg.edges_per_patient_min, cfg.edges_per_patient_max + 1)
        # Most edges are sampled without strong label association.
        pool = np.concatenate([high_context_species, medium_context_species, low_context_species])
        # Give everyone some chance to connect high-context species to reduce single-species leakage.
        probs = np.ones(S) * 0.01
        probs[high_context_species] = 0.35 / len(high_context_species)
        probs[medium_context_species] = 0.35 / max(1, len(medium_context_species))
        probs[low_context_species] = 0.30 / max(1, len(low_context_species))
        probs = probs / probs.sum()
        chosen = rng.choice(np.arange(S), size=min(k, S), replace=False, p=probs)
        A[i, chosen] = 1

    # --------------------------------------------------------
    # 3. Compute true second-order graph-position score
    # --------------------------------------------------------
    # Species context is computed from anchor patients' brain vulnerability.
    species_degree = A.sum(axis=0) + 1e-8
    species_anchor_count = A[is_anchor == 1].sum(axis=0)
    species_anchor_density = species_anchor_count / species_degree

    # Weighted by average anchor brain score through each species.
    anchor_brain_positive = np.maximum(brain_score, 0) * is_anchor
    species_anchor_brain = (A.T @ anchor_brain_positive) / (species_anchor_count + 1e-8)

    # Context score of each species: high if connected to many vulnerable anchors.
    species_context_score = (
        0.65 * species_anchor_density
        + 0.35 * (species_anchor_brain - species_anchor_brain.mean()) / (species_anchor_brain.std() + 1e-8)
    )
    species_context_score = (species_context_score - species_context_score.mean()) / (species_context_score.std() + 1e-8)

    # Patient second-order score: own species neighbors' contextualized anchor signal.
    row_degree = A.sum(axis=1) + 1e-8
    second_order_score = (A @ species_context_score) / row_degree

    # Keep relational-only candidates brain-neutral or brain-low.
    low_brain_pool = np.where(brain_score < np.quantile(brain_score, cfg.target_low_brain_quantile))[0]
    low_brain_pool = np.setdiff1d(low_brain_pool, anchor_idx)

    # --------------------------------------------------------
    # 4. Assign labels
    # --------------------------------------------------------
    n_pos = int(round(cfg.risk_rate * N))
    n_rel_pos = int(round(cfg.relational_positive_fraction * n_pos))
    n_brain_pos = n_pos - n_rel_pos

    # Brain positives are top brain vulnerability anchors.
    brain_pos_idx = np.argsort(-brain_score)[:n_brain_pos]

    # Relational-only positives: top second-order score among low-brain candidates.
    candidate_scores = pd.Series(second_order_score[low_brain_pool], index=low_brain_pool)
    rel_pos_idx = candidate_scores.sort_values(ascending=False).index.values[:n_rel_pos]

    y = np.zeros(N, dtype=int)
    y[brain_pos_idx] = 1
    y[rel_pos_idx] = 1

    relational_only = np.zeros(N, dtype=int)
    relational_only[rel_pos_idx] = 1

    # Ensure relational-only positives are not brain positives.
    relational_only[brain_pos_idx] = 0

    # --------------------------------------------------------
    # 5. Prevalence balancing to reduce species-identity leakage
    # --------------------------------------------------------
    # Add decoy edges to negative patients so single species prevalence is similar
    # across y=0/y=1, without changing the anchor-based second-order context.
    neg_idx = np.where(y == 0)[0]
    pos_idx = np.where(y == 1)[0]

    for s in range(S):
        pos_prev = A[pos_idx, s].mean() if len(pos_idx) else 0
        neg_prev = A[neg_idx, s].mean() if len(neg_idx) else 0
        target_neg_prev = cfg.prevalence_balance_strength * pos_prev + (1 - cfg.prevalence_balance_strength) * neg_prev

        if neg_prev < target_neg_prev:
            needed = int(round((target_neg_prev - neg_prev) * len(neg_idx)))
            candidates = neg_idx[A[neg_idx, s] == 0]
            if needed > 0 and len(candidates) > 0:
                chosen = rng.choice(candidates, size=min(needed, len(candidates)), replace=False)
                A[chosen, s] = 1

    # Recompute graph-position score after balancing.
    species_degree = A.sum(axis=0) + 1e-8
    species_anchor_count = A[is_anchor == 1].sum(axis=0)
    species_anchor_density = species_anchor_count / species_degree
    species_anchor_brain = (A.T @ anchor_brain_positive) / (species_anchor_count + 1e-8)
    species_context_score = (
        0.65 * species_anchor_density
        + 0.35 * (species_anchor_brain - species_anchor_brain.mean()) / (species_anchor_brain.std() + 1e-8)
    )
    species_context_score = (species_context_score - species_context_score.mean()) / (species_context_score.std() + 1e-8)
    second_order_score = (A @ species_context_score) / (A.sum(axis=1) + 1e-8)

    # --------------------------------------------------------
    # 6. Build microbiome features
    # --------------------------------------------------------
    # Abundance is noisy and weakly related to z_micro, but identity alone is balanced.
    Wm = rng.normal(0, 0.25, size=(cfg.latent_dim, S))
    micro_noise = z_micro @ Wm + rng.normal(0, cfg.micro_noise, size=(N, S))
    abundance = A * np.exp(np.clip(0.15 * micro_noise, -1.5, 1.5))
    A_log = np.log1p(abundance).astype(np.float32)

    # Graph aggregation matrix.
    A_presence = (A > 0).astype(np.float32)
    A_norm = A_presence / np.clip(A_presence.sum(axis=1, keepdims=True), 1.0, None)

    # Randomized graph preserving species prevalence approximately.
    A_rand = A_presence.copy()
    for s in range(S):
        rng.shuffle(A_rand[:, s])
    A_rand_norm = A_rand / np.clip(A_rand.sum(axis=1, keepdims=True), 1.0, None)

    # Main flat baselines only see local microbiome summary, not graph neighborhood.
    micro_degree = A_presence.sum(axis=1)
    micro_abund_sum = A_log.sum(axis=1)
    micro_abund_mean = A_log.sum(axis=1) / np.clip(micro_degree, 1.0, None)
    micro_abund_std = np.array([
        A_log[i, A_presence[i] > 0].std() if (A_presence[i] > 0).sum() > 1 else 0.0
        for i in range(N)
    ])
    micro_entropy = []
    for i in range(N):
        vals = A_log[i].clip(min=0)
        p = vals / (vals.sum() + 1e-8)
        micro_entropy.append(float(-(p * np.log(p + 1e-8)).sum()))
    X_micro_summary = np.vstack([
        micro_degree,
        micro_abund_sum,
        micro_abund_mean,
        micro_abund_std,
        np.asarray(micro_entropy),
    ]).T.astype(np.float32)
    X_micro_summary = standardize_np(X_micro_summary).astype(np.float32)

    # Diagnostic flat species-identity baseline.
    X_micro_identity = standardize_np(A_log).astype(np.float32)

    X_early_summary = np.concatenate([X_patient, X_micro_summary], axis=1).astype(np.float32)
    X_early_identity = np.concatenate([X_patient, X_micro_identity], axis=1).astype(np.float32)

    # Diagnostics metadata
    selected_species = calib["selected_species"]
    species_rows = []
    for s in range(S):
        if s in high_context_species:
            group = "high_context"
        elif s in medium_context_species:
            group = "medium_context"
        else:
            group = "low_context"
        species_rows.append({
            "seed": seed,
            "species_index": int(s),
            "species_name": selected_species[s] if s < len(selected_species) else f"species_{s}",
            "context_group": group,
            "anchor_density": float(species_anchor_density[s]),
            "context_score": float(species_context_score[s]),
            "prevalence_y1": float(A_presence[y == 1, s].mean()) if (y == 1).sum() else np.nan,
            "prevalence_y0": float(A_presence[y == 0, s].mean()) if (y == 0).sum() else np.nan,
        })

    return {
        "X_patient": X_patient,
        "X_micro_summary": X_micro_summary,
        "X_micro_identity": X_micro_identity,
        "X_early_summary": X_early_summary,
        "X_early_identity": X_early_identity,
        "A_norm": A_norm.astype(np.float32),
        "A_rand_norm": A_rand_norm.astype(np.float32),
        "A_presence": A_presence.astype(np.float32),
        "A_log": A_log.astype(np.float32),
        "y": y.astype(int),
        "is_anchor": is_anchor.astype(int),
        "relational_only": relational_only.astype(int),
        "brain_score": brain_score.astype(np.float32),
        "second_order_score": second_order_score.astype(np.float32),
        "species_context_score": species_context_score.astype(np.float32),
        "species_anchor_density": species_anchor_density.astype(np.float32),
        "species_info": pd.DataFrame(species_rows),
        "meta": {
            "seed": seed,
            "N": int(N),
            "S": int(S),
            "risk_count": int(y.sum()),
            "risk_rate": float(y.mean()),
            "relational_only_count": int(relational_only.sum()),
            "relational_only_rate": float(relational_only.mean()),
            "brain_positive_count": int(y.sum() - relational_only.sum()),
            "anchor_count": int(is_anchor.sum()),
            "anchor_fraction": float(is_anchor.mean()),
        }
    }


# ============================================================
# 5. Diagnostics
# ============================================================

def cross_modal_cv_r2(A, B, seed=42, n_components=8, n_splits=5):
    n_comp = min(n_components, A.shape[1], B.shape[1], A.shape[0] - 2)
    A_p = PCA(n_components=n_comp, random_state=seed).fit_transform(standardize_np(A))
    B_p = PCA(n_components=n_comp, random_state=seed).fit_transform(standardize_np(B))

    idx = np.arange(A.shape[0])
    rng = np.random.default_rng(seed)
    rng.shuffle(idx)
    folds = np.array_split(idx, n_splits)

    def cv_score(X, Y):
        scores = []
        for te in folds:
            tr = np.setdiff1d(idx, te)
            model = Ridge(alpha=10.0)
            model.fit(X[tr], Y[tr])
            pred = model.predict(X[te])
            sse = ((Y[te] - pred) ** 2).sum()
            sst = ((Y[te] - Y[tr].mean(axis=0)) ** 2).sum()
            scores.append(1 - sse / (sst + 1e-8))
        return float(np.mean(scores))

    return cv_score(A_p, B_p), cv_score(B_p, A_p)


def cca_corrs(A, B, seed=42, n_components=3):
    A_s = standardize_np(A)
    B_s = standardize_np(B)
    A_p = PCA(n_components=min(12, A_s.shape[1], A_s.shape[0] - 2), random_state=seed).fit_transform(A_s)
    B_p = PCA(n_components=min(12, B_s.shape[1], B_s.shape[0] - 2), random_state=seed).fit_transform(B_s)
    n_comp = min(n_components, A_p.shape[1], B_p.shape[1])
    cca = CCA(n_components=n_comp, max_iter=3000)
    U, V = cca.fit_transform(A_p, B_p)
    return [float(np.corrcoef(U[:, i], V[:, i])[0, 1]) for i in range(n_comp)]


def neighbor_overlap(A, B, ks=(5, 10, 20)):
    A_s = standardize_np(A)
    B_s = standardize_np(B)
    out = {}
    for k in ks:
        k_eff = min(k, A.shape[0] - 1)
        nn_a = NearestNeighbors(n_neighbors=k_eff + 1).fit(A_s).kneighbors(A_s, return_distance=False)[:, 1:]
        nn_b = NearestNeighbors(n_neighbors=k_eff + 1).fit(B_s).kneighbors(B_s, return_distance=False)[:, 1:]
        vals = []
        for i in range(A.shape[0]):
            vals.append(len(set(nn_a[i]).intersection(set(nn_b[i]))) / k_eff)
        out[f"neighbor_overlap@{k}"] = float(np.mean(vals))
    return out


def run_diagnostics(data, seed):
    b2m, m2b = cross_modal_cv_r2(data["X_patient"], data["X_micro_identity"], seed=seed)
    cca = cca_corrs(data["X_patient"], data["X_micro_identity"], seed=seed)

    rho_brain_second, _ = spearmanr(data["brain_score"], data["second_order_score"])

    # Species identity leakage diagnostics
    pres = data["A_presence"]
    y = data["y"]
    pos_prev = pres[y == 1].mean(axis=0)
    neg_prev = pres[y == 0].mean(axis=0)
    prev_diff = np.abs(pos_prev - neg_prev)

    # How well does second-order score separate relational-only positives?
    rel = data["relational_only"] == 1
    non_rel = data["relational_only"] == 0
    second_order_gap = float(data["second_order_score"][rel].mean() - data["second_order_score"][non_rel].mean()) if rel.sum() else np.nan

    diag = {
        "seed": seed,
        "brain_to_micro_cv_r2": b2m,
        "micro_to_brain_cv_r2": m2b,
        "cca_1": cca[0] if len(cca) > 0 else np.nan,
        "cca_2": cca[1] if len(cca) > 1 else np.nan,
        "cca_3": cca[2] if len(cca) > 2 else np.nan,
        **neighbor_overlap(data["X_patient"], data["X_micro_identity"]),
        "spearman_brain_vs_second_order_score": float(rho_brain_second),
        "max_abs_species_prevalence_diff": float(np.max(prev_diff)),
        "mean_abs_species_prevalence_diff": float(np.mean(prev_diff)),
        "median_abs_species_prevalence_diff": float(np.median(prev_diff)),
        "second_order_score_gap_relational_vs_other": second_order_gap,
    }
    return diag


# ============================================================
# 6. Models
# ============================================================

class FocalLossBinary(nn.Module):
    def __init__(self, alpha_pos=0.72, gamma=2.0):
        super().__init__()
        self.alpha_pos = alpha_pos
        self.gamma = gamma

    def forward(self, logits, target):
        target = target.float()
        bce = F.binary_cross_entropy_with_logits(logits, target, reduction="none")
        prob = torch.sigmoid(logits)
        pt = torch.where(target == 1, prob, 1 - prob)
        alpha = torch.where(
            target == 1,
            torch.tensor(self.alpha_pos, device=logits.device),
            torch.tensor(1 - self.alpha_pos, device=logits.device),
        )
        return (alpha * (1 - pt).pow(self.gamma) * bce).mean()


class MLPBinary(nn.Module):
    def __init__(self, in_dim, hidden_dim=96, dropout=0.35):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden_dim),
            nn.BatchNorm1d(hidden_dim),
            nn.ReLU(),
            nn.Dropout(dropout),
            nn.Linear(hidden_dim, hidden_dim // 2),
            nn.BatchNorm1d(hidden_dim // 2),
            nn.ReLU(),
            nn.Dropout(dropout),
            nn.Linear(hidden_dim // 2, 1),
        )

    def forward(self, x):
        return self.net(x).squeeze(-1)


class SecondOrderHGNN(nn.Module):
    """
    Pure PyTorch patient-species HGNN.

    Message passing:
      1. patient features -> species:
         species embeddings become contextualized by their neighboring patients.
         If a species connects to brain-vulnerable anchors, its embedding carries that information.
      2. species -> patient:
         target patients receive contextualized messages from their connected species.
    """
    def __init__(self, patient_dim, n_species, hidden_dim=96, latent_dim=32, dropout=0.35, use_gaussian=False):
        super().__init__()
        self.use_gaussian = use_gaussian
        self.dropout = dropout

        self.patient_proj = nn.Linear(patient_dim, hidden_dim)
        self.species_emb = nn.Parameter(torch.randn(n_species, hidden_dim) * 0.03)

        self.species_update = nn.Sequential(
            nn.Linear(hidden_dim * 2, hidden_dim),
            nn.ReLU(),
            nn.Dropout(dropout),
        )

        self.patient_update1 = nn.Sequential(
            nn.Linear(hidden_dim * 2, hidden_dim),
            nn.ReLU(),
            nn.Dropout(dropout),
        )

        self.patient_update2 = nn.Sequential(
            nn.Linear(hidden_dim * 3, hidden_dim),
            nn.ReLU(),
            nn.Dropout(dropout),
        )

        # Gate for second-order context.
        self.context_gate = nn.Sequential(
            nn.Linear(hidden_dim, hidden_dim),
            nn.ReLU(),
            nn.Linear(hidden_dim, hidden_dim),
            nn.Sigmoid(),
        )

        if use_gaussian:
            self.mu = nn.Linear(hidden_dim, latent_dim)
            self.logvar = nn.Linear(hidden_dim, latent_dim)
        else:
            self.det = nn.Linear(hidden_dim, latent_dim)

        self.classifier = nn.Sequential(
            nn.Linear(latent_dim, hidden_dim // 2),
            nn.ReLU(),
            nn.Dropout(dropout),
            nn.Linear(hidden_dim // 2, 1),
        )

    def forward(self, x_patient, A_ps):
        # A_ps: row-normalized patient-species matrix [N, S]
        h_p0 = F.relu(self.patient_proj(x_patient))
        h_s0 = self.species_emb

        # patient -> species
        A_sp = A_ps.t()
        deg_s = A_sp.sum(dim=1, keepdim=True).clamp(min=1.0)
        msg_s = (A_sp @ h_p0) / deg_s
        h_s1 = self.species_update(torch.cat([h_s0, msg_s], dim=1))

        # species -> patient
        msg_p1 = A_ps @ h_s1
        h_p1 = self.patient_update1(torch.cat([h_p0, msg_p1], dim=1))

        # second-order gated message
        msg_p2 = A_ps @ h_s1
        gated = msg_p2 * self.context_gate(msg_p2)
        h_p2 = self.patient_update2(torch.cat([h_p1, msg_p2, gated], dim=1))

        if self.use_gaussian:
            mu = self.mu(h_p2)
            logvar = self.logvar(h_p2).clamp(-8, 6)
            if self.training:
                eps = torch.randn_like(mu)
                z = mu + torch.exp(0.5 * logvar) * eps
            else:
                z = mu
            kl = -0.5 * torch.mean(torch.sum(1 + logvar - mu.pow(2) - logvar.exp(), dim=1))
        else:
            z = self.det(h_p2)
            kl = torch.tensor(0.0, device=x_patient.device)
            mu = z

        logits = self.classifier(z).squeeze(-1)
        return logits, kl, mu


# ============================================================
# 7. Training
# ============================================================

def fit_sklearn_model(model, X, y, train_idx, val_idx, test_idx, cfg: Config):
    imp = SimpleImputer(strategy="median")
    scaler = StandardScaler()

    X_train = scaler.fit_transform(imp.fit_transform(X[train_idx]))
    X_val = scaler.transform(imp.transform(X[val_idx]))
    X_test = scaler.transform(imp.transform(X[test_idx]))

    model.fit(X_train, y[train_idx])
    p_val = model.predict_proba(X_val)[:, 1]
    p_test = model.predict_proba(X_test)[:, 1]
    th = choose_threshold(y[val_idx], p_val, cfg)
    pred = (p_test >= th).astype(int)
    return p_test, pred, th


def fit_mlp_model(X, y, train_idx, val_idx, test_idx, cfg: Config, seed: int):
    set_seed(seed)
    dev = get_device(cfg)

    imp = SimpleImputer(strategy="median")
    scaler = StandardScaler()
    X_train = scaler.fit_transform(imp.fit_transform(X[train_idx]))
    X_val = scaler.transform(imp.transform(X[val_idx]))
    X_test = scaler.transform(imp.transform(X[test_idx]))

    xt = torch.tensor(X_train, dtype=torch.float32, device=dev)
    xv = torch.tensor(X_val, dtype=torch.float32, device=dev)
    xe = torch.tensor(X_test, dtype=torch.float32, device=dev)
    yt = torch.tensor(y[train_idx], dtype=torch.float32, device=dev)
    yv = torch.tensor(y[val_idx], dtype=torch.float32, device=dev)

    model = MLPBinary(X_train.shape[1], cfg.hidden_dim, cfg.dropout).to(dev)
    opt = torch.optim.AdamW(model.parameters(), lr=cfg.lr, weight_decay=cfg.weight_decay)
    criterion = FocalLossBinary(cfg.alpha_pos, cfg.gamma)

    best_state, best_val, bad = None, np.inf, 0
    for epoch in range(cfg.epochs):
        model.train()
        opt.zero_grad()
        loss = criterion(model(xt), yt)
        loss.backward()
        torch.nn.utils.clip_grad_norm_(model.parameters(), 5.0)
        opt.step()

        model.eval()
        with torch.no_grad():
            val_loss = criterion(model(xv), yv).item()

        if val_loss < best_val:
            best_val = val_loss
            best_state = {k: v.detach().cpu().clone() for k, v in model.state_dict().items()}
            bad = 0
        else:
            bad += 1
            if bad >= cfg.patience:
                break

    if best_state is not None:
        model.load_state_dict({k: v.to(dev) for k, v in best_state.items()})

    model.eval()
    with torch.no_grad():
        p_val = torch.sigmoid(model(xv)).detach().cpu().numpy()
        p_test = torch.sigmoid(model(xe)).detach().cpu().numpy()

    th = choose_threshold(y[val_idx], p_val, cfg)
    pred = (p_test >= th).astype(int)
    return p_test, pred, th


def fit_hgnn_model(X_patient, A_norm, y, train_idx, val_idx, test_idx, cfg: Config, seed: int, use_gaussian=False, use_ib=False):
    set_seed(seed)
    dev = get_device(cfg)

    # Scale patient features using all feature distribution. This benchmark is transductive in graph topology,
    # but labels are used only on train nodes.
    X_scaled = standardize_np(X_patient).astype(np.float32)

    x = torch.tensor(X_scaled, dtype=torch.float32, device=dev)
    A = torch.tensor(A_norm, dtype=torch.float32, device=dev)
    yt = torch.tensor(y, dtype=torch.float32, device=dev)

    train_t = torch.tensor(train_idx, dtype=torch.long, device=dev)
    val_t = torch.tensor(val_idx, dtype=torch.long, device=dev)
    test_t = torch.tensor(test_idx, dtype=torch.long, device=dev)

    model = SecondOrderHGNN(
        patient_dim=X_patient.shape[1],
        n_species=A_norm.shape[1],
        hidden_dim=cfg.hidden_dim,
        latent_dim=cfg.latent_dim_model,
        dropout=cfg.dropout,
        use_gaussian=use_gaussian,
    ).to(dev)

    opt = torch.optim.AdamW(model.parameters(), lr=cfg.lr, weight_decay=cfg.weight_decay)
    criterion = FocalLossBinary(cfg.alpha_pos, cfg.gamma)

    best_state, best_val, bad = None, np.inf, 0
    for epoch in range(cfg.epochs):
        model.train()
        opt.zero_grad()
        logits, kl, _ = model(x, A)
        loss = criterion(logits[train_t], yt[train_t])
        if use_ib and use_gaussian:
            loss = loss + cfg.beta * kl
        loss.backward()
        torch.nn.utils.clip_grad_norm_(model.parameters(), 5.0)
        opt.step()

        model.eval()
        with torch.no_grad():
            logits_v, kl_v, _ = model(x, A)
            val_loss = criterion(logits_v[val_t], yt[val_t])
            if use_ib and use_gaussian:
                val_loss = val_loss + cfg.beta * kl_v
            val_loss = val_loss.item()

        if val_loss < best_val:
            best_val = val_loss
            best_state = {k: v.detach().cpu().clone() for k, v in model.state_dict().items()}
            bad = 0
        else:
            bad += 1
            if bad >= cfg.patience:
                break

    if best_state is not None:
        model.load_state_dict({k: v.to(dev) for k, v in best_state.items()})

    model.eval()
    with torch.no_grad():
        logits_all, _, emb = model(x, A)
        p_all = torch.sigmoid(logits_all).detach().cpu().numpy()

    p_val = p_all[val_idx]
    p_test = p_all[test_idx]
    th = choose_threshold(y[val_idx], p_val, cfg)
    pred = (p_test >= th).astype(int)
    return p_test, pred, th, p_all, emb.detach().cpu().numpy()


def evaluate_one_seed(data, cfg: Config, seed: int):
    y = data["y"]
    train_idx, val_idx, test_idx = split_indices(y, seed)

    rows = []

    def add_row(model_name, p_test, pred, th, seconds):
        m = binary_metrics(y[test_idx], p_test, pred=pred)
        rel_mask = data["relational_only"][test_idx] == 1
        brain_pos_mask = (y[test_idx] == 1) & (data["relational_only"][test_idx] == 0)
        anchor_mask = data["is_anchor"][test_idx] == 1

        m.update({
            "seed": seed,
            "model": model_name,
            "threshold": th,
            "seconds": seconds,
            "relational_only_recall": float(pred[rel_mask].mean()) if rel_mask.sum() else np.nan,
            "relational_only_n_test": int(rel_mask.sum()),
            "brain_positive_recall": float(pred[brain_pos_mask].mean()) if brain_pos_mask.sum() else np.nan,
            "anchor_predicted_risk_rate": float(pred[anchor_mask].mean()) if anchor_mask.sum() else np.nan,
        })
        rows.append(m)

    # --------------------------------------------------------
    # Main non-graph baselines: no graph-neighborhood context
    # --------------------------------------------------------
    sklearn_specs = [
        ("LogReg-BrainOnly", LogisticRegression(max_iter=2500, class_weight="balanced"), data["X_patient"]),
        ("LogReg-LocalMicroSummary", LogisticRegression(max_iter=2500, class_weight="balanced"), data["X_micro_summary"]),
        ("LogReg-EarlyFusionLocalSummary", LogisticRegression(max_iter=2500, class_weight="balanced"), data["X_early_summary"]),
        ("RF-BrainOnly", RandomForestClassifier(n_estimators=500, random_state=seed, class_weight="balanced_subsample", min_samples_leaf=2), data["X_patient"]),
        ("RF-LocalMicroSummary", RandomForestClassifier(n_estimators=500, random_state=seed, class_weight="balanced_subsample", min_samples_leaf=2), data["X_micro_summary"]),
        ("RF-EarlyFusionLocalSummary", RandomForestClassifier(n_estimators=500, random_state=seed, class_weight="balanced_subsample", min_samples_leaf=2), data["X_early_summary"]),
    ]

    # Diagnostic identity baselines: included only to detect leakage.
    sklearn_specs += [
        ("DIAGNOSTIC-LogReg-EarlyFusionSpeciesIdentity", LogisticRegression(max_iter=2500, class_weight="balanced"), data["X_early_identity"]),
        ("DIAGNOSTIC-RF-EarlyFusionSpeciesIdentity", RandomForestClassifier(n_estimators=500, random_state=seed, class_weight="balanced_subsample", min_samples_leaf=2), data["X_early_identity"]),
    ]

    for name, model, X in sklearn_specs:
        t0 = time.time()
        p, pred, th = fit_sklearn_model(model, X, y, train_idx, val_idx, test_idx, cfg)
        add_row(name, p, pred, th, time.time() - t0)

    # MLP baselines
    mlp_specs = [
        ("MLP-Focal-BrainOnly", data["X_patient"]),
        ("MLP-Focal-LocalMicroSummary", data["X_micro_summary"]),
        ("MLP-Focal-EarlyFusionLocalSummary", data["X_early_summary"]),
        ("DIAGNOSTIC-MLP-Focal-EarlyFusionSpeciesIdentity", data["X_early_identity"]),
    ]
    for name, X in mlp_specs:
        t0 = time.time()
        p, pred, th = fit_mlp_model(X, y, train_idx, val_idx, test_idx, cfg, seed)
        add_row(name, p, pred, th, time.time() - t0)

    # Graph models
    graph_specs = [
        ("HGNN-Focal-RandomizedEdges", data["A_rand_norm"], False, False),
        ("HGNN-Focal-RealEdges", data["A_norm"], False, False),
        ("HGNN-Gaussian-Focal-RealEdges", data["A_norm"], True, False),
        ("VGIB-HGNN-Focal-Proposed", data["A_norm"], True, True),
    ]

    for name, A_mat, use_g, use_ib in graph_specs:
        t0 = time.time()
        p, pred, th, p_all, emb = fit_hgnn_model(
            data["X_patient"], A_mat, y,
            train_idx, val_idx, test_idx,
            cfg, seed, use_gaussian=use_g, use_ib=use_ib
        )
        add_row(name, p, pred, th, time.time() - t0)

    return pd.DataFrame(rows)


# ============================================================
# 8. Summary
# ============================================================

def summarize_mean_std(df: pd.DataFrame):
    metrics = [
        "auc", "pr_auc", "risk_recall", "risk_precision", "risk_f1",
        "macro_f1", "balanced_acc", "predicted_risk_rate",
        "relational_only_recall", "brain_positive_recall",
        "anchor_predicted_risk_rate", "seconds"
    ]
    rows = []
    for model, sub in df.groupby("model"):
        row = {"model": model}
        for c in metrics:
            row[c + "_mean"] = float(sub[c].mean())
            row[c + "_std"] = float(sub[c].std(ddof=0))
            row[c + "_mean_std"] = f"{sub[c].mean():.3f} ± {sub[c].std(ddof=0):.3f}"
        rows.append(row)
    return pd.DataFrame(rows).sort_values("risk_f1_mean", ascending=False)


def paired_seed_bootstrap(df: pd.DataFrame, proposed="VGIB-HGNN-Focal-Proposed"):
    metrics = [
        "auc", "pr_auc", "risk_recall", "risk_precision", "risk_f1",
        "relational_only_recall", "brain_positive_recall"
    ]
    baselines = [m for m in df["model"].unique() if m != proposed]
    rng = np.random.default_rng(42)
    rows = []

    for b in baselines:
        pivot = df.pivot_table(index="seed", columns="model", values=metrics)
        for metric in metrics:
            try:
                a_vals = pivot[metric][proposed]
                b_vals = pivot[metric][b]
            except Exception:
                continue
            common = pd.concat([a_vals, b_vals], axis=1).dropna()
            if len(common) < 2:
                continue
            av = common.iloc[:, 0].values
            bv = common.iloc[:, 1].values
            n = len(av)
            diffs = []
            for _ in range(5000):
                idx = rng.integers(0, n, size=n)
                diffs.append((av[idx] - bv[idx]).mean())
            diffs = np.asarray(diffs)
            rows.append({
                "model_A": proposed,
                "model_B": b,
                "metric": metric,
                "mean_diff_A_minus_B": float((av - bv).mean()),
                "ci_lower": float(np.quantile(diffs, 0.025)),
                "ci_upper": float(np.quantile(diffs, 0.975)),
                "p_two_sided": float(min(1.0, 2 * min((diffs <= 0).mean(), (diffs >= 0).mean()))),
                "n_seeds": int(n),
            })
    return pd.DataFrame(rows)


# ============================================================
# 9. Main
# ============================================================

def main(cfg: Config = CFG):
    ensure_dir(cfg.output_dir)
    with open(os.path.join(cfg.output_dir, "00_config.json"), "w", encoding="utf-8") as f:
        json.dump(asdict(cfg), f, indent=2, ensure_ascii=False)

    basic, micro, brain, merged = load_real_data_for_calibration(cfg)
    calib = build_calibration(merged, micro, cfg)

    pd.DataFrame([{
        "real_N": calib["real_N"],
        "synthetic_N": calib["synthetic_N"],
        "patient_dim": calib["patient_dim"],
        "basic_dim": calib["basic_dim"],
        "brain_dim": calib["brain_dim"],
        "n_species": calib["n_species"],
        "real_risk_rate": calib["real_risk_rate"],
        "synthetic_risk_rate": cfg.risk_rate,
    }]).to_csv(os.path.join(cfg.output_dir, "00_real_calibration_inventory.csv"), index=False, encoding="utf-8-sig")

    pd.DataFrame({
        "species_index": np.arange(len(calib["selected_species"])),
        "species_name": calib["selected_species"],
        "real_prevalence": calib["species_prevalence"],
        "real_mean_positive_abundance": calib["species_mean_positive"],
    }).to_csv(os.path.join(cfg.output_dir, "00_selected_species_from_real_data.csv"), index=False, encoding="utf-8-sig")

    print("Running second-order graph-position synthetic benchmark on:", get_device(cfg))

    all_perf = []
    all_diag = []
    all_meta = []
    all_species_info = []

    for seed in cfg.seeds:
        print(f"\n================ Seed {seed} ================")
        data = generate_second_order_synthetic(calib, cfg, seed)
        diag = run_diagnostics(data, seed)
        perf = evaluate_one_seed(data, cfg, seed)

        print("\nDiagnostics:")
        for k, v in diag.items():
            if k != "seed":
                print(f"  {k}: {v:.4f}" if isinstance(v, float) else f"  {k}: {v}")

        show_cols = ["model", "auc", "pr_auc", "risk_recall", "risk_precision", "risk_f1", "relational_only_recall"]
        print("\nPerformance:")
        print(perf[show_cols].sort_values("risk_f1", ascending=False).to_string(index=False))

        all_perf.append(perf)
        all_diag.append(pd.DataFrame([diag]))
        all_meta.append(pd.DataFrame([data["meta"]]))
        all_species_info.append(data["species_info"])

    perf_df = pd.concat(all_perf, ignore_index=True)
    diag_df = pd.concat(all_diag, ignore_index=True)
    meta_df = pd.concat(all_meta, ignore_index=True)
    species_df = pd.concat(all_species_info, ignore_index=True)

    summary_df = summarize_mean_std(perf_df)
    boot_df = paired_seed_bootstrap(perf_df)

    save_csv(perf_df, os.path.join(cfg.output_dir, "RQ4_second_order_all_seed_performance.csv"))
    save_csv(summary_df, os.path.join(cfg.output_dir, "RQ4_second_order_summary_mean_std.csv"))
    save_csv(diag_df, os.path.join(cfg.output_dir, "RQ4_second_order_diagnostics_by_seed.csv"))
    save_csv(pd.DataFrame([diag_df.drop(columns=["seed"]).mean(numeric_only=True).to_dict()]), os.path.join(cfg.output_dir, "RQ4_second_order_diagnostics_summary.csv"))
    save_csv(meta_df, os.path.join(cfg.output_dir, "RQ4_second_order_meta_by_seed.csv"))
    save_csv(species_df, os.path.join(cfg.output_dir, "RQ4_second_order_species_context_info.csv"))
    save_csv(boot_df, os.path.join(cfg.output_dir, "RQ4_second_order_paired_bootstrap_over_seeds.csv"))

    print("\n================ FINAL SUMMARY ================")
    print(summary_df[[
        "model",
        "auc_mean_std", "pr_auc_mean_std",
        "risk_recall_mean_std", "risk_precision_mean_std", "risk_f1_mean_std",
        "relational_only_recall_mean_std"
    ]].to_string(index=False))

    print("\nOutputs saved to:", cfg.output_dir)
    print("Key files:")
    print("  - RQ4_second_order_summary_mean_std.csv")
    print("  - RQ4_second_order_diagnostics_summary.csv")
    print("  - RQ4_second_order_paired_bootstrap_over_seeds.csv")
    print("  - RQ4_second_order_all_seed_performance.csv")


if __name__ == "__main__":
    main(CFG)

"""**synthetic benchmark_v2**"""

# ============================================================
# ICDM RQ4 Stronger Synthetic Benchmark
# Real-data-calibrated RELATIONAL-ONLY High-Risk Recovery
#
# Purpose
# -------
# This script fixes the previous synthetic benchmark problem:
#   earlier synthetic microbiome labels were too feature-level, so early fusion
#   could solve them directly.
#
# This version creates a harder controlled benchmark:
#   1. It first READS your real data files to calibrate N, feature dimensions,
#      selected species names, prevalence, and abundance scale.
#   2. It generates weakly aligned brain and microbiome modalities.
#   3. It creates high-risk labels from higher-order patient-species MOTIFS:
#        - single species marginal prevalence is deliberately balanced;
#        - risk is driven by co-occurrence modules / shared rare hubs;
#        - early fusion sees individual species columns, but univariate signal is weak;
#        - graph models can exploit patient-species relational structure.
#   4. It reports both overall screening metrics and relational-only recall.
#
# Expected Colab files
# --------------------
#   /content/data.csv
#   /content/micro.csv
#   /content/all_brain_result_1(3).csv
#
# Output folder
# -------------
#   /content/icdm_relational_only_synthetic_outputs/
#
# Colab command
# -------------
#   !python icdm_relational_only_synthetic_benchmark.py
#
# Dependencies
# ------------
#   pip install numpy pandas scikit-learn scipy torch
#
# Notes
# -----
# - This script does NOT require torch-geometric.
# - The Heterogeneous GNN is implemented in pure PyTorch using a
#   patient-species incidence matrix.
# - It intentionally includes randomized-edge and flattened early-fusion controls.
# ============================================================

import os
import re
import json
import time
import random
import warnings
from dataclasses import dataclass, asdict
from typing import Dict, List, Tuple, Optional

import numpy as np
import pandas as pd

from sklearn.impute import SimpleImputer
from sklearn.preprocessing import StandardScaler
from sklearn.model_selection import train_test_split
from sklearn.metrics import (
    roc_auc_score,
    average_precision_score,
    f1_score,
    recall_score,
    precision_score,
    balanced_accuracy_score,
    accuracy_score,
    brier_score_loss,
)
from sklearn.linear_model import LogisticRegression, Ridge
from sklearn.ensemble import RandomForestClassifier
from sklearn.decomposition import PCA
from sklearn.cross_decomposition import CCA
from sklearn.neighbors import NearestNeighbors

from scipy.stats import spearmanr

import torch
import torch.nn as nn
import torch.nn.functional as F

warnings.filterwarnings("ignore")


# ============================================================
# 1. Configuration
# ============================================================

@dataclass
class Config:
    # Real-data paths
    basic_path: str = "/content/data.csv"
    micro_path: str = "/content/micro.csv"
    brain_path: str = "/content/all_brain_result_1(3).csv"
    output_dir: str = "/content/icdm_relational_only_synthetic_outputs"

    id_col_basic: str = "ID"
    id_col_micro: str = "ID"
    id_col_brain: str = "Subject_ID"
    label_col: str = "Diagnosis"

    # Real-data calibration
    top_k_species: int = 50
    min_prevalence: float = 0.02
    pseudo_count: float = 1e-6

    # Synthetic data
    seeds: Tuple[int, ...] = (11, 22, 33, 44, 55, 66, 77)
    n_patients_min: int = 700       # If real N is smaller, we upsample synthetic N for stable benchmark.
    risk_rate: float = 0.24
    relational_positive_fraction: float = 0.58  # fraction of positives generated from relational-only motif
    brain_positive_fraction: float = 0.42       # fraction of positives generated from brain signal

    # Weak alignment controls
    cross_modal_leakage: float = 0.025
    brain_noise: float = 1.35
    micro_background_noise: float = 1.25

    # Relational motif design
    n_modules: int = 10
    module_size: int = 4
    n_risk_modules_active: int = 2
    rare_hub_count: int = 6
    motif_edge_strength: float = 3.0
    decoy_edge_strength: float = 2.8
    background_presence: float = 0.06

    # Feature masking for flattened baselines:
    # To make this a true graph-mining benchmark, flat baselines are allowed to see
    # the same species columns, but abundances are noisy and marginal prevalence is balanced.
    # Do NOT set this to True unless you want to intentionally cripple flat baselines.
    mask_flat_microbiome: bool = False

    # Model and training
    hidden_dim: int = 96
    latent_dim: int = 32
    dropout: float = 0.35
    lr: float = 2e-3
    weight_decay: float = 1e-4
    epochs: int = 350
    patience: int = 55
    batch_full_graph: bool = True

    # Focal / IB
    gamma: float = 2.0
    beta: float = 5e-4
    alpha_pos: float = 0.72

    # Threshold selection
    precision_floor: float = 0.50
    threshold_grid_size: int = 181

    # Device
    use_cuda_if_available: bool = True


CFG = Config()

# Allow local testing in /mnt/data if files are there.
if os.path.exists("/mnt/data/data.csv"):
    CFG.basic_path = "/mnt/data/data.csv"
    CFG.micro_path = "/mnt/data/micro.csv"
    CFG.brain_path = "/mnt/data/all_brain_result_1(3).csv"
    CFG.output_dir = "/mnt/data/icdm_relational_only_synthetic_outputs"


# ============================================================
# 2. Utilities
# ============================================================

def set_seed(seed: int):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    torch.cuda.manual_seed_all(seed)


def device_of(cfg: Config):
    if cfg.use_cuda_if_available and torch.cuda.is_available():
        return torch.device("cuda")
    return torch.device("cpu")


def ensure_dir(path: str):
    os.makedirs(path, exist_ok=True)


def save_csv(df: pd.DataFrame, path: str):
    df.to_csv(path, index=False, encoding="utf-8-sig")
    print("Saved:", path)


def extract_tpmic_id(x):
    m = re.search(r"TPMIC\d+", str(x))
    return m.group(0) if m else None


def replace_missing_codes(df: pd.DataFrame):
    return df.replace([999, 999.0, "999", "999.0", "NA", "N/A", "", "nan", "None"], np.nan)


def encode_sex_like(series: pd.Series):
    if pd.api.types.is_numeric_dtype(series):
        return pd.to_numeric(series, errors="coerce")
    mapping = {
        "m": 1, "male": 1, "man": 1, "男": 1, "男性": 1, "1": 1,
        "f": 0, "female": 0, "woman": 0, "女": 0, "女性": 0, "0": 0,
    }
    return series.astype(str).str.strip().str.lower().map(mapping)


def safe_numeric(df: pd.DataFrame):
    out = df.copy()
    for c in out.columns:
        if c.lower() in ["sex", "gender"]:
            out[c] = encode_sex_like(out[c])
        else:
            out[c] = pd.to_numeric(out[c], errors="coerce")
    return out


def standardize_np(X):
    X = pd.DataFrame(X).replace([np.inf, -np.inf], np.nan)
    X = SimpleImputer(strategy="median").fit_transform(X)
    return StandardScaler().fit_transform(X)


def sigmoid(x):
    return 1.0 / (1.0 + np.exp(-x))


def threshold_candidates(cfg: Config):
    return np.linspace(0.02, 0.98, cfg.threshold_grid_size)


def choose_threshold(y_val, prob_val, cfg: Config, policy: str = "max_recall_precision_floor"):
    y_val = np.asarray(y_val).astype(int)
    prob_val = np.asarray(prob_val).astype(float)

    best_t, best_tuple = 0.5, None
    for t in threshold_candidates(cfg):
        pred = (prob_val >= t).astype(int)
        rec = recall_score(y_val, pred, zero_division=0)
        prec = precision_score(y_val, pred, zero_division=0)
        f1 = f1_score(y_val, pred, zero_division=0)
        mf1 = f1_score(y_val, pred, average="macro", zero_division=0)

        if policy == "max_recall_precision_floor":
            # Recall-first screening objective under a precision floor.
            if prec >= cfg.precision_floor:
                score_tuple = (rec, f1, prec)
            else:
                score_tuple = (-1, f1, prec)
        elif policy == "max_risk_f1":
            score_tuple = (f1, rec, prec)
        elif policy == "max_macro_f1":
            score_tuple = (mf1, f1, rec)
        else:
            raise ValueError(policy)

        if best_tuple is None or score_tuple > best_tuple:
            best_tuple = score_tuple
            best_t = t

    # If no threshold satisfies precision floor, fall back to risk F1.
    if best_tuple is not None and best_tuple[0] < 0:
        return choose_threshold(y_val, prob_val, cfg, policy="max_risk_f1")
    return float(best_t)


def binary_metrics(y_true, prob, threshold=0.5, pred=None, prefix=""):
    y_true = np.asarray(y_true).astype(int)
    prob = np.asarray(prob).astype(float)
    if pred is None:
        pred = (prob >= threshold).astype(int)
    else:
        pred = np.asarray(pred).astype(int)

    out = {
        prefix + "auc": np.nan,
        prefix + "pr_auc": np.nan,
        prefix + "risk_recall": recall_score(y_true, pred, zero_division=0),
        prefix + "risk_precision": precision_score(y_true, pred, zero_division=0),
        prefix + "risk_f1": f1_score(y_true, pred, zero_division=0),
        prefix + "macro_f1": f1_score(y_true, pred, average="macro", zero_division=0),
        prefix + "balanced_acc": balanced_accuracy_score(y_true, pred),
        prefix + "acc": accuracy_score(y_true, pred),
        prefix + "predicted_risk_rate": float(np.mean(pred == 1)),
        prefix + "brier": np.nan,
    }
    if len(np.unique(y_true)) == 2:
        out[prefix + "auc"] = roc_auc_score(y_true, prob)
        out[prefix + "pr_auc"] = average_precision_score(y_true, prob)
        out[prefix + "brier"] = brier_score_loss(y_true, np.clip(prob, 1e-6, 1 - 1e-6))
    return out


def train_val_test_split(y, seed):
    idx = np.arange(len(y))
    train_val, test = train_test_split(idx, test_size=0.25, stratify=y, random_state=seed)
    train, val = train_test_split(train_val, test_size=0.22, stratify=y[train_val], random_state=seed + 100)
    return train, val, test


# ============================================================
# 3. Real-data calibration
# ============================================================

def load_real_data_for_calibration(cfg: Config):
    if not (os.path.exists(cfg.basic_path) and os.path.exists(cfg.micro_path) and os.path.exists(cfg.brain_path)):
        raise FileNotFoundError(
            "Expected files not found. Please upload:\n"
            f"  {cfg.basic_path}\n"
            f"  {cfg.micro_path}\n"
            f"  {cfg.brain_path}\n"
        )

    basic = replace_missing_codes(pd.read_csv(cfg.basic_path))
    micro = replace_missing_codes(pd.read_csv(cfg.micro_path))
    brain = replace_missing_codes(pd.read_csv(cfg.brain_path))

    brain["ID"] = brain[cfg.id_col_brain].apply(extract_tpmic_id)
    brain = brain.dropna(subset=["ID"]).copy()

    keep_labels = ["Normal", "MCI", "Dementia"]
    basic[cfg.label_col] = basic[cfg.label_col].astype(str)
    basic = basic[basic[cfg.label_col].isin(keep_labels)].copy()

    merged = (
        basic.merge(micro, on="ID", how="inner", suffixes=("", "_micro"))
             .merge(brain, on="ID", how="inner", suffixes=("", "_brain"))
    )

    print("========== Real Data Calibration Summary ==========")
    print("basic:", basic.shape, "micro:", micro.shape, "brain:", brain.shape)
    print("merged:", merged.shape)
    print(merged[cfg.label_col].value_counts())
    print("===================================================\n")

    return basic, micro, brain, merged


def build_basic_features(df: pd.DataFrame):
    cols = ["Sex", "Age", "edu_yr", "BMI", "smoking", "drinking", "exercise_days"]
    cols = [c for c in cols if c in df.columns]
    return safe_numeric(df[cols]).reset_index(drop=True)


def build_brain_features(df: pd.DataFrame):
    candidate_cols = [
        "Left-Hippocampus", "Right-Hippocampus",
        "Left-Amygdala", "Right-Amygdala",
        "lh-entorhinal", "rh-entorhinal",
    ]
    brain_cols = [c for c in candidate_cols if c in df.columns]
    out = pd.DataFrame(index=df.index)

    for c in brain_cols:
        out[c] = pd.to_numeric(df[c], errors="coerce")

    pairs = {
        "Hippocampus": ("Left-Hippocampus", "Right-Hippocampus"),
        "Amygdala": ("Left-Amygdala", "Right-Amygdala"),
        "Entorhinal": ("lh-entorhinal", "rh-entorhinal"),
    }
    for name, (lcol, rcol) in pairs.items():
        if lcol in df.columns and rcol in df.columns:
            L = pd.to_numeric(df[lcol], errors="coerce")
            R = pd.to_numeric(df[rcol], errors="coerce")
            mean = (L + R) / 2.0
            out[f"{name}_mean"] = mean
            out[f"{name}_diff"] = L - R
            out[f"{name}_asymmetry"] = (L - R).abs() / (mean.abs() + 1e-8)

    norm_col = "Total_Labeled_Brain_Volume_mm3"
    if norm_col in df.columns:
        total = pd.to_numeric(df[norm_col], errors="coerce")
        for c in brain_cols:
            out[f"{c}_norm"] = pd.to_numeric(df[c], errors="coerce") / (total + 1e-8)

    return out.reset_index(drop=True)


def get_micro_raw_aligned(merged: pd.DataFrame, micro_original: pd.DataFrame, cfg: Config):
    aligned = merged[["ID"]].merge(micro_original, on="ID", how="left")
    exclude = {"ID", cfg.label_col}
    micro_cols = [c for c in aligned.columns if c not in exclude]
    X = safe_numeric(aligned[micro_cols]).dropna(axis=1, how="all").fillna(0.0).clip(lower=0)
    return X.reset_index(drop=True)


def select_topk_micro_global(X_raw: pd.DataFrame, cfg: Config):
    prevalence = (X_raw > 0).mean(axis=0)
    keep = prevalence[prevalence >= cfg.min_prevalence].index.tolist()
    if len(keep) == 0:
        keep = X_raw.columns.tolist()
    X = X_raw[keep]
    selected = X.var(axis=0).sort_values(ascending=False).head(min(cfg.top_k_species, X.shape[1])).index.tolist()
    return selected


def build_real_calibration(merged, micro, cfg: Config):
    basic_x = build_basic_features(merged)
    brain_x = build_brain_features(merged)
    patient_x = pd.concat([basic_x, brain_x], axis=1).reset_index(drop=True)

    micro_raw = get_micro_raw_aligned(merged, micro, cfg)
    selected_species = select_topk_micro_global(micro_raw, cfg)
    micro_sel = micro_raw[selected_species].copy().fillna(0.0).clip(lower=0)

    real_y = merged[cfg.label_col].map({"Normal": 0, "MCI": 1, "Dementia": 1}).astype(int).values
    real_risk_rate = float(real_y.mean())

    prevalence = (micro_sel > 0).mean(axis=0).values
    mean_positive = []
    for c in selected_species:
        vals = micro_sel.loc[micro_sel[c] > 0, c]
        mean_positive.append(float(vals.mean()) if len(vals) > 0 else 1.0)
    mean_positive = np.asarray(mean_positive, dtype=float)
    mean_positive = np.where(np.isfinite(mean_positive), mean_positive, 1.0)

    calibration = {
        "real_N": int(len(merged)),
        "synthetic_N": int(max(cfg.n_patients_min, len(merged))),
        "patient_dim": int(patient_x.shape[1]),
        "basic_dim": int(basic_x.shape[1]),
        "brain_dim": int(brain_x.shape[1]),
        "n_species": int(len(selected_species)),
        "selected_species": selected_species,
        "real_risk_rate": real_risk_rate,
        "species_prevalence": prevalence,
        "species_mean_positive": mean_positive,
        "real_patient_feature_mean": np.nanmean(patient_x.values.astype(float), axis=0),
        "real_patient_feature_std": np.nanstd(patient_x.values.astype(float), axis=0) + 1e-6,
        "patient_feature_columns": list(patient_x.columns),
    }
    return calibration


# ============================================================
# 4. Relational-only synthetic generation
# ============================================================

def balanced_module_assignment(n_species: int, cfg: Config, rng: np.random.Generator):
    """
    Partition selected species into modules.
    Each module contains several species. Risk is generated by co-occurrence motifs,
    not by single species abundance.
    """
    species_idx = np.arange(n_species)
    rng.shuffle(species_idx)

    max_modules_by_species = n_species // cfg.module_size
    n_modules = min(cfg.n_modules, max_modules_by_species)
    modules = []
    for m in range(n_modules):
        start = m * cfg.module_size
        modules.append(species_idx[start:start + cfg.module_size].tolist())

    leftover = species_idx[n_modules * cfg.module_size:].tolist()
    return modules, leftover


def inject_balanced_motif_edges(
    A: np.ndarray,
    y: np.ndarray,
    relational_only: np.ndarray,
    modules: List[List[int]],
    hubs: List[int],
    cfg: Config,
    rng: np.random.Generator
):
    """
    Core relational-only design.

    Positives:
      - relational-only positives activate multiple full modules plus rare hubs.
      - risk is the module co-occurrence / hub-sharing motif.

    Negatives:
      - decoy negatives activate single modules or partial modules, balancing
        individual species prevalence.
      - this makes single species weakly informative.

    This deliberately weakens flat feature-level signal while preserving
    graph-topological signal.
    """
    N, S = A.shape
    pos_idx = np.where(y == 1)[0]
    rel_idx = np.where(relational_only == 1)[0]
    neg_idx = np.where(y == 0)[0]

    # Relational positives: multiple complete modules + one rare hub.
    for i in rel_idx:
        chosen_mods = rng.choice(len(modules), size=cfg.n_risk_modules_active, replace=False)
        for m in chosen_mods:
            for s in modules[m]:
                A[i, s] += cfg.motif_edge_strength + rng.normal(0, 0.25)
        # rare hub creates shared second-order neighborhood
        if len(hubs) > 0:
            hub = rng.choice(hubs)
            A[i, hub] += cfg.motif_edge_strength + rng.normal(0, 0.20)

    # Brain-driven positives: some partial modules, less complete co-occurrence.
    brain_pos_idx = np.setdiff1d(pos_idx, rel_idx)
    for i in brain_pos_idx:
        m = rng.integers(0, len(modules))
        partial = rng.choice(modules[m], size=max(1, len(modules[m]) // 2), replace=False)
        for s in partial:
            A[i, s] += 1.2 + rng.normal(0, 0.25)

    # Decoy negatives: activate individual modules partially / singly.
    # This balances marginal species prevalence and makes flat univariate signal weak.
    for i in neg_idx:
        # some negatives contain many individual risk species but not complete motifs
        if rng.random() < 0.55:
            m = rng.integers(0, len(modules))
            one_or_two = rng.choice(modules[m], size=rng.integers(1, max(2, len(modules[m]) - 1)), replace=False)
            for s in one_or_two:
                A[i, s] += cfg.decoy_edge_strength + rng.normal(0, 0.25)
        # some negatives contain a hub without module completion
        if len(hubs) > 0 and rng.random() < 0.35:
            A[i, rng.choice(hubs)] += cfg.decoy_edge_strength + rng.normal(0, 0.25)

    A = np.clip(A, 0.0, None)
    return A


def generate_relational_only_synthetic(calib: Dict, cfg: Config, seed: int):
    """
    Real-data-calibrated synthetic benchmark with relational-only high-risk recovery.
    """
    set_seed(seed)
    rng = np.random.default_rng(seed)

    N = int(calib["synthetic_N"])
    S = int(calib["n_species"])
    patient_dim = int(calib["patient_dim"])

    # --------------------------------------------------------
    # 1. Weakly aligned latent spaces
    # --------------------------------------------------------
    latent_dim = 8
    z_brain = rng.normal(0, 1, size=(N, latent_dim))
    z_micro_private = rng.normal(0, 1, size=(N, latent_dim))
    z_micro = (
        cfg.cross_modal_leakage * z_brain
        + np.sqrt(max(1e-8, 1 - cfg.cross_modal_leakage ** 2)) * z_micro_private
    )

    # --------------------------------------------------------
    # 2. Patient features: demographic + brain-like features
    # --------------------------------------------------------
    Wp = rng.normal(0, 1, size=(latent_dim, patient_dim))
    X_patient = z_brain @ Wp + rng.normal(0, cfg.brain_noise, size=(N, patient_dim))

    # Calibrate rough scale to real patient feature distribution.
    real_mean = np.asarray(calib["real_patient_feature_mean"], dtype=float)
    real_std = np.asarray(calib["real_patient_feature_std"], dtype=float)
    if len(real_mean) == patient_dim:
        X_patient = StandardScaler().fit_transform(X_patient)
        X_patient = X_patient * real_std + real_mean
    X_patient = standardize_np(X_patient)

    # Brain score creates some positives, but not relational-only positives.
    brain_score = (
        -0.8 * z_brain[:, 0]
        + 0.55 * z_brain[:, 1]
        - 0.35 * z_brain[:, 2]
        + rng.normal(0, 0.85, size=N)
    )
    brain_score = (brain_score - brain_score.mean()) / (brain_score.std() + 1e-8)

    # --------------------------------------------------------
    # 3. Decide labels by two mechanisms
    # --------------------------------------------------------
    n_pos = int(round(cfg.risk_rate * N))
    n_rel_pos = int(round(cfg.relational_positive_fraction * n_pos))
    n_brain_pos = n_pos - n_rel_pos

    # Brain positives: top brain score.
    brain_order = np.argsort(-brain_score)
    brain_pos_idx = brain_order[:n_brain_pos]

    # Relational positives: deliberately not high brain score.
    neutral_pool = np.where(brain_score < np.quantile(brain_score, 0.58))[0]
    neutral_pool = np.setdiff1d(neutral_pool, brain_pos_idx)
    if len(neutral_pool) < n_rel_pos:
        neutral_pool = np.setdiff1d(np.arange(N), brain_pos_idx)
    rel_pos_idx = rng.choice(neutral_pool, size=n_rel_pos, replace=False)

    y = np.zeros(N, dtype=int)
    y[brain_pos_idx] = 1
    y[rel_pos_idx] = 1

    relational_only = np.zeros(N, dtype=int)
    relational_only[rel_pos_idx] = 1

    # --------------------------------------------------------
    # 4. Generate microbiome background
    # --------------------------------------------------------
    modules, leftover = balanced_module_assignment(S, cfg, rng)

    # Choose rare hubs from leftover if possible; otherwise from random species.
    hub_pool = leftover if len(leftover) >= cfg.rare_hub_count else list(np.arange(S))
    hubs = rng.choice(hub_pool, size=min(cfg.rare_hub_count, len(hub_pool)), replace=False).tolist()

    # Background presence calibrated from real prevalence but dampened.
    real_prev = np.asarray(calib["species_prevalence"], dtype=float)
    real_mean_pos = np.asarray(calib["species_mean_positive"], dtype=float)
    if len(real_prev) != S:
        real_prev = np.full(S, cfg.background_presence)
    if len(real_mean_pos) != S:
        real_mean_pos = np.ones(S)

    bg_prev = np.clip(0.45 * real_prev + 0.55 * cfg.background_presence, 0.01, 0.20)
    bg_presence = rng.binomial(1, bg_prev.reshape(1, -1), size=(N, S)).astype(float)

    # Generate small noisy positive abundances.
    A = bg_presence * rng.gamma(shape=1.2, scale=0.8, size=(N, S))
    A += rng.normal(0, cfg.micro_background_noise * 0.05, size=(N, S))
    A = np.clip(A, 0.0, None)

    # Inject balanced relational motifs.
    A = inject_balanced_motif_edges(A, y, relational_only, modules, hubs, cfg, rng)

    # Convert to log-like abundance and standardizable flat features.
    A_raw = A.copy()
    A_log = np.log1p(A_raw)

    # Important: marginal balancing pass
    # For every module species, add decoy occurrences to negatives to reduce
    # simple univariate label correlation.
    # This makes risk depend more on complete co-occurrence than single species.
    for module in modules:
        for s in module:
            pos_prev = (A_log[y == 1, s] > 0).mean()
            neg_mask = (y == 0)
            neg_candidates = np.where(neg_mask & (A_log[:, s] <= 0))[0]
            target_neg_prev = min(0.90, max(pos_prev * rng.uniform(0.85, 1.05), cfg.background_presence))
            current_neg_prev = (A_log[y == 0, s] > 0).mean()
            n_need = int(max(0, (target_neg_prev - current_neg_prev) * neg_mask.sum()))
            if n_need > 0 and len(neg_candidates) > 0:
                chosen = rng.choice(neg_candidates, size=min(n_need, len(neg_candidates)), replace=False)
                A_log[chosen, s] = np.log1p(cfg.decoy_edge_strength * rng.uniform(0.7, 1.2, size=len(chosen)))

    # Add some noisy abundance variation.
    A_log = np.clip(A_log + rng.normal(0, 0.03, size=A_log.shape), 0, None)

    # Flat features
    X_micro_flat = standardize_np(A_log)
    if cfg.mask_flat_microbiome:
        # Usually False. Keep option only for stress-testing.
        X_micro_flat = X_micro_flat + rng.normal(0, 1.0, size=X_micro_flat.shape)

    X_all_flat = np.concatenate([X_patient, X_micro_flat], axis=1)

    # --------------------------------------------------------
    # 5. Construct graph matrix for HGNN
    # --------------------------------------------------------
    A_presence = (A_log > 0.02).astype(np.float32)
    A_edge_value = A_log.astype(np.float32)

    # Normalize patient-to-species aggregation by row degree.
    row_sum = A_presence.sum(axis=1, keepdims=True)
    A_norm = A_presence / np.clip(row_sum, 1.0, None)

    # Randomized edges preserving patient degree and species degree approximately by column shuffle.
    A_rand = A_presence.copy()
    for s in range(S):
        rng.shuffle(A_rand[:, s])
    row_sum_rand = A_rand.sum(axis=1, keepdims=True)
    A_rand_norm = A_rand / np.clip(row_sum_rand, 1.0, None)

    # Relational motif score for diagnostic only, not used by models.
    motif_score = np.zeros(N)
    for module in modules:
        module_presence = A_presence[:, module]
        # complete or near-complete co-occurrence
        motif_score += (module_presence.sum(axis=1) >= max(2, len(module) - 1)).astype(float)
    if len(hubs) > 0:
        motif_score += 0.5 * (A_presence[:, hubs].sum(axis=1) > 0).astype(float)

    # Species metadata
    species_info_rows = []
    selected_species = calib["selected_species"]
    for m, module in enumerate(modules):
        for s in module:
            species_info_rows.append({
                "seed": seed,
                "species_index": int(s),
                "species_name": selected_species[s] if s < len(selected_species) else f"species_{s}",
                "module": f"module_{m}",
                "is_hub": int(s in hubs),
            })
    for s in hubs:
        species_info_rows.append({
            "seed": seed,
            "species_index": int(s),
            "species_name": selected_species[s] if s < len(selected_species) else f"species_{s}",
            "module": "rare_hub",
            "is_hub": 1,
        })

    return {
        "X_patient": X_patient.astype(np.float32),
        "X_micro_flat": X_micro_flat.astype(np.float32),
        "X_all_flat": X_all_flat.astype(np.float32),
        "A_norm": A_norm.astype(np.float32),
        "A_rand_norm": A_rand_norm.astype(np.float32),
        "A_presence": A_presence.astype(np.float32),
        "A_log": A_log.astype(np.float32),
        "y": y.astype(int),
        "relational_only": relational_only.astype(int),
        "brain_score": brain_score.astype(np.float32),
        "motif_score": motif_score.astype(np.float32),
        "modules": modules,
        "hubs": hubs,
        "species_info": pd.DataFrame(species_info_rows),
        "meta": {
            "seed": seed,
            "N": int(N),
            "S": int(S),
            "risk_count": int(y.sum()),
            "risk_rate": float(y.mean()),
            "relational_only_count": int(relational_only.sum()),
            "relational_only_rate": float(relational_only.mean()),
            "brain_positive_count": int((y.sum() - relational_only.sum())),
            "n_modules": int(len(modules)),
            "module_size": int(cfg.module_size),
            "rare_hub_count": int(len(hubs)),
        }
    }


# ============================================================
# 5. Weak alignment diagnostics
# ============================================================

def cross_modal_cv_r2(A, B, seed=42, n_components=8, n_splits=5):
    n_comp = min(n_components, A.shape[1], B.shape[1], A.shape[0] - 2)
    A_p = PCA(n_components=n_comp, random_state=seed).fit_transform(standardize_np(A))
    B_p = PCA(n_components=n_comp, random_state=seed).fit_transform(standardize_np(B))

    idx = np.arange(A.shape[0])
    rng = np.random.default_rng(seed)
    rng.shuffle(idx)
    folds = np.array_split(idx, n_splits)

    def cv_score(X, Y):
        scores = []
        for te in folds:
            tr = np.setdiff1d(idx, te)
            model = Ridge(alpha=10.0)
            model.fit(X[tr], Y[tr])
            pred = model.predict(X[te])
            sse = ((Y[te] - pred) ** 2).sum()
            sst = ((Y[te] - Y[tr].mean(axis=0)) ** 2).sum()
            scores.append(1 - sse / (sst + 1e-8))
        return float(np.mean(scores))

    return cv_score(A_p, B_p), cv_score(B_p, A_p)


def cca_corrs(A, B, seed=42, n_components=3):
    A_s = standardize_np(A)
    B_s = standardize_np(B)
    A_p = PCA(n_components=min(12, A_s.shape[1], A_s.shape[0] - 2), random_state=seed).fit_transform(A_s)
    B_p = PCA(n_components=min(12, B_s.shape[1], B_s.shape[0] - 2), random_state=seed).fit_transform(B_s)
    n_comp = min(n_components, A_p.shape[1], B_p.shape[1])
    cca = CCA(n_components=n_comp, max_iter=3000)
    U, V = cca.fit_transform(A_p, B_p)
    return [float(np.corrcoef(U[:, i], V[:, i])[0, 1]) for i in range(n_comp)]


def neighbor_overlap(A, B, ks=(5, 10, 20)):
    A_s = standardize_np(A)
    B_s = standardize_np(B)
    out = {}
    for k in ks:
        k_eff = min(k, A.shape[0] - 1)
        nn_a = NearestNeighbors(n_neighbors=k_eff + 1).fit(A_s).kneighbors(A_s, return_distance=False)[:, 1:]
        nn_b = NearestNeighbors(n_neighbors=k_eff + 1).fit(B_s).kneighbors(B_s, return_distance=False)[:, 1:]
        vals = []
        for i in range(A.shape[0]):
            vals.append(len(set(nn_a[i]).intersection(set(nn_b[i]))) / k_eff)
        out[f"neighbor_overlap@{k}"] = float(np.mean(vals))
    return out


def risk_marker_discordance(brain_score, motif_score, y):
    rho, _ = spearmanr(brain_score, motif_score)
    out = {"spearman_brain_vs_motif_score": float(rho)}
    for q in [0.2, 0.3]:
        b = brain_score >= np.quantile(brain_score, 1 - q)
        m = motif_score >= np.quantile(motif_score, 1 - q)
        inter = np.logical_and(b, m).sum()
        union = np.logical_or(b, m).sum()
        out[f"jaccard_top_{int(q*100)}"] = float(inter / (union + 1e-8))
        out[f"both_high_risk_rate_top_{int(q*100)}"] = float(y[np.logical_and(b, m)].mean()) if inter > 0 else np.nan
    return out


def univariate_species_leakage(A_log, y):
    """
    Diagnostic: if single species are too predictive, this benchmark is not relational-only.
    We report max and mean absolute difference in prevalence by label.
    """
    pres = (A_log > 0.02).astype(float)
    pos_prev = pres[y == 1].mean(axis=0)
    neg_prev = pres[y == 0].mean(axis=0)
    diff = np.abs(pos_prev - neg_prev)
    return {
        "max_abs_species_prevalence_diff": float(np.max(diff)),
        "mean_abs_species_prevalence_diff": float(np.mean(diff)),
        "median_abs_species_prevalence_diff": float(np.median(diff)),
    }


def run_diagnostics(data, seed):
    b2m, m2b = cross_modal_cv_r2(data["X_patient"], data["X_micro_flat"], seed=seed)
    cca = cca_corrs(data["X_patient"], data["X_micro_flat"], seed=seed)
    diag = {
        "seed": seed,
        "brain_to_micro_cv_r2": b2m,
        "micro_to_brain_cv_r2": m2b,
        "cca_1": cca[0] if len(cca) > 0 else np.nan,
        "cca_2": cca[1] if len(cca) > 1 else np.nan,
        "cca_3": cca[2] if len(cca) > 2 else np.nan,
        **neighbor_overlap(data["X_patient"], data["X_micro_flat"]),
        **risk_marker_discordance(data["brain_score"], data["motif_score"], data["y"]),
        **univariate_species_leakage(data["A_log"], data["y"]),
    }
    return diag


# ============================================================
# 6. Models
# ============================================================

class FocalLossBinary(nn.Module):
    def __init__(self, alpha_pos=0.72, gamma=2.0):
        super().__init__()
        self.alpha_pos = alpha_pos
        self.gamma = gamma

    def forward(self, logits, target):
        target = target.float()
        bce = F.binary_cross_entropy_with_logits(logits, target, reduction="none")
        prob = torch.sigmoid(logits)
        pt = torch.where(target == 1, prob, 1 - prob)
        alpha = torch.where(target == 1, torch.tensor(self.alpha_pos, device=logits.device), torch.tensor(1 - self.alpha_pos, device=logits.device))
        return (alpha * (1 - pt).pow(self.gamma) * bce).mean()


class MLPBinary(nn.Module):
    def __init__(self, in_dim, hidden_dim=96, dropout=0.35):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden_dim),
            nn.BatchNorm1d(hidden_dim),
            nn.ReLU(),
            nn.Dropout(dropout),
            nn.Linear(hidden_dim, hidden_dim // 2),
            nn.BatchNorm1d(hidden_dim // 2),
            nn.ReLU(),
            nn.Dropout(dropout),
            nn.Linear(hidden_dim // 2, 1),
        )

    def forward(self, x):
        return self.net(x).squeeze(-1)


class RelationalHeteroGNN(nn.Module):
    """
    Pure PyTorch patient-species HGNN.

    Key idea:
      - Species nodes are shared relational anchors.
      - Patient updates aggregate species embeddings via patient-species matrix.
      - Species updates aggregate patients back.
      - Two rounds allow motif-like patient-species-patient/species interactions.
    """
    def __init__(self, patient_dim, n_species, hidden_dim=96, dropout=0.35, use_gaussian=False, latent_dim=32):
        super().__init__()
        self.use_gaussian = use_gaussian
        self.dropout = dropout

        self.patient_proj = nn.Linear(patient_dim, hidden_dim)

        # Learnable species embeddings + simple species identity signal.
        self.species_emb = nn.Parameter(torch.randn(n_species, hidden_dim) * 0.03)

        self.p_update1 = nn.Sequential(
            nn.Linear(hidden_dim * 2, hidden_dim),
            nn.ReLU(),
            nn.Dropout(dropout),
        )
        self.s_update1 = nn.Sequential(
            nn.Linear(hidden_dim * 2, hidden_dim),
            nn.ReLU(),
            nn.Dropout(dropout),
        )
        self.p_update2 = nn.Sequential(
            nn.Linear(hidden_dim * 3, hidden_dim),
            nn.ReLU(),
            nn.Dropout(dropout),
        )

        # A small nonlinear motif gate: lets model respond to co-occurrence strength.
        self.motif_gate = nn.Sequential(
            nn.Linear(hidden_dim, hidden_dim),
            nn.ReLU(),
            nn.Linear(hidden_dim, hidden_dim),
            nn.Sigmoid(),
        )

        if use_gaussian:
            self.mu = nn.Linear(hidden_dim, latent_dim)
            self.logvar = nn.Linear(hidden_dim, latent_dim)
            cls_in = latent_dim
        else:
            self.det = nn.Linear(hidden_dim, latent_dim)
            cls_in = latent_dim

        self.classifier = nn.Sequential(
            nn.Linear(cls_in, hidden_dim // 2),
            nn.ReLU(),
            nn.Dropout(dropout),
            nn.Linear(hidden_dim // 2, 1),
        )

    def forward(self, x_patient, A_ps):
        # A_ps: normalized patient-species matrix [N, S]
        h_p = F.relu(self.patient_proj(x_patient))
        h_s = self.species_emb

        # species -> patient
        msg_p1 = A_ps @ h_s
        h_p1 = self.p_update1(torch.cat([h_p, msg_p1], dim=1))

        # patient -> species, degree normalized
        A_sp = A_ps.t()
        deg_s = A_sp.sum(dim=1, keepdim=True).clamp(min=1.0)
        msg_s1 = (A_sp @ h_p1) / deg_s
        h_s1 = self.s_update1(torch.cat([h_s, msg_s1], dim=1))

        # species -> patient again
        msg_p2 = A_ps @ h_s1

        # Motif-like gated interaction:
        # high response when multiple informative species embeddings co-occur.
        gate = self.motif_gate(msg_p2)
        motif_msg = msg_p2 * gate

        h_p2 = self.p_update2(torch.cat([h_p1, msg_p2, motif_msg], dim=1))

        if self.use_gaussian:
            mu = self.mu(h_p2)
            logvar = self.logvar(h_p2).clamp(-8, 6)
            if self.training:
                eps = torch.randn_like(mu)
                z = mu + torch.exp(0.5 * logvar) * eps
            else:
                z = mu
            logits = self.classifier(z).squeeze(-1)
            kl = -0.5 * torch.mean(torch.sum(1 + logvar - mu.pow(2) - logvar.exp(), dim=1))
            return logits, kl, mu
        else:
            z = self.det(h_p2)
            logits = self.classifier(z).squeeze(-1)
            return logits, torch.tensor(0.0, device=x_patient.device), z


# ============================================================
# 7. Training and evaluation
# ============================================================

def fit_sklearn_model(model, X, y, train_idx, val_idx, test_idx, cfg: Config):
    imp = SimpleImputer(strategy="median")
    scaler = StandardScaler()

    X_train = scaler.fit_transform(imp.fit_transform(X[train_idx]))
    X_val = scaler.transform(imp.transform(X[val_idx]))
    X_test = scaler.transform(imp.transform(X[test_idx]))

    model.fit(X_train, y[train_idx])
    p_val = model.predict_proba(X_val)[:, 1]
    p_test = model.predict_proba(X_test)[:, 1]
    th = choose_threshold(y[val_idx], p_val, cfg)
    pred_test = (p_test >= th).astype(int)
    return p_test, pred_test, th


def fit_mlp_model(X, y, train_idx, val_idx, test_idx, cfg: Config, seed: int):
    set_seed(seed)
    dev = device_of(cfg)

    imp = SimpleImputer(strategy="median")
    scaler = StandardScaler()
    X_train = scaler.fit_transform(imp.fit_transform(X[train_idx]))
    X_val = scaler.transform(imp.transform(X[val_idx]))
    X_test = scaler.transform(imp.transform(X[test_idx]))

    xt = torch.tensor(X_train, dtype=torch.float32, device=dev)
    xv = torch.tensor(X_val, dtype=torch.float32, device=dev)
    xe = torch.tensor(X_test, dtype=torch.float32, device=dev)
    yt = torch.tensor(y[train_idx], dtype=torch.float32, device=dev)
    yv = torch.tensor(y[val_idx], dtype=torch.float32, device=dev)

    model = MLPBinary(X_train.shape[1], cfg.hidden_dim, cfg.dropout).to(dev)
    opt = torch.optim.AdamW(model.parameters(), lr=cfg.lr, weight_decay=cfg.weight_decay)
    criterion = FocalLossBinary(alpha_pos=cfg.alpha_pos, gamma=cfg.gamma)

    best_state, best_val, bad = None, np.inf, 0
    for epoch in range(cfg.epochs):
        model.train()
        opt.zero_grad()
        loss = criterion(model(xt), yt)
        loss.backward()
        torch.nn.utils.clip_grad_norm_(model.parameters(), 5.0)
        opt.step()

        model.eval()
        with torch.no_grad():
            val_loss = criterion(model(xv), yv).item()

        if val_loss < best_val:
            best_val = val_loss
            best_state = {k: v.detach().cpu().clone() for k, v in model.state_dict().items()}
            bad = 0
        else:
            bad += 1
            if bad >= cfg.patience:
                break

    if best_state is not None:
        model.load_state_dict({k: v.to(dev) for k, v in best_state.items()})

    model.eval()
    with torch.no_grad():
        p_val = torch.sigmoid(model(xv)).detach().cpu().numpy()
        p_test = torch.sigmoid(model(xe)).detach().cpu().numpy()

    th = choose_threshold(y[val_idx], p_val, cfg)
    pred_test = (p_test >= th).astype(int)
    return p_test, pred_test, th


def fit_hgnn_model(X_patient, A_norm, y, train_idx, val_idx, test_idx, cfg: Config, seed: int, use_gaussian=False, use_ib=False):
    set_seed(seed)
    dev = device_of(cfg)

    # Fit patient feature scaler on train only.
    imp = SimpleImputer(strategy="median")
    scaler = StandardScaler()
    X_all_scaled = scaler.fit_transform(imp.fit_transform(X_patient))
    X_all_scaled = X_all_scaled.astype(np.float32)

    x = torch.tensor(X_all_scaled, dtype=torch.float32, device=dev)
    A = torch.tensor(A_norm, dtype=torch.float32, device=dev)
    yt = torch.tensor(y, dtype=torch.float32, device=dev)

    model = RelationalHeteroGNN(
        patient_dim=X_patient.shape[1],
        n_species=A_norm.shape[1],
        hidden_dim=cfg.hidden_dim,
        dropout=cfg.dropout,
        use_gaussian=use_gaussian,
        latent_dim=cfg.latent_dim,
    ).to(dev)

    opt = torch.optim.AdamW(model.parameters(), lr=cfg.lr, weight_decay=cfg.weight_decay)
    criterion = FocalLossBinary(alpha_pos=cfg.alpha_pos, gamma=cfg.gamma)

    train_t = torch.tensor(train_idx, dtype=torch.long, device=dev)
    val_t = torch.tensor(val_idx, dtype=torch.long, device=dev)
    test_t = torch.tensor(test_idx, dtype=torch.long, device=dev)

    best_state, best_val, bad = None, np.inf, 0
    for epoch in range(cfg.epochs):
        model.train()
        opt.zero_grad()
        logits, kl, _ = model(x, A)
        loss = criterion(logits[train_t], yt[train_t])
        if use_ib and use_gaussian:
            loss = loss + cfg.beta * kl
        loss.backward()
        torch.nn.utils.clip_grad_norm_(model.parameters(), 5.0)
        opt.step()

        model.eval()
        with torch.no_grad():
            logits_v, kl_v, _ = model(x, A)
            val_loss = criterion(logits_v[val_t], yt[val_t])
            if use_ib and use_gaussian:
                val_loss = val_loss + cfg.beta * kl_v
            val_loss = val_loss.item()

        if val_loss < best_val:
            best_val = val_loss
            best_state = {k: v.detach().cpu().clone() for k, v in model.state_dict().items()}
            bad = 0
        else:
            bad += 1
            if bad >= cfg.patience:
                break

    if best_state is not None:
        model.load_state_dict({k: v.to(dev) for k, v in best_state.items()})

    model.eval()
    with torch.no_grad():
        logits_all, _, emb = model(x, A)
        p_all = torch.sigmoid(logits_all).detach().cpu().numpy()

    p_val = p_all[val_idx]
    p_test = p_all[test_idx]
    th = choose_threshold(y[val_idx], p_val, cfg)
    pred_test = (p_test >= th).astype(int)
    return p_test, pred_test, th, p_all, emb.detach().cpu().numpy()


def evaluate_one_seed(data, cfg: Config, seed: int):
    y = data["y"]
    train_idx, val_idx, test_idx = train_val_test_split(y, seed)

    rows = []
    prob_cache = {}

    def add_result(model_name, p_test, pred_test, th, elapsed):
        m = binary_metrics(y[test_idx], p_test, pred=pred_test)
        # relational-only recall
        rel_test_mask = data["relational_only"][test_idx] == 1
        if rel_test_mask.sum() > 0:
            rel_recall = float(pred_test[rel_test_mask].mean())
            rel_n = int(rel_test_mask.sum())
        else:
            rel_recall = np.nan
            rel_n = 0
        # brain positives recall
        brain_pos_test_mask = (y[test_idx] == 1) & (data["relational_only"][test_idx] == 0)
        if brain_pos_test_mask.sum() > 0:
            brain_pos_recall = float(pred_test[brain_pos_test_mask].mean())
        else:
            brain_pos_recall = np.nan
        m.update({
            "seed": seed,
            "model": model_name,
            "threshold": th,
            "seconds": elapsed,
            "relational_only_recall": rel_recall,
            "relational_only_n_test": rel_n,
            "brain_positive_recall": brain_pos_recall,
        })
        rows.append(m)
        prob_cache[model_name] = {
            "p_test": p_test,
            "pred_test": pred_test,
            "test_idx": test_idx,
            "threshold": th,
        }

    # ------------------
    # Sklearn baselines
    # ------------------
    sklearn_specs = [
        ("LogReg-BrainOnly", LogisticRegression(max_iter=2500, class_weight="balanced"), data["X_patient"]),
        ("LogReg-MicroOnly", LogisticRegression(max_iter=2500, class_weight="balanced"), data["X_micro_flat"]),
        ("LogReg-EarlyFusionAllTabular", LogisticRegression(max_iter=2500, class_weight="balanced"), data["X_all_flat"]),
        ("RF-BrainOnly", RandomForestClassifier(n_estimators=500, class_weight="balanced_subsample", random_state=seed, min_samples_leaf=2), data["X_patient"]),
        ("RF-MicroOnly", RandomForestClassifier(n_estimators=500, class_weight="balanced_subsample", random_state=seed, min_samples_leaf=2), data["X_micro_flat"]),
        ("RF-EarlyFusionAllTabular", RandomForestClassifier(n_estimators=500, class_weight="balanced_subsample", random_state=seed, min_samples_leaf=2), data["X_all_flat"]),
    ]
    for name, model, X in sklearn_specs:
        t0 = time.time()
        p, pred, th = fit_sklearn_model(model, X, y, train_idx, val_idx, test_idx, cfg)
        add_result(name, p, pred, th, time.time() - t0)

    # ------------------
    # MLP baselines
    # ------------------
    mlp_specs = [
        ("MLP-Focal-BrainOnly", data["X_patient"]),
        ("MLP-Focal-MicroOnly", data["X_micro_flat"]),
        ("MLP-Focal-EarlyFusionAllTabular", data["X_all_flat"]),
    ]
    for name, X in mlp_specs:
        t0 = time.time()
        p, pred, th = fit_mlp_model(X, y, train_idx, val_idx, test_idx, cfg, seed)
        add_result(name, p, pred, th, time.time() - t0)

    # ------------------
    # Graph baselines/proposed
    # ------------------
    graph_specs = [
        ("HGNN-Focal-RandomizedEdges", data["A_rand_norm"], False, False),
        ("HGNN-Focal-RealEdges", data["A_norm"], False, False),
        ("HGNN-Gaussian-Focal-RealEdges", data["A_norm"], True, False),
        ("VGIB-HGNN-Focal-Proposed", data["A_norm"], True, True),
    ]
    for name, A_mat, use_g, use_ib in graph_specs:
        t0 = time.time()
        p, pred, th, p_all, emb = fit_hgnn_model(
            data["X_patient"], A_mat, y, train_idx, val_idx, test_idx,
            cfg, seed, use_gaussian=use_g, use_ib=use_ib
        )
        add_result(name, p, pred, th, time.time() - t0)

    return pd.DataFrame(rows), prob_cache


# ============================================================
# 8. Summary and bootstrap over seeds
# ============================================================

def summarize_mean_std(df: pd.DataFrame):
    metric_cols = [
        "auc", "pr_auc", "risk_recall", "risk_precision", "risk_f1",
        "macro_f1", "balanced_acc", "relational_only_recall", "brain_positive_recall",
        "predicted_risk_rate", "seconds"
    ]
    rows = []
    for model, sub in df.groupby("model"):
        row = {"model": model}
        for c in metric_cols:
            row[c + "_mean"] = float(sub[c].mean())
            row[c + "_std"] = float(sub[c].std(ddof=0))
            row[c + "_mean_std"] = f"{sub[c].mean():.3f} ± {sub[c].std(ddof=0):.3f}"
        rows.append(row)
    return pd.DataFrame(rows).sort_values("risk_f1_mean", ascending=False)


def paired_seed_bootstrap(df: pd.DataFrame, proposed="VGIB-HGNN-Focal-Proposed"):
    metrics = ["auc", "pr_auc", "risk_recall", "risk_precision", "risk_f1", "relational_only_recall", "brain_positive_recall"]
    baselines = [m for m in df["model"].unique() if m != proposed]
    rng = np.random.default_rng(42)
    rows = []
    for b in baselines:
        for metric in metrics:
            pivot = df.pivot_table(index="seed", columns="model", values=metric)
            if proposed not in pivot.columns or b not in pivot.columns:
                continue
            common = pivot[[proposed, b]].dropna()
            if len(common) < 2:
                continue
            a_vals = common[proposed].values
            b_vals = common[b].values
            n = len(common)
            diffs = []
            for _ in range(5000):
                idx = rng.integers(0, n, size=n)
                diffs.append((a_vals[idx] - b_vals[idx]).mean())
            diffs = np.asarray(diffs)
            obs = float((a_vals - b_vals).mean())
            p_two = float(min(1.0, 2 * min((diffs <= 0).mean(), (diffs >= 0).mean())))
            rows.append({
                "model_A": proposed,
                "model_B": b,
                "metric": metric,
                "mean_diff_A_minus_B": obs,
                "ci_lower": float(np.quantile(diffs, 0.025)),
                "ci_upper": float(np.quantile(diffs, 0.975)),
                "p_two_sided": p_two,
                "n_seeds": int(n),
            })
    return pd.DataFrame(rows)


# ============================================================
# 9. Main
# ============================================================

def main(cfg: Config = CFG):
    ensure_dir(cfg.output_dir)
    set_seed(42)

    # Save config
    with open(os.path.join(cfg.output_dir, "00_config.json"), "w", encoding="utf-8") as f:
        json.dump(asdict(cfg), f, indent=2, ensure_ascii=False)

    # Read real data for calibration
    basic, micro, brain, merged = load_real_data_for_calibration(cfg)
    calib = build_real_calibration(merged, micro, cfg)

    calib_public = {
        k: v for k, v in calib.items()
        if k not in ["species_prevalence", "species_mean_positive", "real_patient_feature_mean", "real_patient_feature_std"]
    }
    pd.DataFrame([{
        "real_N": calib["real_N"],
        "synthetic_N": calib["synthetic_N"],
        "patient_dim": calib["patient_dim"],
        "basic_dim": calib["basic_dim"],
        "brain_dim": calib["brain_dim"],
        "n_species": calib["n_species"],
        "real_risk_rate": calib["real_risk_rate"],
        "configured_synthetic_risk_rate": cfg.risk_rate,
    }]).to_csv(os.path.join(cfg.output_dir, "00_real_calibration_inventory.csv"), index=False, encoding="utf-8-sig")

    pd.DataFrame({
        "species_index": np.arange(len(calib["selected_species"])),
        "species_name": calib["selected_species"],
        "real_prevalence": calib["species_prevalence"],
        "real_mean_positive_abundance": calib["species_mean_positive"],
    }).to_csv(os.path.join(cfg.output_dir, "00_selected_species_from_real_data.csv"), index=False, encoding="utf-8-sig")

    print("Running relational-only synthetic benchmark on device:", device_of(cfg))

    all_perf = []
    all_diag = []
    all_meta = []
    all_species_info = []

    for seed in cfg.seeds:
        print(f"\n================ Seed {seed} ================")
        data = generate_relational_only_synthetic(calib, cfg, seed)
        diag = run_diagnostics(data, seed)
        perf, cache = evaluate_one_seed(data, cfg, seed)

        print("\nWeak-alignment diagnostics:")
        for k, v in diag.items():
            if k != "seed":
                print(f"  {k}: {v:.4f}" if isinstance(v, float) else f"  {k}: {v}")

        print("\nPerformance:")
        show_cols = ["model", "auc", "pr_auc", "risk_recall", "risk_precision", "risk_f1", "relational_only_recall"]
        print(perf[show_cols].sort_values("risk_f1", ascending=False).to_string(index=False))

        all_perf.append(perf)
        all_diag.append(pd.DataFrame([diag]))
        all_meta.append(pd.DataFrame([data["meta"]]))
        all_species_info.append(data["species_info"])

    perf_df = pd.concat(all_perf, ignore_index=True)
    diag_df = pd.concat(all_diag, ignore_index=True)
    meta_df = pd.concat(all_meta, ignore_index=True)
    species_df = pd.concat(all_species_info, ignore_index=True)

    summary_df = summarize_mean_std(perf_df)
    boot_df = paired_seed_bootstrap(perf_df)

    # Save outputs
    save_csv(perf_df, os.path.join(cfg.output_dir, "RQ4_relational_only_all_seed_performance.csv"))
    save_csv(summary_df, os.path.join(cfg.output_dir, "RQ4_relational_only_summary_mean_std.csv"))
    save_csv(diag_df, os.path.join(cfg.output_dir, "RQ4_relational_only_weak_alignment_diagnostics.csv"))
    save_csv(pd.DataFrame([diag_df.drop(columns=["seed"]).mean(numeric_only=True).to_dict()]), os.path.join(cfg.output_dir, "RQ4_relational_only_weak_alignment_diagnostics_summary.csv"))
    save_csv(meta_df, os.path.join(cfg.output_dir, "RQ4_relational_only_meta_by_seed.csv"))
    save_csv(species_df, os.path.join(cfg.output_dir, "RQ4_relational_only_species_module_info.csv"))
    save_csv(boot_df, os.path.join(cfg.output_dir, "RQ4_relational_only_paired_bootstrap_over_seeds.csv"))

    print("\n================ FINAL SUMMARY ================")
    print(summary_df[[
        "model",
        "auc_mean_std", "pr_auc_mean_std",
        "risk_recall_mean_std", "risk_precision_mean_std", "risk_f1_mean_std",
        "relational_only_recall_mean_std"
    ]].to_string(index=False))

    print("\nOutputs saved to:", cfg.output_dir)
    print("Key files:")
    print("  - RQ4_relational_only_summary_mean_std.csv")
    print("  - RQ4_relational_only_weak_alignment_diagnostics_summary.csv")
    print("  - RQ4_relational_only_paired_bootstrap_over_seeds.csv")
    print("  - RQ4_relational_only_all_seed_performance.csv")


if __name__ == "__main__":
    main(CFG)

