# ============================================================
# 1. Configuration
# ============================================================

@dataclass
class Config:
    # Real files used for calibration
    basic_path: str = "/content/data.csv"
    micro_path: str = "/content/micro.csv"
    brain_path: str = "/content/all_brain_result_1(3).csv"
    output_dir: str = "/content/icdm_synthetic_weak_alignment_outputs_v2"

    id_col_basic: str = "ID"
    id_col_micro: str = "ID"
    id_col_brain: str = "Subject_ID"
    label_col: str = "Diagnosis"

    random_seed: int = 42
    seeds: Tuple[int, ...] = (42, 52, 62, 72, 82)
    n_splits: int = 5

    # Real-data preprocessing
    top_k_species: int = 50
    min_prevalence: float = 0.02
    pseudo_count: float = 1e-6

    # Synthetic benchmark size
    # If synth_n is None, use max(real_N * synth_multiplier, minimum_synth_n)
    synth_n: Optional[int] = None
    synth_multiplier: float = 2.0
    minimum_synth_n: int = 800

    # Synthetic weak-alignment controls
    latent_dim: int = 6
    cross_modal_leakage: float = 0.04       # lower = weaker brain-micro latent alignment
    brain_noise: float = 1.10
    micro_noise: float = 1.80
    risk_rate: float = 0.24
    brain_signal_strength: float = 1.00
    micro_rel_signal_strength: float = 1.05
    interaction_strength: float = 0.65
    label_noise: float = 0.90

    # Species pattern controls
    n_risk_species: int = 12
    n_protective_species: int = 8
    species_effect_min: float = 1.35
    species_effect_max: float = 2.30
    abundance_edge_threshold: float = 0.0

    # Model size
    hidden_dim: int = 64
    latent_dim_model: int = 32
