# ============================================================
# 2. Utilities
# ============================================================

def set_seed(seed: int = 42):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    torch.cuda.manual_seed_all(seed)


def ensure_dir(path: str):
    os.makedirs(path, exist_ok=True)


def save_csv(df: pd.DataFrame, path: str):
    df.to_csv(path, index=False, encoding="utf-8-sig")
    print("Saved:", path)


def extract_tpmic_id(x):
    m = re.search(r"TPMIC\d+", str(x))
    return m.group(0) if m else None


def replace_missing_codes(df: pd.DataFrame):
    return df.replace([999, 999.0, "999", "999.0", "NA", "N/A", "", "nan", "None"], np.nan)


def encode_sex_like(series: pd.Series):
    if pd.api.types.is_numeric_dtype(series):
        return pd.to_numeric(series, errors="coerce")
    mapping = {
        "m": 1, "male": 1, "man": 1, "男": 1, "男性": 1, "1": 1,
        "f": 0, "female": 0, "woman": 0, "女": 0, "女性": 0, "0": 0,
    }
    return series.astype(str).str.strip().str.lower().map(mapping)


def safe_numeric(df: pd.DataFrame):
    out = df.copy()
    for c in out.columns:
        if c.lower() in ["sex", "gender"]:
            out[c] = encode_sex_like(out[c])
        else:
            out[c] = pd.to_numeric(out[c], errors="coerce")
    return out


def standardize_df(df: pd.DataFrame):
    x = pd.DataFrame(df).replace([np.inf, -np.inf], np.nan)
    x = SimpleImputer(strategy="median").fit_transform(x)
    x = StandardScaler().fit_transform(x)
    return x.astype(np.float32)


def cv_splitter(y, cfg: Config, seed: Optional[int] = None):
    min_class = pd.Series(y).value_counts().min()
    n_splits = max(2, min(cfg.n_splits, int(min_class)))
    return StratifiedKFold(n_splits=n_splits, shuffle=True, random_state=cfg.random_seed if seed is None else seed)


def train_val_split(train_idx, y, seed: int):
    train_idx = np.asarray(train_idx)
    y_train = y[train_idx]
    if len(np.unique(y_train)) < 2 or pd.Series(y_train).value_counts().min() < 2:
        return train_idx, train_idx
    tr_sub, val_sub = train_test_split(
        train_idx,
        test_size=0.2,
        stratify=y_train,
        random_state=seed,
    )
    return np.asarray(tr_sub), np.asarray(val_sub)


def threshold_values(cfg: Config):
    return np.linspace(0.01, 0.99, cfg.threshold_grid_size)


def binary_metrics(y_true, prob, threshold=0.5, pred=None):
    y_true = np.asarray(y_true).astype(int)
    prob = np.asarray(prob).astype(float)
    if pred is None:
        pred = (prob >= threshold).astype(int)
    else:
        pred = np.asarray(pred).astype(int)

    out = {
        "auc": np.nan,
        "pr_auc": np.nan,
        "macro_f1": f1_score(y_true, pred, average="macro", zero_division=0),
        "risk_recall": recall_score(y_true, pred, pos_label=1, zero_division=0),
        "risk_precision": precision_score(y_true, pred, pos_label=1, zero_division=0),
        "risk_f1": f1_score(y_true, pred, pos_label=1, zero_division=0),
        "balanced_acc": balanced_accuracy_score(y_true, pred),
        "acc": accuracy_score(y_true, pred),
        "predicted_risk_rate": float(np.mean(pred == 1)),
        "brier": np.nan,
    }
    if len(np.unique(y_true)) == 2:
        out["auc"] = roc_auc_score(y_true, prob)
        out["pr_auc"] = average_precision_score(y_true, prob)
        out["brier"] = brier_score_loss(y_true, prob)
    return out


def choose_threshold(y, prob, policy: str, cfg: Config, target=None):
    y = np.asarray(y).astype(int)
    prob = np.asarray(prob).astype(float)
    if policy == "default_0.5":
        return 0.5

    best_t, best_score = 0.5, -np.inf
    for t in threshold_values(cfg):
        pred = (prob >= t).astype(int)
        rec = recall_score(y, pred, pos_label=1, zero_division=0)
        prec = precision_score(y, pred, pos_label=1, zero_division=0)
        rf1 = f1_score(y, pred, pos_label=1, zero_division=0)
        mf1 = f1_score(y, pred, average="macro", zero_division=0)

        if policy == "max_risk_f1":
            score = rf1
        elif policy == "max_macro_f1":
            score = mf1
        elif policy == "max_recall_precision_floor":
            floor = cfg.tuning_precision_floor if target is None else float(target)
            score = rec + 0.02 * rf1 if prec >= floor else -np.inf
        else:
            raise ValueError(f"Unknown threshold policy: {policy}")

        if score > best_score:
            best_score = score
            best_t = t

    if not np.isfinite(best_score):
        return choose_threshold(y, prob, "max_risk_f1", cfg)
    return float(best_t)


def class_weights_tensor(y_train: np.ndarray, device):
    counts = np.bincount(y_train.astype(int), minlength=2)
    weights = counts.sum() / (counts + 1e-8)
    weights = weights / weights.mean()
    return torch.tensor(weights, dtype=torch.float32, device=device)


# ============================================================
# 3. Real data loading and calibration features
# ============================================================

def load_and_merge(cfg: Config):
    basic = replace_missing_codes(pd.read_csv(cfg.basic_path))
    micro = replace_missing_codes(pd.read_csv(cfg.micro_path))
    brain = replace_missing_codes(pd.read_csv(cfg.brain_path))

    brain["ID"] = brain[cfg.id_col_brain].apply(extract_tpmic_id)
    brain = brain.dropna(subset=["ID"]).copy()

    keep_labels = ["Normal", "MCI", "Dementia"]
    basic[cfg.label_col] = basic[cfg.label_col].astype(str)
    basic = basic[basic[cfg.label_col].isin(keep_labels)].copy()

    merged = (
        basic.merge(micro, on="ID", how="inner", suffixes=("", "_micro"))
             .merge(brain, on="ID", how="inner", suffixes=("", "_brain"))
    )

    print("========== Real Data Summary for Calibration ==========")
    print("basic:", basic.shape, "micro:", micro.shape, "brain:", brain.shape)
    print("merged:", merged.shape)
    print(merged[cfg.label_col].value_counts())
    print("=======================================================\n")
    return basic, micro, brain, merged


def make_binary_labels(diagnosis: pd.Series):
    return diagnosis.map({"Normal": 0, "MCI": 1, "Dementia": 1}).astype(int).values


def build_basic_features(df: pd.DataFrame):
    cols = ["Sex", "Age", "edu_yr", "BMI", "smoking", "drinking", "exercise_days"]
    cols = [c for c in cols if c in df.columns]
    return safe_numeric(df[cols])


def build_brain_features(df: pd.DataFrame):
    candidate_cols = [
        "Left-Hippocampus", "Right-Hippocampus",
        "Left-Amygdala", "Right-Amygdala",
        "lh-entorhinal", "rh-entorhinal",
    ]
    brain_cols = [c for c in candidate_cols if c in df.columns]
    out = pd.DataFrame(index=df.index)
    for c in brain_cols:
        out[c] = pd.to_numeric(df[c], errors="coerce")

    pairs = {
        "Hippocampus": ("Left-Hippocampus", "Right-Hippocampus"),
        "Amygdala": ("Left-Amygdala", "Right-Amygdala"),
        "Entorhinal": ("lh-entorhinal", "rh-entorhinal"),
    }
    for name, (lcol, rcol) in pairs.items():
        if lcol in df.columns and rcol in df.columns:
            L = pd.to_numeric(df[lcol], errors="coerce")
            R = pd.to_numeric(df[rcol], errors="coerce")
            mean = (L + R) / 2.0
            out[f"{name}_mean"] = mean
            out[f"{name}_diff"] = L - R
            out[f"{name}_asymmetry"] = (L - R).abs() / (mean.abs() + 1e-8)

    norm_col = "Total_Labeled_Brain_Volume_mm3"
    if norm_col in df.columns:
        total = pd.to_numeric(df[norm_col], errors="coerce")
        for c in brain_cols:
            out[f"{c}_norm"] = pd.to_numeric(df[c], errors="coerce") / (total + 1e-8)
    return out


def get_micro_raw_aligned(merged: pd.DataFrame, micro_original: pd.DataFrame, cfg: Config):
    aligned = merged[["ID"]].merge(micro_original, on="ID", how="left")
    exclude = {"ID", cfg.label_col}
    micro_cols = [c for c in aligned.columns if c not in exclude]
    X = safe_numeric(aligned[micro_cols]).dropna(axis=1, how="all").fillna(0.0).clip(lower=0)
    return X


def select_topk_micro_global(X_raw: pd.DataFrame, cfg: Config):
    prevalence = (X_raw > 0).mean(axis=0)
    keep = prevalence[prevalence >= cfg.min_prevalence].index.tolist()
    if len(keep) == 0:
        keep = X_raw.columns.tolist()
    X = X_raw[keep]
    selected = X.var(axis=0).sort_values(ascending=False).head(min(cfg.top_k_species, X.shape[1])).index.tolist()
    return selected


def microbiome_diversity_features(X_raw: pd.DataFrame):
    X = X_raw.fillna(0.0).clip(lower=0)
    total = X.sum(axis=1).values.reshape(-1, 1)
    P = X.values / (total + 1e-12)
    richness = (X.values > 0).sum(axis=1)
    shannon = -(P * np.log(P + 1e-12)).sum(axis=1)
    simpson = 1.0 - (P ** 2).sum(axis=1)
    evenness = shannon / (np.log(richness + 1e-12) + 1e-12)
    return pd.DataFrame({
        "micro_richness": richness,
        "micro_shannon": shannon,
        "micro_simpson": simpson,
        "micro_evenness": evenness,
        "micro_total_abundance": X.sum(axis=1).values,
    }, index=X.index)


def prepare_real_calibration(merged: pd.DataFrame, micro_original: pd.DataFrame, cfg: Config):
    y_real = make_binary_labels(merged[cfg.label_col])
    basic_x = build_basic_features(merged).reset_index(drop=True)
    brain_x = build_brain_features(merged).reset_index(drop=True)
    brainclinical_x = pd.concat([basic_x, brain_x], axis=1).reset_index(drop=True)

    micro_raw = get_micro_raw_aligned(merged, micro_original, cfg).reset_index(drop=True)
    selected_species = select_topk_micro_global(micro_raw, cfg)
    micro_selected = micro_raw[selected_species].copy().reset_index(drop=True)

    calibration = {
        "y_real": y_real,
        "basic_x": basic_x,
        "brain_x": brain_x,
        "brainclinical_x": brainclinical_x,
        "micro_selected": micro_selected,
        "selected_species": selected_species,
        "real_N": len(y_real),
        "real_risk_rate": float(np.mean(y_real == 1)),
    }
    return calibration


# ============================================================
# 4. Real-data-calibrated synthetic generator
# ============================================================

def sigmoid(x):
    return 1 / (1 + np.exp(-x))


def safe_logit(p):
    p = np.clip(p, 1e-4, 1 - 1e-4)
    return np.log(p / (1 - p))


def sample_from_real_marginal(real_df: pd.DataFrame, n: int, rng: np.random.Generator, noise_scale=0.08):
    X = pd.DataFrame(real_df).replace([np.inf, -np.inf], np.nan)
    X_imp = SimpleImputer(strategy="median").fit_transform(X)
    idx = rng.integers(0, X_imp.shape[0], size=n)
    sampled = X_imp[idx].astype(float)
    std = np.nanstd(X_imp, axis=0) + 1e-8
    sampled = sampled + rng.normal(0, noise_scale, size=sampled.shape) * std
    return sampled.astype(np.float32)


def generate_realdata_calibrated_synthetic(calib: Dict, cfg: Config, seed: int = 42):
    """
    Generate a stronger synthetic weak-alignment benchmark calibrated by real data.

    It reads real data first, then uses:
      - real patient feature dimensions and marginal distributions,
      - selected real microbiome species names,
      - real species prevalence and abundance scales,
    but creates controlled synthetic labels and relational microbiome patterns.
    """
    set_seed(seed)
    rng = np.random.default_rng(seed)

    real_N = calib["real_N"]
    N = int(cfg.synth_n) if cfg.synth_n is not None else int(max(real_N * cfg.synth_multiplier, cfg.minimum_synth_n))
    species_names = calib["selected_species"]
    S = len(species_names)
    dz = cfg.latent_dim

    # 1) Patient-level features calibrated from real demographic + brain distributions
    X_patient_base = sample_from_real_marginal(calib["brainclinical_x"], N, rng, noise_scale=0.10)
    patient_cols = list(calib["brainclinical_x"].columns)
    d_patient = X_patient_base.shape[1]

    # 2) Independent latent factors for brain and microbiome with very low leakage
    z_brain = rng.normal(0, 1, size=(N, dz))
    z_micro_private = rng.normal(0, 1, size=(N, dz))
    z_micro = cfg.cross_modal_leakage * z_brain + np.sqrt(1 - cfg.cross_modal_leakage ** 2) * z_micro_private

    # 3) Inject synthetic brain-risk direction into patient features
    #    Keep dimensions real-data-like, but create a controlled weak signal.
    W_brain = rng.normal(0, 0.45, size=(dz, d_patient))
    X_patient = X_patient_base + cfg.brain_noise * (z_brain @ W_brain).astype(np.float32)
    X_patient_z = StandardScaler().fit_transform(X_patient)

    # Use a sparse subset of patient features to mimic hippocampus/amygdala/entorhinal-related vulnerability
    # If real column names contain ROI names, prioritize them.
    roi_keywords = ["Hippocampus", "Amygdala", "Entorhinal", "entorhinal"]
    roi_idx = [i for i, c in enumerate(patient_cols) if any(k in str(c) for k in roi_keywords)]
    if len(roi_idx) < 5:
        roi_idx = list(range(min(8, d_patient)))
    roi_idx = roi_idx[:min(10, len(roi_idx))]
    brain_w = np.zeros(d_patient)
    brain_w[roi_idx] = rng.choice([-1, 1], size=len(roi_idx)) * rng.uniform(0.35, 0.90, size=len(roi_idx))
    brain_score = X_patient_z @ brain_w
    brain_score = (brain_score - brain_score.mean()) / (brain_score.std() + 1e-8)

    # 4) Microbiome matrix calibrated from real prevalence and abundance scale
    real_micro = calib["micro_selected"].fillna(0.0).clip(lower=0)
    real_prev = (real_micro > 0).mean(axis=0).values
    real_positive = real_micro.where(real_micro > 0)
    pos_mean = np.nanmean(np.log1p(real_positive.values), axis=0)
    pos_std = np.nanstd(np.log1p(real_positive.values), axis=0)
    pos_mean = np.nan_to_num(pos_mean, nan=0.3, posinf=0.3, neginf=0.3)
    pos_std = np.nan_to_num(pos_std, nan=0.8, posinf=0.8, neginf=0.8) + 0.15

    # Species groups
    all_species_idx = np.arange(S)
    n_risk = min(cfg.n_risk_species, max(3, S // 4))
    n_protect = min(cfg.n_protective_species, max(2, S // 5))
    risk_species_idx = rng.choice(all_species_idx, size=n_risk, replace=False)
    remaining = np.setdiff1d(all_species_idx, risk_species_idx)
    protective_species_idx = rng.choice(remaining, size=n_protect, replace=False)

    # Hidden microbiome subtype: nonlinear and only weakly related to brain
    subtype_axis = (
        0.85 * z_micro[:, 0]
        - 0.65 * z_micro[:, 2]
        + 0.45 * np.sin(z_micro[:, 3])
        + rng.normal(0, 0.75, size=N)
    )
    subtype_prob = sigmoid(subtype_axis)
    micro_subtype = rng.binomial(1, subtype_prob)

    # Presence logits use real prevalence as intercept
    logits = np.tile(safe_logit(real_prev), (N, 1))
    W_micro = rng.normal(0, 0.65, size=(dz, S))
    logits += z_micro @ W_micro
    logits += rng.normal(0, cfg.micro_noise, size=(N, S))

    # Inject relational co-occurrence effect
    for j in risk_species_idx:
        logits[:, j] += micro_subtype * rng.uniform(cfg.species_effect_min, cfg.species_effect_max)
    for j in protective_species_idx:
        logits[:, j] -= micro_subtype * rng.uniform(0.75, 1.40)

    presence_prob = np.clip(sigmoid(logits), 0.001, 0.999)
    presence = rng.binomial(1, presence_prob).astype(np.float32)

    log_abund = np.zeros((N, S), dtype=np.float32)
    for j in range(S):
        log_abund[:, j] = rng.normal(pos_mean[j], pos_std[j], size=N)
    log_abund += 0.35 * (z_micro @ rng.normal(0, 0.30, size=(dz, S)))
    abundance = np.expm1(np.clip(log_abund, 0, 8)) * presence
    abundance = abundance.astype(np.float32)

    micro_log = np.log1p(abundance)
    micro_log_z = StandardScaler().fit_transform(micro_log)

    # Relational microbiome risk score: depends on co-occurrence pattern, not one species alone
    risk_abund = micro_log[:, risk_species_idx]
    protect_abund = micro_log[:, protective_species_idx]
    micro_score = (
        risk_abund.mean(axis=1)
        + 0.40 * (risk_abund > 0).sum(axis=1) / max(1, len(risk_species_idx))
        - 0.55 * protect_abund.mean(axis=1)
    )
    micro_score = (micro_score - micro_score.mean()) / (micro_score.std() + 1e-8)

    # 5) Label construction: brain + microbiome relational + nonlinear interaction
    interaction = np.maximum(brain_score, 0) * np.maximum(micro_score, 0)
    risk_logit = (
        cfg.brain_signal_strength * brain_score
        + cfg.micro_rel_signal_strength * micro_score
        + cfg.interaction_strength * interaction
        + rng.normal(0, cfg.label_noise, size=N)
    )
    threshold = np.quantile(risk_logit, 1 - cfg.risk_rate)
    y = (risk_logit >= threshold).astype(int)

    # Relational-only high-risk cases:
    # high risk is true, brain score is not high, microbiome relational score is high
    relational_only = (
        (y == 1)
        & (brain_score <= np.quantile(brain_score, 0.55))
        & (micro_score >= np.quantile(micro_score, 0.70))
    ).astype(int)

    # If too few relational-only cases, loosen condition slightly for stable reporting
    if relational_only.sum() < max(10, int(0.03 * N)):
        relational_only = (
            (y == 1)
            & (brain_score <= np.quantile(brain_score, 0.65))
            & (micro_score >= np.quantile(micro_score, 0.65))
        ).astype(int)

    patient_df = pd.DataFrame(X_patient, columns=patient_cols)
    micro_log_df = pd.DataFrame(np.log1p(abundance), columns=species_names)
    micro_presence_df = pd.DataFrame((abundance > 0).astype(float), columns=species_names)
    micro_abund_df = pd.DataFrame(abundance, columns=species_names)
    micro_div_df = microbiome_diversity_features(micro_abund_df)
    alltabular_df = pd.concat([patient_df, micro_log_df.add_prefix("micro_")], axis=1)

    meta = pd.DataFrame({
        "synthetic_id": [f"SYN_{seed}_{i:04d}" for i in range(N)],
        "y": y,
        "brain_score_true": brain_score,
        "micro_score_true": micro_score,
        "risk_logit_true": risk_logit,
        "micro_subtype_true": micro_subtype,
        "relational_only_high_risk": relational_only,
    })

    species_info = pd.DataFrame({
        "species": species_names,
        "real_prevalence": real_prev,
        "is_risk_species": [int(i in set(risk_species_idx)) for i in range(S)],
        "is_protective_species": [int(i in set(protective_species_idx)) for i in range(S)],
    })

    return {
        "patient_df": patient_df,
        "micro_log_df": micro_log_df,
        "micro_presence_df": micro_presence_df,
        "micro_abund_df": micro_abund_df,
        "micro_div_df": micro_div_df,
        "alltabular_df": alltabular_df,
        "y": y,
        "meta": meta,
        "species_info": species_info,
        "brain_score": brain_score,
        "micro_score": micro_score,
        "relational_only": relational_only,
        "risk_species_idx": risk_species_idx,
        "protective_species_idx": protective_species_idx,
    }


# ============================================================
# 5. Weak-alignment diagnostics
# ============================================================

def weak_alignment_diagnostics(syn: Dict, cfg: Config, seed: int):
    Xb = standardize_df(syn["patient_df"])
    Xm = standardize_df(syn["micro_log_df"])
    y = syn["y"]
    n = len(y)

    n_comp_b = max(1, min(8, Xb.shape[1], n - 2))
    n_comp_m = max(1, min(8, Xm.shape[1], n - 2))
    B = PCA(n_components=n_comp_b, random_state=seed).fit_transform(Xb)
    M = PCA(n_components=n_comp_m, random_state=seed).fit_transform(Xm)
    cv = max(2, min(cfg.n_splits, int(pd.Series(y).value_counts().min())))

    ridge = RidgeCV(alphas=np.logspace(-3, 3, 13))
    m2b = cross_val_score(ridge, M, B, cv=cv, scoring="r2").mean()
    b2m = cross_val_score(ridge, B, M, cv=cv, scoring="r2").mean()

    rows = [
        {"seed": seed, "analysis": "Microbiome PCs -> Brain PCs CV R2", "value": float(m2b)},
        {"seed": seed, "analysis": "Brain PCs -> Microbiome PCs CV R2", "value": float(b2m)},
    ]

    cca_components = max(1, min(3, B.shape[1], M.shape[1]))
    try:
        cca = CCA(n_components=cca_components, max_iter=5000)
        U, V = cca.fit_transform(B, M)
        for i in range(cca_components):
            rows.append({"seed": seed, "analysis": f"CCA component {i+1}", "value": float(np.corrcoef(U[:, i], V[:, i])[0, 1])})
    except Exception:
        pass

    max_k = min(20, n - 1)
    brain_nn = NearestNeighbors(n_neighbors=max_k + 1).fit(Xb).kneighbors(Xb, return_distance=False)[:, 1:]
    micro_nn = NearestNeighbors(n_neighbors=max_k + 1).fit(Xm).kneighbors(Xm, return_distance=False)[:, 1:]
    for k in [5, 10, 20]:
        if k <= max_k:
            vals = []
            for i in range(n):
                vals.append(len(set(brain_nn[i, :k]).intersection(set(micro_nn[i, :k]))) / k)
            rows.append({"seed": seed, "analysis": f"Neighbor overlap@{k}", "value": float(np.mean(vals))})

    # Risk-marker discordance
    brain_score = syn["brain_score"]
    micro_score = syn["micro_score"]
    spearman = np.corrcoef(pd.Series(brain_score).rank(), pd.Series(micro_score).rank())[0, 1]
    rows.append({"seed": seed, "analysis": "Spearman brain-risk vs micro-risk score", "value": float(spearman)})
    for q in [0.20, 0.30]:
        b_high = brain_score >= np.quantile(brain_score, 1 - q)
        m_high = micro_score >= np.quantile(micro_score, 1 - q)
        inter = np.logical_and(b_high, m_high).sum()
        union = np.logical_or(b_high, m_high).sum()
        rows.append({"seed": seed, "analysis": f"Jaccard top {int(q*100)}% risk-marker groups", "value": float(inter / (union + 1e-8))})

    return pd.DataFrame(rows)


# ============================================================
# 6. Graph and models
# ============================================================

def build_heterodata(patient_df: pd.DataFrame, micro_edge_df: pd.DataFrame, y: np.ndarray, cfg: Config):
    patient_x = standardize_df(patient_df)
    edge_values = pd.DataFrame(micro_edge_df).fillna(0.0).values.astype(np.float32)
    edge_abs = np.abs(edge_values)

    valid_values = edge_values[edge_abs > cfg.abundance_edge_threshold]
    edge_mean = valid_values.mean() if len(valid_values) else 0.0
    edge_std = valid_values.std() + 1e-8 if len(valid_values) else 1.0

    n_patients, n_species = edge_values.shape
    species_prevalence = (edge_abs > cfg.abundance_edge_threshold).mean(axis=0)
    species_mean_abs = edge_abs.mean(axis=0)
    species_x = np.stack([species_prevalence, species_mean_abs], axis=1)
    species_x = StandardScaler().fit_transform(species_x).astype(np.float32)

    src_pat, dst_sp, attrs = [], [], []
    for i in range(n_patients):
        nz = np.where(edge_abs[i] > cfg.abundance_edge_threshold)[0]
        for j in nz:
            src_pat.append(i)
            dst_sp.append(j)
            attrs.append([(edge_values[i, j] - edge_mean) / edge_std])

    if len(src_pat) == 0:
        raise ValueError("No patient-species edges were created. Check synthetic microbiome matrix.")

    edge_index_p2s = torch.tensor([src_pat, dst_sp], dtype=torch.long)
    edge_attr_p2s = torch.tensor(attrs, dtype=torch.float32)
    edge_index_s2p = torch.tensor([dst_sp, src_pat], dtype=torch.long)

    data = HeteroData()
    data["patient"].x = torch.tensor(patient_x, dtype=torch.float32)
    data["species"].x = torch.tensor(species_x, dtype=torch.float32)
    data["patient"].y = torch.tensor(y, dtype=torch.long)
    data[("patient", "has", "species")].edge_index = edge_index_p2s
    data[("patient", "has", "species")].edge_attr = edge_attr_p2s
    data[("species", "rev_has", "patient")].edge_index = edge_index_s2p
    data[("species", "rev_has", "patient")].edge_attr = edge_attr_p2s.clone()
    return data


def randomize_micro_edges(data: HeteroData, seed: int = 42):
    rng = np.random.default_rng(seed)
    out = data.clone()
    p2s = out[("patient", "has", "species")].edge_index.cpu().numpy()
    src = p2s[0]
    n_species = out["species"].x.size(0)
    new_dst = rng.integers(0, n_species, size=len(src))
    out[("patient", "has", "species")].edge_index = torch.tensor([src, new_dst], dtype=torch.long)
    out[("species", "rev_has", "patient")].edge_index = torch.tensor([new_dst, src], dtype=torch.long)
    return out


class FocalLoss(nn.Module):
    def __init__(self, gamma=2.0, alpha=None):
        super().__init__()
        self.gamma = gamma
        self.alpha = alpha

    def forward(self, logits, target):
        ce = F.cross_entropy(logits, target, weight=self.alpha, reduction="none")
        pt = torch.exp(-ce)
        return (((1 - pt) ** self.gamma) * ce).mean()


def kl_normal(mu, logvar):
    return -0.5 * torch.mean(torch.sum(1 + logvar - mu.pow(2) - logvar.exp(), dim=1))


class VGIBHGNN(nn.Module):
    def __init__(self, patient_in_dim, species_in_dim, hidden_dim, latent_dim,
                 num_layers=2, heads=2, dropout=0.35, use_gaussian=True):
        super().__init__()
        self.dropout = dropout
        self.use_gaussian = use_gaussian
        self.patient_encoder = Linear(patient_in_dim, hidden_dim)
        self.species_encoder = Linear(species_in_dim, hidden_dim)

        assert hidden_dim % heads == 0, "hidden_dim must be divisible by heads"
        out_per_head = hidden_dim // heads
        self.convs = nn.ModuleList()
        for _ in range(num_layers):
            self.convs.append(HeteroConv({
                ("patient", "has", "species"): GATConv(
                    (hidden_dim, hidden_dim), out_per_head,
                    heads=heads, edge_dim=1, add_self_loops=False, dropout=dropout,
                ),
                ("species", "rev_has", "patient"): GATConv(
                    (hidden_dim, hidden_dim), out_per_head,
                    heads=heads, edge_dim=1, add_self_loops=False, dropout=dropout,
                ),
            }, aggr="sum"))

        self.mu_layer = nn.Linear(hidden_dim, latent_dim)
        self.logvar_layer = nn.Linear(hidden_dim, latent_dim)
        self.det_layer = nn.Linear(hidden_dim, latent_dim)
        self.classifier = nn.Sequential(
            nn.Linear(latent_dim, hidden_dim),
            nn.ReLU(),
            nn.Dropout(dropout),
            nn.Linear(hidden_dim, 2),
        )

    def reparameterize(self, mu, logvar):
        if not self.training:
            return mu
        std = torch.exp(0.5 * logvar)
        return mu + torch.randn_like(std) * std

    def forward(self, x_dict, edge_index_dict, edge_attr_dict):
        x_dict = {
            "patient": F.relu(self.patient_encoder(x_dict["patient"])),
            "species": F.relu(self.species_encoder(x_dict["species"])),
        }
        for conv in self.convs:
            new_x = conv(x_dict, edge_index_dict, edge_attr_dict=edge_attr_dict)
            for k in x_dict.keys():
                if k in new_x:
                    x_dict[k] = F.relu(new_x[k] + x_dict[k])
                    x_dict[k] = F.dropout(x_dict[k], p=self.dropout, training=self.training)
        h = x_dict["patient"]
        if self.use_gaussian:
            mu = self.mu_layer(h)
            logvar = self.logvar_layer(h).clamp(-8, 8)
            z = self.reparameterize(mu, logvar)
        else:
            z = self.det_layer(h)
            mu = z
            logvar = torch.zeros_like(z)
        return self.classifier(z), mu, logvar


class MLPClassifier(nn.Module):
    def __init__(self, in_dim, hidden_dim=64, dropout=0.35):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden_dim),
            nn.ReLU(),
            nn.Dropout(dropout),
            nn.Linear(hidden_dim, hidden_dim),
            nn.ReLU(),
            nn.Dropout(dropout),
            nn.Linear(hidden_dim, 2),
        )

    def forward(self, x):
        return self.net(x)


# ============================================================
# 7. Training and evaluation
# ============================================================

def train_hgnn_fold(data: HeteroData, y: np.ndarray, train_idx, test_idx, cfg: Config,
                    model_kind="vgib", seed=42):
    """
    model_kind:
      - hgnn_ce
      - hgnn_focal
      - hgnn_gaussian_focal
      - vgib
    """
    set_seed(seed)
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    data = data.to(device)
    labels = data["patient"].y
    tr_sub, val_sub = train_val_split(train_idx, y, seed)

    n = len(y)
    tr_mask = torch.zeros(n, dtype=torch.bool, device=device)
    val_mask = torch.zeros(n, dtype=torch.bool, device=device)
    tr_mask[torch.tensor(tr_sub, dtype=torch.long, device=device)] = True
    val_mask[torch.tensor(val_sub, dtype=torch.long, device=device)] = True

    use_gaussian = model_kind in ["hgnn_gaussian_focal", "vgib"]
    use_ib = model_kind == "vgib"
    use_focal = model_kind in ["hgnn_focal", "hgnn_gaussian_focal", "vgib"]

    model = VGIBHGNN(
        patient_in_dim=data["patient"].x.size(1),
        species_in_dim=data["species"].x.size(1),
        hidden_dim=cfg.hidden_dim,
        latent_dim=cfg.latent_dim_model,
        num_layers=cfg.num_layers,
        heads=cfg.heads,
        dropout=cfg.dropout,
        use_gaussian=use_gaussian,
    ).to(device)

    if use_focal:
        criterion = FocalLoss(gamma=cfg.gamma, alpha=class_weights_tensor(y[tr_sub], device))
    else:
        criterion = nn.CrossEntropyLoss(weight=class_weights_tensor(y[tr_sub], device))

    opt = torch.optim.AdamW(model.parameters(), lr=cfg.lr, weight_decay=cfg.weight_decay)
    best_state, best_val_loss, bad = None, np.inf, 0
    t0 = time.perf_counter()

    for epoch in range(cfg.epochs):
        model.train()
        opt.zero_grad()
        logits, mu, logvar = model(data.x_dict, data.edge_index_dict, data.edge_attr_dict)
        loss = criterion(logits[tr_mask], labels[tr_mask])
        if use_ib and cfg.beta > 0:
            loss = loss + cfg.beta * kl_normal(mu[tr_mask], logvar[tr_mask])
        loss.backward()
        torch.nn.utils.clip_grad_norm_(model.parameters(), 5.0)
        opt.step()

        model.eval()
        with torch.no_grad():
            logits_v, mu_v, logvar_v = model(data.x_dict, data.edge_index_dict, data.edge_attr_dict)
            vloss = criterion(logits_v[val_mask], labels[val_mask])
            if use_ib and cfg.beta > 0:
                vloss = vloss + cfg.beta * kl_normal(mu_v[val_mask], logvar_v[val_mask])
            v = float(vloss.detach().cpu())

        if v < best_val_loss:
            best_val_loss = v
            best_state = {k: vv.detach().cpu().clone() for k, vv in model.state_dict().items()}
            bad = 0
        else:
            bad += 1
            if bad >= cfg.patience:
                break

    runtime = time.perf_counter() - t0
    if best_state is not None:
        model.load_state_dict({k: vv.to(device) for k, vv in best_state.items()})

    model.eval()
    with torch.no_grad():
        logits, mu, logvar = model(data.x_dict, data.edge_index_dict, data.edge_attr_dict)
        prob_all = F.softmax(logits, dim=1).detach().cpu().numpy()[:, 1]

    val_prob = prob_all[val_sub]
    val_y = y[val_sub]
    th = choose_threshold(val_y, val_prob, cfg.threshold_policy, cfg)
    test_prob = prob_all[test_idx]
    test_pred = (test_prob >= th).astype(int)

    return {
        "test_prob": test_prob,
        "test_pred": test_pred,
        "threshold": th,
        "runtime_sec": runtime,
        "epochs_used": epoch + 1,
    }


def eval_hgnn_oof(data: HeteroData, y: np.ndarray, cfg: Config, seed: int, model_name: str, model_kind: str, relational_only=None):
    skf = cv_splitter(y, cfg, seed)
    oof_prob = np.zeros(len(y), dtype=float)
    oof_pred = np.zeros(len(y), dtype=int)
    thresholds = np.zeros(len(y), dtype=float)
    runtimes, epochs = [], []

    for fold, (tr, te) in enumerate(skf.split(np.zeros(len(y)), y), 1):
        print(f"[HGNN seed={seed}] {model_name} fold {fold}/{skf.get_n_splits()}")
        res = train_hgnn_fold(data, y, tr, te, cfg, model_kind=model_kind, seed=seed + fold)
        oof_prob[te] = res["test_prob"]
        oof_pred[te] = res["test_pred"]
        thresholds[te] = res["threshold"]
        runtimes.append(res["runtime_sec"])
        epochs.append(res["epochs_used"])

    metrics = binary_metrics(y, oof_prob, pred=oof_pred)
    metrics.update({
        "model": model_name,
        "seed": seed,
        "threshold_policy": cfg.threshold_policy,
        "threshold_mean": float(np.mean(thresholds)),
        "runtime_sec_total": float(np.sum(runtimes)),
        "epochs_used_mean": float(np.mean(epochs)),
    })
    if relational_only is not None:
        mask = np.asarray(relational_only).astype(bool)
        metrics["relational_only_n"] = int(mask.sum())
        metrics["relational_only_recall"] = float(oof_pred[mask].mean()) if mask.sum() > 0 else np.nan
    return pd.DataFrame([metrics]), {model_name: {"prob": oof_prob, "pred": oof_pred, "thresholds": thresholds}}


def fit_transform_train_val_test(X, tr_sub, val_sub, te):
    X = pd.DataFrame(X).replace([np.inf, -np.inf], np.nan).reset_index(drop=True)
    imp = SimpleImputer(strategy="median")
    sc = StandardScaler()
    Xt = imp.fit_transform(X.iloc[tr_sub])
    Xv = imp.transform(X.iloc[val_sub])
    Xe = imp.transform(X.iloc[te])
    Xt = sc.fit_transform(Xt)
    Xv = sc.transform(Xv)
    Xe = sc.transform(Xe)
    return Xt, Xv, Xe


def train_mlp_fold(X, y, train_idx, test_idx, cfg: Config, seed: int):
    set_seed(seed)
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    tr_sub, val_sub = train_val_split(train_idx, y, seed)
    Xt, Xv, Xe = fit_transform_train_val_test(X, tr_sub, val_sub, test_idx)
    xt = torch.tensor(Xt, dtype=torch.float32, device=device)
    xv = torch.tensor(Xv, dtype=torch.float32, device=device)
    yt = torch.tensor(y[tr_sub], dtype=torch.long, device=device)
    yv = torch.tensor(y[val_sub], dtype=torch.long, device=device)

    model = MLPClassifier(xt.size(1), cfg.hidden_dim, cfg.dropout).to(device)
    criterion = FocalLoss(gamma=cfg.gamma, alpha=class_weights_tensor(y[tr_sub], device))
    opt = torch.optim.AdamW(model.parameters(), lr=cfg.lr, weight_decay=cfg.weight_decay)
    best_state, best_val, bad = None, np.inf, 0
    t0 = time.perf_counter()

    for epoch in range(cfg.epochs):
        model.train()
        opt.zero_grad()
        loss = criterion(model(xt), yt)
        loss.backward()
        torch.nn.utils.clip_grad_norm_(model.parameters(), 5.0)
        opt.step()

        model.eval()
        with torch.no_grad():
            vloss = criterion(model(xv), yv)
            v = float(vloss.detach().cpu())
        if v < best_val:
            best_val = v
            best_state = {k: vv.detach().cpu().clone() for k, vv in model.state_dict().items()}
            bad = 0
        else:
            bad += 1
            if bad >= cfg.patience:
                break

    runtime = time.perf_counter() - t0
    if best_state is not None:
        model.load_state_dict({k: vv.to(device) for k, vv in best_state.items()})
    model.eval()
    with torch.no_grad():
        pv = F.softmax(model(torch.tensor(Xv, dtype=torch.float32, device=device)), dim=1).cpu().numpy()[:, 1]
        pe = F.softmax(model(torch.tensor(Xe, dtype=torch.float32, device=device)), dim=1).cpu().numpy()[:, 1]
    th = choose_threshold(y[val_sub], pv, cfg.threshold_policy, cfg)
    return pe, (pe >= th).astype(int), th, runtime, epoch + 1


def eval_mlp_oof(feature_sets: Dict[str, pd.DataFrame], y: np.ndarray, cfg: Config, seed: int, relational_only=None):
    skf = cv_splitter(y, cfg, seed)
    rows, outputs = [], {}
    for name, X in feature_sets.items():
        model_name = f"MLP-Focal-{name}"
        oof_prob = np.zeros(len(y), dtype=float)
        oof_pred = np.zeros(len(y), dtype=int)
        thresholds = np.zeros(len(y), dtype=float)
        runtimes, epochs = [], []
        for fold, (tr, te) in enumerate(skf.split(np.zeros(len(y)), y), 1):
            print(f"[MLP seed={seed}] {model_name} fold {fold}/{skf.get_n_splits()}")
            prob, pred, th, rt, ep = train_mlp_fold(X, y, tr, te, cfg, seed + fold)
            oof_prob[te] = prob
            oof_pred[te] = pred
            thresholds[te] = th
            runtimes.append(rt)
            epochs.append(ep)
        m = binary_metrics(y, oof_prob, pred=oof_pred)
        m.update({"model": model_name, "seed": seed, "threshold_policy": cfg.threshold_policy, "threshold_mean": float(np.mean(thresholds)), "runtime_sec_total": float(np.sum(runtimes)), "epochs_used_mean": float(np.mean(epochs))})
        if relational_only is not None:
            mask = np.asarray(relational_only).astype(bool)
            m["relational_only_n"] = int(mask.sum())
            m["relational_only_recall"] = float(oof_pred[mask].mean()) if mask.sum() > 0 else np.nan
        rows.append(m)
        outputs[model_name] = {"prob": oof_prob, "pred": oof_pred, "thresholds": thresholds}
    return pd.DataFrame(rows), outputs


def eval_sklearn_oof(feature_sets: Dict[str, pd.DataFrame], y: np.ndarray, cfg: Config, seed: int, relational_only=None):
    skf = cv_splitter(y, cfg, seed)
    models = {
        "LogReg": LogisticRegression(max_iter=3000, class_weight="balanced"),
        "RF": RandomForestClassifier(n_estimators=500, random_state=seed, class_weight="balanced_subsample", min_samples_leaf=2),
    }
    rows, outputs = [], {}
    for fs_name, X in feature_sets.items():
        X = pd.DataFrame(X).replace([np.inf, -np.inf], np.nan).reset_index(drop=True)
        for model_short, clf in models.items():
            model_name = f"{model_short}-{fs_name}"
            oof_prob = np.zeros(len(y), dtype=float)
            oof_pred = np.zeros(len(y), dtype=int)
            thresholds = np.zeros(len(y), dtype=float)
            runtime_total = 0.0
            for fold, (tr, te) in enumerate(skf.split(np.zeros(len(y)), y), 1):
                tr_sub, val_sub = train_val_split(tr, y, seed + fold)
                pipe = Pipeline([
                    ("imputer", SimpleImputer(strategy="median")),
                    ("scaler", StandardScaler()),
                    ("clf", clf),
                ])
                t0 = time.perf_counter()
                pipe.fit(X.iloc[tr_sub], y[tr_sub])
                runtime_total += time.perf_counter() - t0
                pv = pipe.predict_proba(X.iloc[val_sub])[:, 1]
                pe = pipe.predict_proba(X.iloc[te])[:, 1]
                th = choose_threshold(y[val_sub], pv, cfg.threshold_policy, cfg)
                oof_prob[te] = pe
                oof_pred[te] = (pe >= th).astype(int)
                thresholds[te] = th
            m = binary_metrics(y, oof_prob, pred=oof_pred)
            m.update({"model": model_name, "seed": seed, "threshold_policy": cfg.threshold_policy, "threshold_mean": float(np.mean(thresholds)), "runtime_sec_total": runtime_total, "epochs_used_mean": np.nan})
            if relational_only is not None:
                mask = np.asarray(relational_only).astype(bool)
                m["relational_only_n"] = int(mask.sum())
                m["relational_only_recall"] = float(oof_pred[mask].mean()) if mask.sum() > 0 else np.nan
            rows.append(m)
            outputs[model_name] = {"prob": oof_prob, "pred": oof_pred, "thresholds": thresholds}
    return pd.DataFrame(rows), outputs


# ============================================================
# 8. Benchmark evaluation and bootstrap
# ============================================================

def run_model_suite_on_synthetic(syn: Dict, cfg: Config, seed: int):
    y = syn["y"]
    rel = syn["relational_only"]
    rows, oof = [], {}

    # Non-graph and tabular baselines
    feature_sets = {
        "BrainDemo": syn["patient_df"],
        "EarlyFusionAllTabular": syn["alltabular_df"],
        "MicroOnly": syn["micro_log_df"],
    }
    sk_df, sk_cache = eval_sklearn_oof(feature_sets, y, cfg, seed, relational_only=rel)
    mlp_df, mlp_cache = eval_mlp_oof(feature_sets, y, cfg, seed, relational_only=rel)
    rows.extend([sk_df, mlp_df])
    oof.update(sk_cache)
    oof.update(mlp_cache)

    # Graph baselines and proposed model
    data_real = build_heterodata(syn["patient_df"], syn["micro_presence_df"], y, cfg)
    data_rand = randomize_micro_edges(data_real, seed + 999)

    graph_specs = [
        ("HGNN-CE-RealMicroEdges", data_real, "hgnn_ce"),
        ("HGNN-Focal-RandomizedMicroEdges", data_rand, "hgnn_focal"),
        ("HGNN-Focal-RealMicroEdges", data_real, "hgnn_focal"),
        ("HGNN-Gaussian-Focal-RealMicroEdges", data_real, "hgnn_gaussian_focal"),
        ("VGIB-HGNN-Focal-Proposed", data_real, "vgib"),
    ]
    for model_name, graph_data, kind in graph_specs:
        df, cache = eval_hgnn_oof(graph_data, y, cfg, seed, model_name, kind, relational_only=rel)
        rows.append(df)
        oof.update(cache)

    perf = pd.concat(rows, ignore_index=True)
    return perf, oof


def aggregate_performance(df: pd.DataFrame):
    metric_cols = [
        "auc", "pr_auc", "macro_f1", "risk_recall", "risk_precision", "risk_f1",
        "balanced_acc", "acc", "predicted_risk_rate", "brier", "relational_only_recall",
        "runtime_sec_total", "epochs_used_mean",
    ]
    rows = []
    for model, sub in df.groupby("model"):
        row = {"model": model}
        for c in metric_cols:
            if c in sub.columns:
                row[f"{c}_mean"] = float(sub[c].mean())
                row[f"{c}_std"] = float(sub[c].std(ddof=0))
        rows.append(row)
    return pd.DataFrame(rows).sort_values("risk_f1_mean", ascending=False)


def paired_bootstrap_over_seeds(df: pd.DataFrame, model_a: str, model_b: str, metric: str, cfg: Config):
    pivot = df.pivot_table(index="seed", columns="model", values=metric, aggfunc="mean")
    if model_a not in pivot.columns or model_b not in pivot.columns:
        return None
    sub = pivot[[model_a, model_b]].dropna()
    if len(sub) < 2:
        return None
    a = sub[model_a].values
    b = sub[model_b].values
    rng = np.random.default_rng(cfg.random_seed)
    diffs = []
    for _ in range(cfg.n_bootstrap):
        idx = rng.integers(0, len(sub), len(sub))
        diffs.append((a[idx] - b[idx]).mean())
    diffs = np.asarray(diffs)
    obs = float((a - b).mean())
    p = float(min(1.0, 2 * min(np.mean(diffs <= 0), np.mean(diffs >= 0))))
    return {
        "model_A": model_a,
        "model_B": model_b,
        "metric": metric,
        "mean_diff_A_minus_B": obs,
        "ci_lower": float(np.quantile(diffs, cfg.alpha / 2)),
        "ci_upper": float(np.quantile(diffs, 1 - cfg.alpha / 2)),
        "p_value": p,
        "n_seed_pairs": int(len(sub)),
    }


def run_bootstrap_summary(perf_all: pd.DataFrame, cfg: Config):
    proposed = "VGIB-HGNN-Focal-Proposed"
    baselines = [
        "MLP-Focal-EarlyFusionAllTabular",
        "HGNN-Focal-RandomizedMicroEdges",
        "HGNN-Focal-RealMicroEdges",
        "HGNN-Gaussian-Focal-RealMicroEdges",
        "RF-EarlyFusionAllTabular",
        "MLP-Focal-BrainDemo",
    ]
    metrics = ["risk_recall", "risk_precision", "risk_f1", "pr_auc", "relational_only_recall"]
    rows = []
    for b in baselines:
        for m in metrics:
            res = paired_bootstrap_over_seeds(perf_all, proposed, b, m, cfg)
            if res is not None:
                rows.append(res)
    return pd.DataFrame(rows)


# ============================================================
# 9. Main
# ============================================================

def main(cfg: Config = CFG):
    set_seed(cfg.random_seed)
    ensure_dir(cfg.output_dir)

    print("Device:", "cuda" if torch.cuda.is_available() else "cpu")
    print("Output dir:", cfg.output_dir)

    with open(os.path.join(cfg.output_dir, "00_config.json"), "w", encoding="utf-8") as f:
        json.dump(asdict(cfg), f, indent=2, ensure_ascii=False)

    # 1) Read real data and calibrate benchmark
    basic, micro, brain, merged = load_and_merge(cfg)
    calib = prepare_real_calibration(merged, micro, cfg)

    inventory = pd.DataFrame([
        {"item": "real_N_after_merge", "value": calib["real_N"]},
        {"item": "real_risk_rate", "value": calib["real_risk_rate"]},
        {"item": "patient_feature_dim", "value": calib["brainclinical_x"].shape[1]},
        {"item": "selected_species", "value": len(calib["selected_species"])},
        {"item": "synthetic_N_per_seed", "value": int(cfg.synth_n) if cfg.synth_n is not None else int(max(calib["real_N"] * cfg.synth_multiplier, cfg.minimum_synth_n))},
    ])
    save_csv(inventory, os.path.join(cfg.output_dir, "00_real_calibration_inventory.csv"))
    pd.DataFrame({"selected_species": calib["selected_species"]}).to_csv(
        os.path.join(cfg.output_dir, "00_selected_species_from_real_data.csv"), index=False, encoding="utf-8-sig"
    )

    all_perf = []
    all_diag = []
    all_species_info = []
    all_meta_summary = []

    for seed in cfg.seeds:
        print(f"\n========== Synthetic benchmark seed {seed} ==========")
        syn = generate_realdata_calibrated_synthetic(calib, cfg, seed=seed)

        # Save one seed's generated data preview for sanity check
        seed_dir = os.path.join(cfg.output_dir, f"seed_{seed}")
        ensure_dir(seed_dir)
        syn["meta"].to_csv(os.path.join(seed_dir, "synthetic_meta.csv"), index=False, encoding="utf-8-sig")
        syn["species_info"].to_csv(os.path.join(seed_dir, "synthetic_species_info.csv"), index=False, encoding="utf-8-sig")

        all_meta_summary.append({
            "seed": seed,
            "N": len(syn["y"]),
            "risk_count": int(np.sum(syn["y"] == 1)),
            "risk_rate": float(np.mean(syn["y"] == 1)),
            "relational_only_count": int(np.sum(syn["relational_only"] == 1)),
            "relational_only_rate": float(np.mean(syn["relational_only"] == 1)),
        })
        sp = syn["species_info"].copy()
        sp["seed"] = seed
        all_species_info.append(sp)

        # 2) Weak alignment diagnostics
        diag = weak_alignment_diagnostics(syn, cfg, seed)
        all_diag.append(diag)
        print("Weak-alignment diagnostics:")
        print(diag.to_string(index=False))

        # 3) Model benchmark
        perf, oof = run_model_suite_on_synthetic(syn, cfg, seed)
        all_perf.append(perf)
        print("Performance summary for this seed:")
        print(perf[["model", "auc", "pr_auc", "risk_recall", "risk_precision", "risk_f1", "relational_only_recall"]].to_string(index=False))

    perf_all = pd.concat(all_perf, ignore_index=True)
    diag_all = pd.concat(all_diag, ignore_index=True)
    species_all = pd.concat(all_species_info, ignore_index=True)
    meta_summary = pd.DataFrame(all_meta_summary)

    save_csv(perf_all, os.path.join(cfg.output_dir, "RQ4_synthetic_all_seed_performance.csv"))
    save_csv(aggregate_performance(perf_all), os.path.join(cfg.output_dir, "RQ4_synthetic_summary_mean_std.csv"))
    save_csv(diag_all, os.path.join(cfg.output_dir, "RQ4_synthetic_weak_alignment_diagnostics_long.csv"))

    diag_summary = diag_all.groupby("analysis", as_index=False).agg(value_mean=("value", "mean"), value_std=("value", "std"))
    save_csv(diag_summary, os.path.join(cfg.output_dir, "RQ4_synthetic_weak_alignment_diagnostics_summary.csv"))
    save_csv(species_all, os.path.join(cfg.output_dir, "RQ4_synthetic_species_info_all_seeds.csv"))
    save_csv(meta_summary, os.path.join(cfg.output_dir, "RQ4_synthetic_meta_summary.csv"))

    boot = run_bootstrap_summary(perf_all, cfg)
    save_csv(boot, os.path.join(cfg.output_dir, "RQ4_synthetic_paired_bootstrap_over_seeds.csv"))

    print("\n========== Final synthetic benchmark summary ==========")
    print(aggregate_performance(perf_all).to_string(index=False))
    print("\n========== Weak alignment summary ==========")
    print(diag_summary.to_string(index=False))
    print("\nAll outputs saved to:", cfg.output_dir)


if __name__ == "__main__":
    main(CFG)

