# ============================================================
# Standalone RQ3 Feature-level Ablation for VGIB-HGNN-Focal
#
# Purpose:
#   Run only RQ3 ablation experiments based on the tuned VGIB-HGNN-Focal architecture.
#
# Main RQ3:
#   A. Feature-level ablation
#      - Demographic only
#      - Brain only
#      - Demographic + Brain
#      - Demographic only + real microbiome graph
#      - Brain only + real microbiome graph
#      - Demographic + Brain + real microbiome graph
#
#   B. Microbiome relation ablation
#      - Demographic + Brain, NoMicro
#      - Demographic + Brain, RandomizedMicroEdges
#      - Demographic + Brain, RealMicroEdges
#
# Supplementary:
#   C. Component variants
#      - HGNN-CE
#      - HGNN-Focal
#      - HGNN-Gaussian-Focal
#      - VGIB-HGNN-Focal-Tuned
#
# Expected Colab files:
#   /content/data.csv
#   /content/micro.csv
#   /content/all_brain_result_1(3).csv
#
# Optional:
#   /content/icdm_tuned_vgib_outputs/RQ1_00_selected_vgib_config.json
#
# Outputs:
#   /content/rq3_feature_ablation_outputs/
# ============================================================

