# ============================================================
# 1. Config
# ============================================================

@dataclass
class Config:
    basic_path: str = "/content/data.csv"
    micro_path: str = "/content/micro.csv"
    brain_path: str = "/content/all_brain_result_1(3).csv"

    selected_config_path: str = "/content/icdm_tuned_vgib_outputs/RQ1_00_selected_vgib_config.json"
    output_dir: str = "/content/rq3_feature_ablation_outputs"

    id_col_basic: str = "ID"
    id_col_micro: str = "ID"
    id_col_brain: str = "Subject_ID"
    label_col: str = "Diagnosis"

    random_seed: int = 42
    seeds: Tuple[int, ...] = (42, 52, 62, 72, 82)
    n_splits: int = 5

    # microbiome filtering
    top_k_species: int = 50
    min_prevalence: float = 0.02
    abundance_edge_threshold: float = 0.0
    pseudo_count: float = 1e-6

    # model
    hidden_dim: int = 64
    latent_dim: int = 32
    num_layers: int = 2
    heads: int = 2
    dropout: float = 0.35
    lr: float = 1e-3
    weight_decay: float = 1e-4
    epochs: int = 250
    patience: int = 40

    # threshold
    threshold_grid_size: int = 99
    tuning_precision_floor: float = 0.50

    # quick test switch
    # If True, only use first seed. Change to False for final formal run.
    quick_test: bool = False


CFG = Config()


# ============================================================
# 2. Utilities
# ============================================================

def set_seed(seed: int = 42):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    torch.cuda.manual_seed_all(seed)


def ensure_dir(path: str):
    os.makedirs(path, exist_ok=True)


def save_csv(df: pd.DataFrame, path: str):
    df.to_csv(path, index=False, encoding="utf-8-sig")
    print("Saved:", path)


def extract_tpmic_id(x):
    m = re.search(r"TPMIC\d+", str(x))
    return m.group(0) if m else None


def replace_missing_codes(df: pd.DataFrame):
    return df.replace([999, 999.0, "999", "999.0", "NA", "N/A", "", "nan", "None"], np.nan)


def encode_sex_like(series: pd.Series):
    if pd.api.types.is_numeric_dtype(series):
        return pd.to_numeric(series, errors="coerce")

    mapping = {
        "m": 1, "male": 1, "man": 1, "男": 1, "男性": 1, "1": 1,
        "f": 0, "female": 0, "woman": 0, "女": 0, "女性": 0, "0": 0,
    }

    return series.astype(str).str.strip().str.lower().map(mapping)


def safe_numeric(df: pd.DataFrame):
    out = df.copy()
    for c in out.columns:
        if c.lower() in ["sex", "gender"]:
            out[c] = encode_sex_like(out[c])
        else:
            out[c] = pd.to_numeric(out[c], errors="coerce")
    return out


def cv_splitter(y, cfg: Config, seed: Optional[int] = None):
    min_class = pd.Series(y).value_counts().min()
    n_splits = max(2, min(cfg.n_splits, int(min_class)))
    return StratifiedKFold(
        n_splits=n_splits,
        shuffle=True,
        random_state=cfg.random_seed if seed is None else seed,
    )


def train_val_split(train_idx, y, seed: int):
    train_idx = np.asarray(train_idx)
    y_train = y[train_idx]

    if len(np.unique(y_train)) < 2 or pd.Series(y_train).value_counts().min() < 2:
        return train_idx, train_idx

    tr_sub, val_sub = train_test_split(
        train_idx,
        test_size=0.2,
        stratify=y_train,
        random_state=seed,
    )

    return np.asarray(tr_sub), np.asarray(val_sub)


def threshold_values(cfg: Config):
    return np.linspace(0.01, 0.99, cfg.threshold_grid_size)


def binary_metrics(y_true, prob, threshold=0.5, pred=None):
    y_true = np.asarray(y_true).astype(int)
    prob = np.asarray(prob).astype(float)

    if pred is None:
        pred = (prob >= threshold).astype(int)
    else:
        pred = np.asarray(pred).astype(int)

    out = {
        "auc": np.nan,
        "pr_auc": np.nan,
        "macro_f1": f1_score(y_true, pred, average="macro", zero_division=0),
        "risk_recall": recall_score(y_true, pred, pos_label=1, zero_division=0),
        "risk_precision": precision_score(y_true, pred, pos_label=1, zero_division=0),
        "risk_f1": f1_score(y_true, pred, pos_label=1, zero_division=0),
        "balanced_acc": balanced_accuracy_score(y_true, pred),
        "acc": accuracy_score(y_true, pred),
        "predicted_risk_rate": float(np.mean(pred == 1)),
        "brier": np.nan,
    }

    if len(np.unique(y_true)) == 2:
        out["auc"] = roc_auc_score(y_true, prob)
        out["pr_auc"] = average_precision_score(y_true, prob)
        out["brier"] = brier_score_loss(y_true, prob)

    return out


def choose_threshold(y, prob, policy: str, cfg: Config, target=None):
    y = np.asarray(y).astype(int)
    prob = np.asarray(prob).astype(float)

    if policy == "default_0.5":
        return 0.5

    best_t, best_score = 0.5, -np.inf

    for t in threshold_values(cfg):
        pred = (prob >= t).astype(int)
        rec = recall_score(y, pred, pos_label=1, zero_division=0)
        prec = precision_score(y, pred, pos_label=1, zero_division=0)
        rf1 = f1_score(y, pred, pos_label=1, zero_division=0)
        mf1 = f1_score(y, pred, average="macro", zero_division=0)

        if policy == "max_risk_f1":
            score = rf1
        elif policy == "max_macro_f1":
            score = mf1
        elif policy == "max_recall_precision_floor":
            floor = cfg.tuning_precision_floor if target is None else float(target)
            score = rec if prec >= floor else -np.inf
        else:
            raise ValueError(f"Unknown threshold policy: {policy}")

        if score > best_score:
            best_score = score
            best_t = t

    if not np.isfinite(best_score):
        return choose_threshold(y, prob, "max_risk_f1", cfg)

    return float(best_t)


def class_weights_tensor(y_train: np.ndarray, device):
    counts = np.bincount(y_train.astype(int), minlength=2)
    weights = counts.sum() / (counts + 1e-8)
    weights = weights / weights.mean()
    return torch.tensor(weights, dtype=torch.float32, device=device)


def kl_normal(mu, logvar):
    return -0.5 * torch.mean(torch.sum(1 + logvar - mu.pow(2) - logvar.exp(), dim=1))


def fit_transform_train_val_test(X, tr_sub, val_sub, te):
    X = pd.DataFrame(X).replace([np.inf, -np.inf], np.nan).reset_index(drop=True)

    imp = SimpleImputer(strategy="median")
    sc = StandardScaler()

    Xt = imp.fit_transform(X.iloc[tr_sub])
    Xv = imp.transform(X.iloc[val_sub])
    Xe = imp.transform(X.iloc[te])

    Xt = sc.fit_transform(Xt)
    Xv = sc.transform(Xv)
    Xe = sc.transform(Xe)

    return Xt, Xv, Xe


# ============================================================
# 3. Data Loading and Feature Engineering
# ============================================================

def load_and_merge(cfg: Config):
    basic = replace_missing_codes(pd.read_csv(cfg.basic_path))
    micro = replace_missing_codes(pd.read_csv(cfg.micro_path))
    brain = replace_missing_codes(pd.read_csv(cfg.brain_path))

    brain["ID"] = brain[cfg.id_col_brain].apply(extract_tpmic_id)
    brain = brain.dropna(subset=["ID"]).copy()

    keep_labels = ["Normal", "MCI", "Dementia"]
    basic[cfg.label_col] = basic[cfg.label_col].astype(str)
    basic = basic[basic[cfg.label_col].isin(keep_labels)].copy()

    merged = (
        basic.merge(micro, on="ID", how="inner", suffixes=("", "_micro"))
             .merge(brain, on="ID", how="inner", suffixes=("", "_brain"))
    )

    print("========== Data Summary ==========")
    print("basic:", basic.shape)
    print("micro:", micro.shape)
    print("brain:", brain.shape)
    print("merged:", merged.shape)
    print(merged[cfg.label_col].value_counts())
    print("==================================\n")

    return basic, micro, brain, merged


def make_binary_labels(diagnosis: pd.Series):
    return diagnosis.map({"Normal": 0, "MCI": 1, "Dementia": 1}).astype(int).values


def build_demographic_features(df: pd.DataFrame, include_mmse=False):
    cols = ["Sex", "Age", "edu_yr", "BMI", "smoking", "drinking", "exercise_days"]

    if include_mmse:
        cols.append("MMSE")

    cols = [c for c in cols if c in df.columns]
    return safe_numeric(df[cols])


def build_brain_features(df: pd.DataFrame):
    candidate_cols = [
        "Left-Hippocampus", "Right-Hippocampus",
        "Left-Amygdala", "Right-Amygdala",
        "lh-entorhinal", "rh-entorhinal",
    ]

    brain_cols = [c for c in candidate_cols if c in df.columns]
    out = pd.DataFrame(index=df.index)

    for c in brain_cols:
        out[c] = pd.to_numeric(df[c], errors="coerce")

    pairs = {
        "Hippocampus": ("Left-Hippocampus", "Right-Hippocampus"),
        "Amygdala": ("Left-Amygdala", "Right-Amygdala"),
        "Entorhinal": ("lh-entorhinal", "rh-entorhinal"),
    }

    for name, (lcol, rcol) in pairs.items():
        if lcol in df.columns and rcol in df.columns:
            L = pd.to_numeric(df[lcol], errors="coerce")
            R = pd.to_numeric(df[rcol], errors="coerce")
            mean = (L + R) / 2.0
            out[f"{name}_mean"] = mean
            out[f"{name}_diff"] = L - R
            out[f"{name}_asymmetry"] = (L - R).abs() / (mean.abs() + 1e-8)

    norm_col = "Total_Labeled_Brain_Volume_mm3"
    if norm_col in df.columns:
        total = pd.to_numeric(df[norm_col], errors="coerce")
        for c in brain_cols:
            out[f"{c}_norm"] = pd.to_numeric(df[c], errors="coerce") / (total + 1e-8)

    return out


def get_micro_raw_aligned(merged: pd.DataFrame, micro_original: pd.DataFrame, cfg: Config):
    aligned = merged[["ID"]].merge(micro_original, on="ID", how="left")
    exclude = {"ID", cfg.label_col}
    micro_cols = [c for c in aligned.columns if c not in exclude]

    X = (
        safe_numeric(aligned[micro_cols])
        .dropna(axis=1, how="all")
        .fillna(0.0)
        .clip(lower=0)
    )

    return X


def select_topk_micro_global(X_raw: pd.DataFrame, cfg: Config):
    prevalence = (X_raw > 0).mean(axis=0)
    keep = prevalence[prevalence >= cfg.min_prevalence].index.tolist()

    if len(keep) == 0:
        keep = X_raw.columns.tolist()

    X = X_raw[keep]

    selected = (
        X.var(axis=0)
        .sort_values(ascending=False)
        .head(min(cfg.top_k_species, X.shape[1]))
        .index
        .tolist()
    )

    return selected


def log1p_micro(X_raw: pd.DataFrame, cols: List[str]):
    return np.log1p(X_raw[cols].fillna(0.0).clip(lower=0))


def presence_micro(X_raw: pd.DataFrame, cols: List[str]):
    return (X_raw[cols].fillna(0.0) > 0).astype(float)


def clr_transform_df(X_raw: pd.DataFrame, cols: List[str], pseudo_count: float = 1e-6):
    X = X_raw[cols].fillna(0.0).clip(lower=0) + pseudo_count
    logX = np.log(X)
    gm = logX.mean(axis=1).values.reshape(-1, 1)
    clr = logX.values - gm

    return pd.DataFrame(clr, index=X.index, columns=[f"CLR_{c}" for c in cols])


def prepare_features(merged: pd.DataFrame, micro_original: pd.DataFrame, cfg: Config):
    y = make_binary_labels(merged[cfg.label_col])

    demographic_x = build_demographic_features(merged, include_mmse=False).reset_index(drop=True)
    brain_x = build_brain_features(merged).reset_index(drop=True)
    demographic_brain_x = pd.concat([demographic_x, brain_x], axis=1).reset_index(drop=True)

    micro_raw = get_micro_raw_aligned(merged, micro_original, cfg).reset_index(drop=True)
    selected_species = select_topk_micro_global(micro_raw, cfg)

    micro_log = log1p_micro(micro_raw, selected_species).reset_index(drop=True)
    micro_clr = clr_transform_df(micro_raw, selected_species, cfg.pseudo_count).reset_index(drop=True)
    micro_presence = presence_micro(micro_raw, selected_species).reset_index(drop=True)

    return {
        "y": y,
        "demographic_x": demographic_x,
        "brain_x": brain_x,
        "demographic_brain_x": demographic_brain_x,
        "micro_raw": micro_raw,
        "micro_log": micro_log,
        "micro_clr": micro_clr,
        "micro_presence": micro_presence,
        "selected_species": selected_species,
    }


def get_edge_rep_df(feats: Dict, edge_rep: str):
    if edge_rep == "log1p":
        return feats["micro_log"]
    if edge_rep == "clr":
        return feats["micro_clr"]
    if edge_rep == "presence":
        return feats["micro_presence"]
    raise ValueError(f"Unknown edge_rep: {edge_rep}")


# ============================================================
# 4. Graph Construction
# ============================================================

def build_heterodata(patient_df: pd.DataFrame, micro_edge_df: pd.DataFrame, y: np.ndarray, cfg: Config):
    patient_df = pd.DataFrame(patient_df).replace([np.inf, -np.inf], np.nan)
    micro_edge_df = pd.DataFrame(micro_edge_df).replace([np.inf, -np.inf], np.nan).fillna(0.0)

    patient_x = SimpleImputer(strategy="median").fit_transform(patient_df)
    patient_x = StandardScaler().fit_transform(patient_x)

    values = micro_edge_df.values.astype(np.float32)
    edge_mask_values = np.abs(values)

    valid_values = values[edge_mask_values > cfg.abundance_edge_threshold]
    edge_mean = valid_values.mean() if len(valid_values) else 0.0
    edge_std = valid_values.std() + 1e-8 if len(valid_values) else 1.0

    n_patients, n_species = values.shape

    species_prevalence = (edge_mask_values > cfg.abundance_edge_threshold).mean(axis=0)
    species_mean_abs = np.abs(values).mean(axis=0)

    species_x = np.stack([species_prevalence, species_mean_abs], axis=1)
    species_x = StandardScaler().fit_transform(species_x)

    src_pat, dst_sp, attrs = [], [], []

    for i in range(n_patients):
        nz = np.where(edge_mask_values[i] > cfg.abundance_edge_threshold)[0]
        for j in nz:
            src_pat.append(i)
            dst_sp.append(j)
            attrs.append([(values[i, j] - edge_mean) / edge_std])

    if len(src_pat) == 0:
        raise ValueError("No microbiome edges were created. Check edge representation or threshold.")

    edge_index_p2s = torch.tensor([src_pat, dst_sp], dtype=torch.long)
    edge_attr_p2s = torch.tensor(attrs, dtype=torch.float32)
    edge_index_s2p = torch.tensor([dst_sp, src_pat], dtype=torch.long)

    data = HeteroData()
    data["patient"].x = torch.tensor(patient_x, dtype=torch.float32)
    data["species"].x = torch.tensor(species_x, dtype=torch.float32)
    data["patient"].y = torch.tensor(y, dtype=torch.long)

    data[("patient", "has", "species")].edge_index = edge_index_p2s
    data[("patient", "has", "species")].edge_attr = edge_attr_p2s

    data[("species", "rev_has", "patient")].edge_index = edge_index_s2p
    data[("species", "rev_has", "patient")].edge_attr = edge_attr_p2s.clone()

    return data


def randomize_micro_edges(data: HeteroData, seed: int = 42):
    rng = np.random.default_rng(seed)
    out = data.clone()

    p2s = out[("patient", "has", "species")].edge_index.cpu().numpy()
    src = p2s[0]
    n_species = out["species"].x.size(0)

    new_dst = rng.integers(0, n_species, size=len(src))

    out[("patient", "has", "species")].edge_index = torch.tensor([src, new_dst], dtype=torch.long)
    out[("species", "rev_has", "patient")].edge_index = torch.tensor([new_dst, src], dtype=torch.long)

    return out


# ============================================================
# 5. Models
# ============================================================

class FocalLoss(nn.Module):
    def __init__(self, gamma=2.0, alpha=None):
        super().__init__()
        self.gamma = gamma
        self.alpha = alpha

    def forward(self, logits, target):
        ce = F.cross_entropy(logits, target, weight=self.alpha, reduction="none")
        pt = torch.exp(-ce)
        loss = ((1 - pt) ** self.gamma) * ce
        return loss.mean()


class VGIBHGNN(nn.Module):
    def __init__(
        self,
        patient_in_dim,
        species_in_dim,
        hidden_dim,
        latent_dim,
        num_layers=2,
        heads=2,
        dropout=0.35,
        use_gaussian=True,
    ):
        super().__init__()

        self.dropout = dropout
        self.use_gaussian = use_gaussian

        self.patient_encoder = Linear(patient_in_dim, hidden_dim)
        self.species_encoder = Linear(species_in_dim, hidden_dim)

        assert hidden_dim % heads == 0, "hidden_dim must be divisible by heads"
        out_per_head = hidden_dim // heads

        self.convs = nn.ModuleList()

        for _ in range(num_layers):
            self.convs.append(
                HeteroConv(
                    {
                        ("patient", "has", "species"): GATConv(
                            (hidden_dim, hidden_dim),
                            out_per_head,
                            heads=heads,
                            edge_dim=1,
                            add_self_loops=False,
                            dropout=dropout,
                        ),
                        ("species", "rev_has", "patient"): GATConv(
                            (hidden_dim, hidden_dim),
                            out_per_head,
                            heads=heads,
                            edge_dim=1,
                            add_self_loops=False,
                            dropout=dropout,
                        ),
                    },
                    aggr="sum",
                )
            )

        self.mu_layer = nn.Linear(hidden_dim, latent_dim)
        self.logvar_layer = nn.Linear(hidden_dim, latent_dim)
        self.det_layer = nn.Linear(hidden_dim, latent_dim)

        self.classifier = nn.Sequential(
            nn.Linear(latent_dim, hidden_dim),
            nn.ReLU(),
            nn.Dropout(dropout),
            nn.Linear(hidden_dim, 2),
        )

    def reparameterize(self, mu, logvar):
        if not self.training:
            return mu
        std = torch.exp(0.5 * logvar)
        return mu + torch.randn_like(std) * std

    def forward(self, x_dict, edge_index_dict, edge_attr_dict):
        x_dict = {
            "patient": F.relu(self.patient_encoder(x_dict["patient"])),
            "species": F.relu(self.species_encoder(x_dict["species"])),
        }

        for conv in self.convs:
            new_x = conv(x_dict, edge_index_dict, edge_attr_dict=edge_attr_dict)
            for k in x_dict.keys():
                if k in new_x:
                    x_dict[k] = F.relu(new_x[k] + x_dict[k])
                    x_dict[k] = F.dropout(x_dict[k], p=self.dropout, training=self.training)

        h = x_dict["patient"]

        if self.use_gaussian:
            mu = self.mu_layer(h)
            logvar = self.logvar_layer(h).clamp(-8, 8)
            z = self.reparameterize(mu, logvar)
        else:
            z = self.det_layer(h)
            mu = z
            logvar = torch.zeros_like(z)

        logits = self.classifier(z)

        return logits, mu, logvar


class PatientOnlyVGIB(nn.Module):
    def __init__(self, in_dim, hidden_dim, latent_dim, dropout=0.35, use_gaussian=True):
        super().__init__()

        self.use_gaussian = use_gaussian

        self.encoder = nn.Sequential(
            nn.Linear(in_dim, hidden_dim),
            nn.ReLU(),
            nn.Dropout(dropout),
            nn.Linear(hidden_dim, hidden_dim),
            nn.ReLU(),
        )

        self.mu_layer = nn.Linear(hidden_dim, latent_dim)
        self.logvar_layer = nn.Linear(hidden_dim, latent_dim)
        self.det_layer = nn.Linear(hidden_dim, latent_dim)

        self.classifier = nn.Sequential(
            nn.Linear(latent_dim, hidden_dim),
            nn.ReLU(),
            nn.Dropout(dropout),
            nn.Linear(hidden_dim, 2),
        )

    def reparameterize(self, mu, logvar):
        if not self.training:
            return mu
        std = torch.exp(0.5 * logvar)
        return mu + torch.randn_like(std) * std

    def forward(self, x):
        h = self.encoder(x)

        if self.use_gaussian:
            mu = self.mu_layer(h)
            logvar = self.logvar_layer(h).clamp(-8, 8)
            z = self.reparameterize(mu, logvar)
        else:
            z = self.det_layer(h)
            mu = z
            logvar = torch.zeros_like(z)

        logits = self.classifier(z)

        return logits, mu, logvar


# ============================================================
# 6. Training Helpers
# ============================================================

def train_hgnn_fold(
    data: HeteroData,
    y: np.ndarray,
    train_idx,
    test_idx,
    cfg: Config,
    loss_type="focal",
    use_gaussian=True,
    use_ib=True,
    beta=1e-4,
    gamma=1.0,
    threshold_policy="max_risk_f1",
    seed=42,
):
    set_seed(seed)

    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    data = data.to(device)
    labels = data["patient"].y

    tr_sub, val_sub = train_val_split(train_idx, y, seed)

    n = len(y)
    tr_mask = torch.zeros(n, dtype=torch.bool, device=device)
    val_mask = torch.zeros(n, dtype=torch.bool, device=device)
    test_mask = torch.zeros(n, dtype=torch.bool, device=device)

    tr_mask[torch.tensor(tr_sub, dtype=torch.long, device=device)] = True
    val_mask[torch.tensor(val_sub, dtype=torch.long, device=device)] = True
    test_mask[torch.tensor(test_idx, dtype=torch.long, device=device)] = True

    model = VGIBHGNN(
        patient_in_dim=data["patient"].x.size(1),
        species_in_dim=data["species"].x.size(1),
        hidden_dim=cfg.hidden_dim,
        latent_dim=cfg.latent_dim,
        num_layers=cfg.num_layers,
        heads=cfg.heads,
        dropout=cfg.dropout,
        use_gaussian=use_gaussian,
    ).to(device)

    if loss_type == "focal":
        criterion = FocalLoss(gamma=gamma, alpha=class_weights_tensor(y[tr_sub], device))
    elif loss_type == "ce_weighted":
        criterion = nn.CrossEntropyLoss(weight=class_weights_tensor(y[tr_sub], device))
    else:
        criterion = nn.CrossEntropyLoss()

    opt = torch.optim.AdamW(model.parameters(), lr=cfg.lr, weight_decay=cfg.weight_decay)

    best_state, best_val_loss, bad = None, np.inf, 0
    t0 = time.perf_counter()

    for epoch in range(cfg.epochs):
        model.train()
        opt.zero_grad()

        logits, mu, logvar = model(data.x_dict, data.edge_index_dict, data.edge_attr_dict)
        loss = criterion(logits[tr_mask], labels[tr_mask])

        if use_ib and use_gaussian and beta > 0:
            loss = loss + beta * kl_normal(mu[tr_mask], logvar[tr_mask])

        loss.backward()
        torch.nn.utils.clip_grad_norm_(model.parameters(), 5.0)
        opt.step()

        model.eval()
        with torch.no_grad():
            val_logits, val_mu, val_logvar = model(data.x_dict, data.edge_index_dict, data.edge_attr_dict)
            val_loss = criterion(val_logits[val_mask], labels[val_mask])

            if use_ib and use_gaussian and beta > 0:
                val_loss = val_loss + beta * kl_normal(val_mu[val_mask], val_logvar[val_mask])

            val_loss_value = float(val_loss.detach().cpu())

        if val_loss_value < best_val_loss:
            best_val_loss = val_loss_value
            best_state = {k: v.detach().cpu().clone() for k, v in model.state_dict().items()}
            bad = 0
        else:
            bad += 1
            if bad >= cfg.patience:
                break

    runtime = time.perf_counter() - t0

    if best_state is not None:
        model.load_state_dict({k: v.to(device) for k, v in best_state.items()})

    model.eval()
    with torch.no_grad():
        logits, mu, logvar = model(data.x_dict, data.edge_index_dict, data.edge_attr_dict)
        prob_all = F.softmax(logits, dim=1).detach().cpu().numpy()[:, 1]

    val_prob = prob_all[val_sub]
    val_y = y[val_sub]

    th = choose_threshold(val_y, val_prob, threshold_policy, cfg)

    test_prob = prob_all[test_idx]
    test_pred = (test_prob >= th).astype(int)

    return {
        "test_prob": test_prob,
        "test_pred": test_pred,
        "threshold": th,
        "runtime_sec": runtime,
        "epochs_used": epoch + 1,
    }


def eval_hgnn_oof(
    data: HeteroData,
    y: np.ndarray,
    cfg: Config,
    seed: int,
    model_name: str,
    loss_type="focal",
    use_gaussian=True,
    use_ib=True,
    beta=1e-4,
    gamma=1.0,
    threshold_policy="max_risk_f1",
):
    skf = cv_splitter(y, cfg, seed)

    oof_prob = np.zeros(len(y), dtype=float)
    oof_pred = np.zeros(len(y), dtype=int)
    thresholds = np.zeros(len(y), dtype=float)
    runtimes, epochs = [], []

    for fold, (tr, te) in enumerate(skf.split(np.zeros(len(y)), y), 1):
        print(f"[HGNN] {model_name} | seed={seed} | fold {fold}/{skf.get_n_splits()}")

        res = train_hgnn_fold(
            data=data,
            y=y,
            train_idx=tr,
            test_idx=te,
            cfg=cfg,
            loss_type=loss_type,
            use_gaussian=use_gaussian,
            use_ib=use_ib,
            beta=beta,
            gamma=gamma,
            threshold_policy=threshold_policy,
            seed=seed + fold,
        )

        oof_prob[te] = res["test_prob"]
        oof_pred[te] = res["test_pred"]
        thresholds[te] = res["threshold"]
        runtimes.append(res["runtime_sec"])
        epochs.append(res["epochs_used"])

    metrics = binary_metrics(y, oof_prob, pred=oof_pred)
    metrics.update({
        "model": model_name,
        "seed": seed,
        "threshold_policy": threshold_policy,
        "threshold_mean": float(np.mean(thresholds)),
        "runtime_sec_total": float(np.sum(runtimes)),
        "epochs_used_mean": float(np.mean(epochs)),
        "beta": beta,
        "gamma": gamma,
    })

    cache = {
        model_name: {
            "prob": oof_prob,
            "pred": oof_pred,
            "thresholds": thresholds,
        }
    }

    return pd.DataFrame([metrics]), cache


def eval_patientonly_vgib_oof_named(
    X: pd.DataFrame,
    y: np.ndarray,
    cfg: Config,
    seed: int,
    beta: float,
    gamma: float,
    policy: str,
    model_name: str,
):
    skf = cv_splitter(y, cfg, seed)

    oof_prob = np.zeros(len(y), dtype=float)
    oof_pred = np.zeros(len(y), dtype=int)
    thresholds = np.zeros(len(y), dtype=float)
    runtimes, epochs_used = [], []

    for fold, (tr, te) in enumerate(skf.split(np.zeros(len(y)), y), 1):
        print(f"[PatientOnly] {model_name} | seed={seed} | fold {fold}/{skf.get_n_splits()}")

        tr_sub, val_sub = train_val_split(tr, y, seed + fold)
        Xt, Xv, Xe = fit_transform_train_val_test(X, tr_sub, val_sub, te)

        device = torch.device("cuda" if torch.cuda.is_available() else "cpu")

        model = PatientOnlyVGIB(
            in_dim=Xt.shape[1],
            hidden_dim=cfg.hidden_dim,
            latent_dim=cfg.latent_dim,
            dropout=cfg.dropout,
            use_gaussian=True,
        ).to(device)

        criterion = FocalLoss(gamma=gamma, alpha=class_weights_tensor(y[tr_sub], device))
        opt = torch.optim.AdamW(model.parameters(), lr=cfg.lr, weight_decay=cfg.weight_decay)

        xt = torch.tensor(Xt, dtype=torch.float32, device=device)
        xv = torch.tensor(Xv, dtype=torch.float32, device=device)
        xe = torch.tensor(Xe, dtype=torch.float32, device=device)
        yt = torch.tensor(y[tr_sub], dtype=torch.long, device=device)
        yv = torch.tensor(y[val_sub], dtype=torch.long, device=device)

        best_state, best_val_loss, bad = None, np.inf, 0
        t0 = time.perf_counter()

        for epoch in range(cfg.epochs):
            model.train()
            opt.zero_grad()

            logits, mu, logvar = model(xt)
            loss = criterion(logits, yt)

            if beta > 0:
                loss = loss + beta * kl_normal(mu, logvar)

            loss.backward()
            torch.nn.utils.clip_grad_norm_(model.parameters(), 5.0)
            opt.step()

            model.eval()
            with torch.no_grad():
                val_logits, val_mu, val_logvar = model(xv)
                val_loss = criterion(val_logits, yv)

                if beta > 0:
                    val_loss = val_loss + beta * kl_normal(val_mu, val_logvar)

                val_loss_value = float(val_loss.detach().cpu())

            if val_loss_value < best_val_loss:
                best_val_loss = val_loss_value
                best_state = {k: v.detach().cpu().clone() for k, v in model.state_dict().items()}
                bad = 0
            else:
                bad += 1
                if bad >= cfg.patience:
                    break

        runtime = time.perf_counter() - t0
        runtimes.append(runtime)
        epochs_used.append(epoch + 1)

        if best_state is not None:
            model.load_state_dict({k: v.to(device) for k, v in best_state.items()})

        model.eval()
        with torch.no_grad():
            val_prob = F.softmax(model(xv)[0], dim=1).cpu().numpy()[:, 1]
            test_prob = F.softmax(model(xe)[0], dim=1).cpu().numpy()[:, 1]

        th = choose_threshold(y[val_sub], val_prob, policy, cfg)

        oof_prob[te] = test_prob
        oof_pred[te] = (test_prob >= th).astype(int)
        thresholds[te] = th

    metrics = binary_metrics(y, oof_prob, pred=oof_pred)
    metrics.update({
        "model": model_name,
        "seed": seed,
        "threshold_policy": policy,
        "threshold_mean": float(np.mean(thresholds)),
        "runtime_sec_total": float(np.sum(runtimes)),
        "epochs_used_mean": float(np.mean(epochs_used)),
        "beta": beta,
        "gamma": gamma,
    })

    cache = {
        model_name: {
            "prob": oof_prob,
            "pred": oof_pred,
            "thresholds": thresholds,
        }
    }

    return pd.DataFrame([metrics]), cache


# ============================================================
# 7. Selected VGIB Config
# ============================================================

def load_selected_config(cfg: Config):
    if os.path.exists(cfg.selected_config_path):
        with open(cfg.selected_config_path, "r", encoding="utf-8") as f:
            selected = json.load(f)
        print("Loaded selected VGIB config:", selected)
        return selected

    print("Selected config not found. Using fallback config.")
    selected = {
        "edge_rep": "presence",
        "beta": 1e-4,
        "gamma": 1.0,
        "threshold_policy": "max_risk_f1",
    }
    print("Fallback selected config:", selected)
    return selected


# ============================================================
# 8. RQ3 Main Function
# ============================================================

def run_rq3_standalone(feats: Dict, y: np.ndarray, cfg: Config, selected: Dict):
    beta = float(selected["beta"])
    gamma = float(selected["gamma"])
    policy = selected["threshold_policy"]
    selected_edge_rep = selected["edge_rep"]

    edge_df_selected = get_edge_rep_df(feats, selected_edge_rep)

    all_rows = []
    all_oof = {}

    rq3_seeds = (cfg.seeds[:1] if cfg.quick_test else cfg.seeds)

    for seed in rq3_seeds:
        print("\n" + "=" * 80)
        print(f"RQ3 Standalone Ablation | seed={seed}")
        print("=" * 80)

        # ----------------------------------------------------
        # Panel A. Feature-level ablation without microbiome
        # ----------------------------------------------------
        patientonly_specs = [
            {
                "model_name": "RQ3A_DemographicOnly_NoMicro",
                "patient_df": feats["demographic_x"],
                "rq3_panel": "A_feature_level_no_micro",
                "patient_features": "Demographic only",
                "microbiome_setting": "No microbiome",
                "main_text_recommendation": "Main text",
            },
            {
                "model_name": "RQ3A_BrainOnly_NoMicro",
                "patient_df": feats["brain_x"],
                "rq3_panel": "A_feature_level_no_micro",
                "patient_features": "Brain only",
                "microbiome_setting": "No microbiome",
                "main_text_recommendation": "Main text",
            },
            {
                "model_name": "RQ3A_DemographicBrain_NoMicro",
                "patient_df": feats["demographic_brain_x"],
                "rq3_panel": "A_feature_level_no_micro",
                "patient_features": "Demographic + Brain",
                "microbiome_setting": "No microbiome",
                "main_text_recommendation": "Main text",
            },
        ]

        for spec in patientonly_specs:
            df, cache = eval_patientonly_vgib_oof_named(
                X=spec["patient_df"],
                y=y,
                cfg=cfg,
                seed=seed,
                beta=beta,
                gamma=gamma,
                policy=policy,
                model_name=spec["model_name"],
            )

            for k, v in spec.items():
                if k != "patient_df":
                    df[k] = v

            df["edge_rep"] = "None"
            df["randomized_edges"] = False

            all_rows.append(df)
            all_oof.update(cache)

        # ----------------------------------------------------
        # Panel B. Feature-level ablation with real microbiome graph
        # ----------------------------------------------------
        hgnn_feature_specs = [
            {
                "model_name": "RQ3B_DemographicOnly_RealMicroEdges",
                "patient_df": feats["demographic_x"],
                "rq3_panel": "B_feature_level_with_real_microbiome",
                "patient_features": "Demographic only",
                "microbiome_setting": "Real microbiome edges",
                "main_text_recommendation": "Main text",
            },
            {
                "model_name": "RQ3B_BrainOnly_RealMicroEdges",
                "patient_df": feats["brain_x"],
                "rq3_panel": "B_feature_level_with_real_microbiome",
                "patient_features": "Brain only",
                "microbiome_setting": "Real microbiome edges",
                "main_text_recommendation": "Main text",
            },
            {
                "model_name": "RQ3B_DemographicBrain_RealMicroEdges",
                "patient_df": feats["demographic_brain_x"],
                "rq3_panel": "B_feature_level_with_real_microbiome",
                "patient_features": "Demographic + Brain",
                "microbiome_setting": "Real microbiome edges",
                "main_text_recommendation": "Main text",
            },
        ]

        for spec in hgnn_feature_specs:
            data = build_heterodata(spec["patient_df"], edge_df_selected, y, cfg)

            df, cache = eval_hgnn_oof(
                data=data,
                y=y,
                cfg=cfg,
                seed=seed,
                model_name=spec["model_name"],
                loss_type="focal",
                use_gaussian=True,
                use_ib=True,
                beta=beta,
                gamma=gamma,
                threshold_policy=policy,
            )

            for k, v in spec.items():
                if k != "patient_df":
                    df[k] = v

            df["edge_rep"] = selected_edge_rep
            df["randomized_edges"] = False

            all_rows.append(df)
            all_oof.update(cache)

        # ----------------------------------------------------
        # Panel C. Microbiome relation ablation
        # Fixed patient features = Demographic + Brain
        # ----------------------------------------------------
        relation_specs = [
            {
                "model_name": "RQ3C_DemographicBrain_NoMicro",
                "kind": "patientonly",
                "rq3_panel": "C_microbiome_relation_ablation",
                "patient_features": "Demographic + Brain",
                "microbiome_setting": "No microbiome",
                "main_text_recommendation": "Main text",
            },
            {
                "model_name": "RQ3C_DemographicBrain_RandomizedMicroEdges",
                "kind": "hgnn_random",
                "rq3_panel": "C_microbiome_relation_ablation",
                "patient_features": "Demographic + Brain",
                "microbiome_setting": "Randomized microbiome edges",
                "main_text_recommendation": "Main text",
            },
            {
                "model_name": "RQ3C_DemographicBrain_RealMicroEdges",
                "kind": "hgnn_real",
                "rq3_panel": "C_microbiome_relation_ablation",
                "patient_features": "Demographic + Brain",
                "microbiome_setting": "Real microbiome edges",
                "main_text_recommendation": "Main text",
            },
        ]

        for spec in relation_specs:
            if spec["kind"] == "patientonly":
                df, cache = eval_patientonly_vgib_oof_named(
                    X=feats["demographic_brain_x"],
                    y=y,
                    cfg=cfg,
                    seed=seed + 1000,
                    beta=beta,
                    gamma=gamma,
                    policy=policy,
                    model_name=spec["model_name"],
                )
                df["edge_rep"] = "None"
                df["randomized_edges"] = False

            else:
                data = build_heterodata(feats["demographic_brain_x"], edge_df_selected, y, cfg)

                if spec["kind"] == "hgnn_random":
                    data = randomize_micro_edges(data, seed + 1000)
                    randomized = True
                else:
                    randomized = False

                df, cache = eval_hgnn_oof(
                    data=data,
                    y=y,
                    cfg=cfg,
                    seed=seed + 1000,
                    model_name=spec["model_name"],
                    loss_type="focal",
                    use_gaussian=True,
                    use_ib=True,
                    beta=beta,
                    gamma=gamma,
                    threshold_policy=policy,
                )

                df["edge_rep"] = selected_edge_rep
                df["randomized_edges"] = randomized

            for k, v in spec.items():
                if k != "kind":
                    df[k] = v

            all_rows.append(df)
            all_oof.update(cache)

        # ----------------------------------------------------
        # Panel D. Edge representation sensitivity
        # Fixed patient features = Demographic + Brain
        # ----------------------------------------------------
        for edge_rep in ["presence", "log1p", "clr"]:
            edge_df = get_edge_rep_df(feats, edge_rep)

            model_name = f"RQ3D_DemographicBrain_RealMicroEdges_{edge_rep}"

            data = build_heterodata(feats["demographic_brain_x"], edge_df, y, cfg)

            df, cache = eval_hgnn_oof(
                data=data,
                y=y,
                cfg=cfg,
                seed=seed + 2000,
                model_name=model_name,
                loss_type="focal",
                use_gaussian=True,
                use_ib=True,
                beta=beta,
                gamma=gamma,
                threshold_policy=policy,
            )

            df["rq3_panel"] = "D_microbiome_edge_representation_sensitivity"
            df["patient_features"] = "Demographic + Brain"
            df["microbiome_setting"] = f"Real microbiome edges ({edge_rep})"
            df["main_text_recommendation"] = "Optional / Supplement"
            df["edge_rep"] = edge_rep
            df["randomized_edges"] = False

            all_rows.append(df)
            all_oof.update(cache)

        # ----------------------------------------------------
        # Panel S. Component variants for supplementary table
        # ----------------------------------------------------
        data_real = build_heterodata(feats["demographic_brain_x"], edge_df_selected, y, cfg)

        component_specs = [
            ("RQ3S_HGNN-CE", "ce_weighted", False, False, 0.0, gamma),
            ("RQ3S_HGNN-Focal", "focal", False, False, 0.0, gamma),
            ("RQ3S_HGNN-Gaussian-Focal", "focal", True, False, 0.0, gamma),
            ("RQ3S_VGIB-HGNN-Focal-Tuned", "focal", True, True, beta, gamma),
        ]

        for name, loss_type, use_g, use_ib, b, g in component_specs:
            df, cache = eval_hgnn_oof(
                data=data_real,
                y=y,
                cfg=cfg,
                seed=seed + 3000,
                model_name=name,
                loss_type=loss_type,
                use_gaussian=use_g,
                use_ib=use_ib,
                beta=b,
                gamma=g,
                threshold_policy=policy,
            )

            df["rq3_panel"] = "S_component_variants_supplement"
            df["patient_features"] = "Demographic + Brain"
            df["microbiome_setting"] = f"Real microbiome edges ({selected_edge_rep})"
            df["main_text_recommendation"] = "Supplement"
            df["edge_rep"] = selected_edge_rep
            df["randomized_edges"] = False

            all_rows.append(df)
            all_oof.update(cache)

    rq3_raw = pd.concat(all_rows, ignore_index=True)

    group_cols = [
        "rq3_panel",
        "model",
        "patient_features",
        "microbiome_setting",
        "edge_rep",
        "main_text_recommendation",
    ]

    metric_cols = [
        "auc",
        "pr_auc",
        "macro_f1",
        "risk_recall",
        "risk_precision",
        "risk_f1",
        "balanced_acc",
        "acc",
        "predicted_risk_rate",
        "brier",
        "threshold_mean",
        "runtime_sec_total",
        "epochs_used_mean",
        "beta",
        "gamma",
    ]

    existing_metric_cols = [c for c in metric_cols if c in rq3_raw.columns]

    rq3_summary = (
        rq3_raw
        .groupby(group_cols, dropna=False)[existing_metric_cols]
        .agg(["mean", "std"])
        .reset_index()
    )

    rq3_summary.columns = [
        "_".join([str(x) for x in col if x != ""]).strip("_")
        for col in rq3_summary.columns.values
    ]

    sort_cols = ["rq3_panel", "risk_recall_mean", "risk_f1_mean", "auc_mean"]
    sort_cols = [c for c in sort_cols if c in rq3_summary.columns]

    rq3_summary = rq3_summary.sort_values(
        sort_cols,
        ascending=[True, False, False, False][:len(sort_cols)],
    )

    return rq3_raw, rq3_summary, all_oof


# ============================================================
# 9. Main
# ============================================================

def main(cfg: Config = CFG):
    set_seed(cfg.random_seed)
    ensure_dir(cfg.output_dir)

    basic, micro, brain, merged = load_and_merge(cfg)
    feats = prepare_features(merged, micro, cfg)
    y = feats["y"]

    selected = load_selected_config(cfg)

    inventory = pd.DataFrame([
        {"item": "N", "value": len(y)},
        {"item": "Normal_count", "value": int(np.sum(y == 0))},
        {"item": "Risk_count_MCI_plus_Dementia", "value": int(np.sum(y == 1))},
        {"item": "selected_species", "value": len(feats["selected_species"])},
        {"item": "demographic_dim", "value": feats["demographic_x"].shape[1]},
        {"item": "brain_dim", "value": feats["brain_x"].shape[1]},
        {"item": "demographic_brain_dim", "value": feats["demographic_brain_x"].shape[1]},
        {"item": "selected_edge_rep", "value": selected["edge_rep"]},
        {"item": "selected_beta", "value": selected["beta"]},
        {"item": "selected_gamma", "value": selected["gamma"]},
        {"item": "selected_threshold_policy", "value": selected["threshold_policy"]},
    ])

    save_csv(inventory, os.path.join(cfg.output_dir, "RQ3_00_dataset_and_config_inventory.csv"))

    print("\n========== Running standalone RQ3 ==========")

    rq3_raw, rq3_summary, rq3_oof = run_rq3_standalone(feats, y, cfg, selected)

    save_csv(rq3_raw, os.path.join(cfg.output_dir, "RQ3_01_feature_level_ablation_raw.csv"))
    save_csv(rq3_summary, os.path.join(cfg.output_dir, "RQ3_02_feature_level_ablation_summary.csv"))

    rq3_main = rq3_summary[
        rq3_summary["main_text_recommendation"].isin(["Main text"])
    ].copy()

    rq3_supp = rq3_summary[
        rq3_summary["main_text_recommendation"].isin(["Supplement", "Optional / Supplement"])
    ].copy()

    save_csv(rq3_main, os.path.join(cfg.output_dir, "RQ3_03_main_text_ablation_table.csv"))
    save_csv(rq3_supp, os.path.join(cfg.output_dir, "RQ3_04_supplementary_ablation_table.csv"))

    # Save OOF predictions for main RQ3 models
    oof_df = pd.DataFrame({
        "ID": merged["ID"].values,
        "Diagnosis": merged[cfg.label_col].values,
        "y_true": y,
    })

    for name, rec in rq3_oof.items():
        oof_df[f"prob_{name}"] = rec["prob"]
        oof_df[f"pred_{name}"] = rec["pred"]

    save_csv(oof_df, os.path.join(cfg.output_dir, "RQ3_05_oof_predictions.csv"))

    readme = f"""
Standalone RQ3 feature-level ablation completed.

Output folder:
{cfg.output_dir}

Important files:
1. RQ3_00_dataset_and_config_inventory.csv
   Dataset size, feature dimensions, and selected VGIB config.

2. RQ3_01_feature_level_ablation_raw.csv
   Raw results across seeds.

3. RQ3_02_feature_level_ablation_summary.csv
   Mean/std summary across seeds.

4. RQ3_03_main_text_ablation_table.csv
   Recommended main-text RQ3 table.

5. RQ3_04_supplementary_ablation_table.csv
   Supplementary component variants and edge-representation sensitivity.

6. RQ3_05_oof_predictions.csv
   Out-of-fold predictions for all RQ3 settings.

Recommended main-text interpretation:
- Panel A: feature-level ablation without microbiome.
- Panel B: feature-level ablation with real microbiome edges.
- Panel C: microbiome relation ablation.
- Component variants should be moved to supplementary material.
"""
    readme_path = os.path.join(cfg.output_dir, "README_RQ3_outputs.txt")
    with open(readme_path, "w", encoding="utf-8") as f:
        f.write(readme)

    print("Saved:", readme_path)
    print("\nAll RQ3 outputs saved to:", cfg.output_dir)


if __name__ == "__main__":
    main(CFG)

# ============================================================
# RQ2.3 Risk-marker Discordance Analysis
# Purpose:
#   Test whether brain-related risk markers and microbiome-related
#   risk markers identify the same or different high-risk patients.
#
# Interpretation:
#   Low correlation / low top-k overlap / low kappa supports:
#   "weakly aligned but potentially complementary risk signals"
# ============================================================

import os
import re
import numpy as np
import pandas as pd

from scipy.stats import spearmanr
from sklearn.preprocessing import StandardScaler
from sklearn.impute import SimpleImputer
from sklearn.decomposition import PCA
from sklearn.metrics import cohen_kappa_score

# -----------------------------
# Paths
# -----------------------------
BASIC_PATH = "/content/data.csv"
MICRO_PATH = "/content/micro.csv"
BRAIN_PATH = "/content/all_brain_result_1(3).csv"
OUT_DIR = "/content/icdm_tuned_vgib_outputs"
os.makedirs(OUT_DIR, exist_ok=True)

LABEL_COL = "Diagnosis"
BRAIN_ID_COL = "Subject_ID"

# -----------------------------
# Helper functions
# -----------------------------
def extract_tpmic_id(x):
    m = re.search(r"TPMIC\d+", str(x))
    return m.group(0) if m else None

def replace_missing_codes(df):
    return df.replace([999, 999.0, "999", "999.0", "NA", "N/A", "", "nan", "None"], np.nan)

def encode_sex_like(series):
    if pd.api.types.is_numeric_dtype(series):
        return pd.to_numeric(series, errors="coerce")
    mapping = {
        "m": 1, "male": 1, "man": 1, "男": 1, "男性": 1, "1": 1,
        "f": 0, "female": 0, "woman": 0, "女": 0, "女性": 0, "0": 0,
    }
    return series.astype(str).str.strip().str.lower().map(mapping)

def safe_numeric(df):
    out = df.copy()
    for c in out.columns:
        if c.lower() in ["sex", "gender"]:
            out[c] = encode_sex_like(out[c])
        else:
            out[c] = pd.to_numeric(out[c], errors="coerce")
    return out

def load_and_merge():
    basic = replace_missing_codes(pd.read_csv(BASIC_PATH))
    micro = replace_missing_codes(pd.read_csv(MICRO_PATH))
    brain = replace_missing_codes(pd.read_csv(BRAIN_PATH))

    brain["ID"] = brain[BRAIN_ID_COL].apply(extract_tpmic_id)
    brain = brain.dropna(subset=["ID"]).copy()

    keep_labels = ["Normal", "MCI", "Dementia"]
    basic[LABEL_COL] = basic[LABEL_COL].astype(str)
    basic = basic[basic[LABEL_COL].isin(keep_labels)].copy()

    merged = (
        basic.merge(micro, on="ID", how="inner", suffixes=("", "_micro"))
             .merge(brain, on="ID", how="inner", suffixes=("", "_brain"))
    )

    y = merged[LABEL_COL].map({"Normal": 0, "MCI": 1, "Dementia": 1}).astype(int).values
    return basic, micro, brain, merged, y

def build_brain_marker_features(df):
    """
    Build risk-relevant brain/clinical markers.
    Higher score should mean higher risk.
    """
    out = pd.DataFrame(index=df.index)

    # Clinical risk markers
    if "Age" in df.columns:
        out["Age_risk"] = pd.to_numeric(df["Age"], errors="coerce")

    if "edu_yr" in df.columns:
        # lower education = higher risk
        out["Education_low_risk"] = -pd.to_numeric(df["edu_yr"], errors="coerce")

    if "MMSE" in df.columns:
        # lower MMSE = higher risk, optional because MMSE may be too diagnosis-proximal
        out["MMSE_low_risk"] = -pd.to_numeric(df["MMSE"], errors="coerce")

    # Brain ROI risk markers: lower volume = higher risk
    pairs = {
        "Hippocampus": ("Left-Hippocampus", "Right-Hippocampus"),
        "Amygdala": ("Left-Amygdala", "Right-Amygdala"),
        "Entorhinal": ("lh-entorhinal", "rh-entorhinal"),
    }

    for name, (lcol, rcol) in pairs.items():
        if lcol in df.columns and rcol in df.columns:
            L = pd.to_numeric(df[lcol], errors="coerce")
            R = pd.to_numeric(df[rcol], errors="coerce")
            mean = (L + R) / 2.0
            out[f"{name}_low_volume_risk"] = -mean

    # Normalized ROI risk if total brain volume is available
    norm_col = "Total_Labeled_Brain_Volume_mm3"
    if norm_col in df.columns:
        total = pd.to_numeric(df[norm_col], errors="coerce")
        for name, (lcol, rcol) in pairs.items():
            if lcol in df.columns and rcol in df.columns:
                L = pd.to_numeric(df[lcol], errors="coerce")
                R = pd.to_numeric(df[rcol], errors="coerce")
                mean_norm = ((L + R) / 2.0) / (total + 1e-8)
                out[f"{name}_low_norm_volume_risk"] = -mean_norm

    return out

def get_micro_raw_aligned(merged, micro_original):
    aligned = merged[["ID"]].merge(micro_original, on="ID", how="left")
    exclude = {"ID", LABEL_COL}
    micro_cols = [c for c in aligned.columns if c not in exclude]
    X = safe_numeric(aligned[micro_cols]).dropna(axis=1, how="all").fillna(0.0).clip(lower=0)
    return X

def microbiome_diversity_features(X_raw):
    X = X_raw.fillna(0.0).clip(lower=0)
    total = X.sum(axis=1).values.reshape(-1, 1)
    P = X.values / (total + 1e-12)

    richness = (X.values > 0).sum(axis=1)
    shannon = -(P * np.log(P + 1e-12)).sum(axis=1)
    simpson = 1.0 - (P ** 2).sum(axis=1)
    evenness = shannon / (np.log(richness + 1e-12) + 1e-12)

    return pd.DataFrame({
        "micro_richness": richness,
        "micro_shannon": shannon,
        "micro_simpson": simpson,
        "micro_evenness": evenness,
        "micro_total_abundance": X.sum(axis=1).values,
    }, index=X_raw.index)

def clr_transform(X_raw, pseudo_count=1e-6):
    X = X_raw.fillna(0.0).clip(lower=0) + pseudo_count
    logX = np.log(X)
    clr = logX.values - logX.mean(axis=1).values.reshape(-1, 1)
    return pd.DataFrame(clr, index=X.index, columns=[f"CLR_{c}" for c in X.columns])

def zscore_composite_score(df, direction="higher_is_risk"):
    """
    df columns should already be oriented so higher means higher risk.
    """
    X = df.replace([np.inf, -np.inf], np.nan)
    X_imp = SimpleImputer(strategy="median").fit_transform(X)
    X_z = StandardScaler().fit_transform(X_imp)
    score = np.nanmean(X_z, axis=1)
    return score

def top_flag(score, top_quantile=0.20):
    threshold = np.quantile(score, 1 - top_quantile)
    return (score >= threshold).astype(int), threshold

def jaccard(a, b):
    a = np.asarray(a).astype(bool)
    b = np.asarray(b).astype(bool)
    inter = np.logical_and(a, b).sum()
    union = np.logical_or(a, b).sum()
    return inter / union if union > 0 else np.nan

# -----------------------------
# Main analysis
# -----------------------------
basic, micro, brain, merged, y = load_and_merge()

# 1. Brain-related risk marker score
brain_marker_df = build_brain_marker_features(merged)

# Optional: remove MMSE if you think it is too close to diagnosis
# brain_marker_df = brain_marker_df.drop(columns=["MMSE_low_risk"], errors="ignore")

brain_risk_score = zscore_composite_score(brain_marker_df)

# 2. Microbiome-related risk marker score
micro_raw = get_micro_raw_aligned(merged, micro)

# Diversity features
micro_div = microbiome_diversity_features(micro_raw)

# CLR features + microbiome PC
micro_clr = clr_transform(micro_raw)
micro_clr_imp = SimpleImputer(strategy="median").fit_transform(micro_clr)
micro_clr_z = StandardScaler().fit_transform(micro_clr_imp)

n_pc = min(5, micro_clr_z.shape[1], micro_clr_z.shape[0] - 2)
micro_pcs = PCA(n_components=n_pc, random_state=42).fit_transform(micro_clr_z)
micro_pc_df = pd.DataFrame(
    micro_pcs,
    columns=[f"micro_PC{i+1}" for i in range(n_pc)],
    index=merged.index
)

# If you have known/suggestive taxa from RQ4, add them here if present
candidate_taxa = [
    "CLR_Parabacteroides_unclassified",
    "CLR_Ruminococcus_lactaris",
    "CLR_Bacteroides_fragilis",
]

micro_marker_df = pd.concat([micro_div, micro_pc_df], axis=1)

for taxon in candidate_taxa:
    if taxon in micro_clr.columns:
        micro_marker_df[taxon] = micro_clr[taxon]

# Because microbiome risk direction is not always biologically fixed,
# create a data-driven risk-oriented version:
# If a microbiome marker is higher in Risk than Normal, keep it.
# If lower in Risk than Normal, multiply by -1.
micro_marker_oriented = pd.DataFrame(index=micro_marker_df.index)

for col in micro_marker_df.columns:
    vals = pd.to_numeric(micro_marker_df[col], errors="coerce")
    mean_risk = vals[y == 1].mean()
    mean_normal = vals[y == 0].mean()
    sign = 1 if mean_risk >= mean_normal else -1
    micro_marker_oriented[f"{col}_risk_oriented"] = sign * vals

micro_risk_score = zscore_composite_score(micro_marker_oriented)

# 3. High-risk flags from each modality
brain_flag_20, brain_thr = top_flag(brain_risk_score, top_quantile=0.20)
micro_flag_20, micro_thr = top_flag(micro_risk_score, top_quantile=0.20)

brain_flag_30, _ = top_flag(brain_risk_score, top_quantile=0.30)
micro_flag_30, _ = top_flag(micro_risk_score, top_quantile=0.30)

# 4. Agreement statistics
rho, rho_p = spearmanr(brain_risk_score, micro_risk_score, nan_policy="omit")

summary_rows = []

for q, bf, mf in [
    ("top20", brain_flag_20, micro_flag_20),
    ("top30", brain_flag_30, micro_flag_30),
]:
    summary_rows.append({
        "analysis": f"{q}_brain_micro_high_risk_overlap",
        "spearman_rho": rho,
        "spearman_p_value": rho_p,
        "jaccard_overlap": jaccard(bf, mf),
        "cohen_kappa": cohen_kappa_score(bf, mf),
        "brain_high_count": int(bf.sum()),
        "micro_high_count": int(mf.sum()),
        "both_high_count": int(np.logical_and(bf == 1, mf == 1).sum()),
        "brain_only_count": int(np.logical_and(bf == 1, mf == 0).sum()),
        "micro_only_count": int(np.logical_and(bf == 0, mf == 1).sum()),
    })

summary_df = pd.DataFrame(summary_rows)

# 5. Patient-level output
patient_scores = pd.DataFrame({
    "ID": merged["ID"].values,
    "Diagnosis": merged[LABEL_COL].values,
    "y_true": y,
    "brain_risk_score": brain_risk_score,
    "microbiome_risk_score": micro_risk_score,
    "brain_high_top20": brain_flag_20,
    "micro_high_top20": micro_flag_20,
    "brain_high_top30": brain_flag_30,
    "micro_high_top30": micro_flag_30,
})

patient_scores["risk_marker_group_top20"] = "neither_high"
patient_scores.loc[(patient_scores["brain_high_top20"] == 1) & (patient_scores["micro_high_top20"] == 0), "risk_marker_group_top20"] = "brain_only_high"
patient_scores.loc[(patient_scores["brain_high_top20"] == 0) & (patient_scores["micro_high_top20"] == 1), "risk_marker_group_top20"] = "microbiome_only_high"
patient_scores.loc[(patient_scores["brain_high_top20"] == 1) & (patient_scores["micro_high_top20"] == 1), "risk_marker_group_top20"] = "both_high"

# 6. Group-level outcome enrichment
enrichment = (
    patient_scores.groupby("risk_marker_group_top20")
    .agg(
        n=("ID", "count"),
        risk_rate=("y_true", "mean"),
        mean_brain_score=("brain_risk_score", "mean"),
        mean_micro_score=("microbiome_risk_score", "mean"),
    )
    .reset_index()
)

# 7. Save
summary_path = os.path.join(OUT_DIR, "RQ2_03_risk_marker_overlap_summary.csv")
patient_path = os.path.join(OUT_DIR, "RQ2_03_risk_marker_patient_scores.csv")
enrich_path = os.path.join(OUT_DIR, "RQ2_03_risk_marker_group_enrichment.csv")

summary_df.to_csv(summary_path, index=False, encoding="utf-8-sig")
patient_scores.to_csv(patient_path, index=False, encoding="utf-8-sig")
enrichment.to_csv(enrich_path, index=False, encoding="utf-8-sig")

print("Saved:", summary_path)
print("Saved:", patient_path)
print("Saved:", enrich_path)

print("\n=== Risk-marker Discordance Summary ===")
display(summary_df)

print("\n=== Risk-marker Group Enrichment ===")
display(enrichment)

