@dataclass
class Config:
    basic_path: str = "/content/data.csv"
    micro_path: str = "/content/micro.csv"
    brain_path: str = "/content/all_brain_result_1(3).csv"
    output_dir: str = "/content/icdm_tuned_vgib_outputs"

    id_col_basic: str = "ID"
    id_col_micro: str = "ID"
    id_col_brain: str = "Subject_ID"
    label_col: str = "Diagnosis"

    random_seed: int = 42
    seeds: Tuple[int, ...] = (42, 52, 62, 72, 82)
    n_splits: int = 5

    # Main ICDM task: Normal vs Risk(MCI + Dementia)
    task_mode: str = "binary_risk"

    # Microbiome filtering / representation
    top_k_species: int = 50
    min_prevalence: float = 0.02
    abundance_edge_threshold: float = 0.0
    pseudo_count: float = 1e-6

    # Model size
    hidden_dim: int = 64
    latent_dim: int = 32
    num_layers: int = 2
    heads: int = 2
    dropout: float = 0.35
    lr: float = 1e-3
    weight_decay: float = 1e-4
    epochs: int = 250
    patience: int = 40

    # Tuned VGIB grid. This is the important correction.
    edge_rep_grid: Tuple[str, ...] = ("log1p", "clr", "presence")
    beta_grid: Tuple[float, ...] = (0.0, 1e-5, 1e-4, 5e-4, 1e-3)
    gamma_grid: Tuple[float, ...] = (0.5, 1.0, 1.5, 2.0)
    threshold_policy_grid: Tuple[str, ...] = (
        "max_risk_f1",
        "max_recall_precision_floor",
        "max_macro_f1",
    )
    tuning_precision_floor: float = 0.50

    # If precision >= floor, select by recall first. Otherwise use risk_f1 as fallback.
    tuning_primary_metric: str = "screening_recall_with_precision_floor"

    # Bootstrap / threshold matching
    n_bootstrap: int = 3000
    alpha: float = 0.05
    threshold_grid_size: int = 99
    target_precision: float = 0.70
    target_recall: float = 0.70

    # RQ4 disagreement profile
    rq4_model_name: str = "VGIB-HGNN-Focal-Tuned"
    rq4_top_species_report: int = 30

    # Runtime switches
    run_tuning: bool = True
    run_repeated_seed: bool = True
    run_bootstrap: bool = True
    run_threshold_matched: bool = True
    run_rq3: bool = True
    run_rq4: bool = True


CFG = Config()

if os.path.exists("/mnt/data/data.csv"):
    CFG.basic_path = "/mnt/data/data.csv"
    CFG.micro_path = "/mnt/data/micro.csv"
    CFG.brain_path = "/mnt/data/all_brain_result_1(3).csv"
    CFG.output_dir = "/mnt/data/icdm_tuned_vgib_outputs"


# ============================================================
# 2. Utilities
# ============================================================

def set_seed(seed: int = 42):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    torch.cuda.manual_seed_all(seed)


def ensure_dir(path: str):
    os.makedirs(path, exist_ok=True)


def save_csv(df: pd.DataFrame, path: str):
    df.to_csv(path, index=False, encoding="utf-8-sig")
    print("Saved:", path)


def extract_tpmic_id(x):
    m = re.search(r"TPMIC\d+", str(x))
    return m.group(0) if m else None


def replace_missing_codes(df: pd.DataFrame):
    return df.replace([999, 999.0, "999", "999.0", "NA", "N/A", "", "nan", "None"], np.nan)


def encode_sex_like(series: pd.Series):
    if pd.api.types.is_numeric_dtype(series):
        return pd.to_numeric(series, errors="coerce")
    mapping = {
        "m": 1, "male": 1, "man": 1, "男": 1, "男性": 1, "1": 1,
        "f": 0, "female": 0, "woman": 0, "女": 0, "女性": 0, "0": 0,
    }
    return series.astype(str).str.strip().str.lower().map(mapping)


def safe_numeric(df: pd.DataFrame):
    out = df.copy()
    for c in out.columns:
        if c.lower() in ["sex", "gender"]:
            out[c] = encode_sex_like(out[c])
        else:
            out[c] = pd.to_numeric(out[c], errors="coerce")
    return out


def cv_splitter(y, cfg: Config, seed: Optional[int] = None):
    min_class = pd.Series(y).value_counts().min()
    n_splits = max(2, min(cfg.n_splits, int(min_class)))
    return StratifiedKFold(n_splits=n_splits, shuffle=True, random_state=cfg.random_seed if seed is None else seed)


def train_val_split(train_idx, y, seed: int):
    train_idx = np.asarray(train_idx)
    y_train = y[train_idx]
    if len(np.unique(y_train)) < 2 or pd.Series(y_train).value_counts().min() < 2:
        return train_idx, train_idx
    tr_sub, val_sub = train_test_split(
        train_idx,
        test_size=0.2,
        stratify=y_train,
        random_state=seed,
    )
    return np.asarray(tr_sub), np.asarray(val_sub)


def threshold_values(cfg: Config):
    return np.linspace(0.01, 0.99, cfg.threshold_grid_size)


def binary_metrics(y_true, prob, threshold=0.5, pred=None):
    y_true = np.asarray(y_true).astype(int)
    prob = np.asarray(prob).astype(float)
    if pred is None:
        pred = (prob >= threshold).astype(int)
    else:
        pred = np.asarray(pred).astype(int)

    out = {
        "auc": np.nan,
        "pr_auc": np.nan,
        "macro_f1": f1_score(y_true, pred, average="macro", zero_division=0),
        "risk_recall": recall_score(y_true, pred, pos_label=1, zero_division=0),
        "risk_precision": precision_score(y_true, pred, pos_label=1, zero_division=0),
        "risk_f1": f1_score(y_true, pred, pos_label=1, zero_division=0),
        "balanced_acc": balanced_accuracy_score(y_true, pred),
        "acc": accuracy_score(y_true, pred),
        "predicted_risk_rate": float(np.mean(pred == 1)),
        "brier": np.nan,
    }
    if len(np.unique(y_true)) == 2:
        out["auc"] = roc_auc_score(y_true, prob)
        out["pr_auc"] = average_precision_score(y_true, prob)
        out["brier"] = brier_score_loss(y_true, prob)
    return out


def choose_threshold(y, prob, policy: str, cfg: Config, target=None):
    y = np.asarray(y).astype(int)
    prob = np.asarray(prob).astype(float)
    if policy == "default_0.5":
        return 0.5

    best_t, best_score = 0.5, -np.inf
    for t in threshold_values(cfg):
        pred = (prob >= t).astype(int)
        rec = recall_score(y, pred, pos_label=1, zero_division=0)
        prec = precision_score(y, pred, pos_label=1, zero_division=0)
        rf1 = f1_score(y, pred, pos_label=1, zero_division=0)
        mf1 = f1_score(y, pred, average="macro", zero_division=0)
        rate = np.mean(pred == 1)

        if policy == "max_risk_f1":
            score = rf1
        elif policy == "max_macro_f1":
            score = mf1
        elif policy == "max_recall_precision_floor":
            floor = cfg.tuning_precision_floor if target is None else float(target)
            score = rec if prec >= floor else -np.inf
        elif policy == "match_predicted_rate":
            score = -abs(rate - float(target))
        elif policy == "recall_at_precision":
            score = rec if prec >= float(target) else -np.inf
        elif policy == "precision_at_recall":
            score = prec if rec >= float(target) else -np.inf
        else:
            raise ValueError(f"Unknown threshold policy: {policy}")

        if score > best_score:
            best_score = score
            best_t = t

    if not np.isfinite(best_score):
        # fallback if precision floor cannot be met
        return choose_threshold(y, prob, "max_risk_f1", cfg)
    return float(best_t)


def aggregate_rows(df: pd.DataFrame, group_cols: List[str]):
    metric_cols = [c for c in df.columns if c not in group_cols and pd.api.types.is_numeric_dtype(df[c])]
    rows = []
    for keys, sub in df.groupby(group_cols):
        if not isinstance(keys, tuple):
            keys = (keys,)
        row = {k: v for k, v in zip(group_cols, keys)}
        for c in metric_cols:
            row[c] = float(sub[c].mean())
            row[f"{c}_std"] = float(sub[c].std(ddof=0))
        rows.append(row)
    return pd.DataFrame(rows)


def standardize_matrix(X):
    X = pd.DataFrame(X).replace([np.inf, -np.inf], np.nan)
    X = SimpleImputer(strategy="median").fit_transform(X)
    return StandardScaler().fit_transform(X)


# ============================================================
# 3. Data loading and feature engineering
# ============================================================

def load_and_merge(cfg: Config):
    basic = replace_missing_codes(pd.read_csv(cfg.basic_path))
    micro = replace_missing_codes(pd.read_csv(cfg.micro_path))
    brain = replace_missing_codes(pd.read_csv(cfg.brain_path))

    brain["ID"] = brain[cfg.id_col_brain].apply(extract_tpmic_id)
    brain = brain.dropna(subset=["ID"]).copy()

    keep_labels = ["Normal", "MCI", "Dementia"]
    basic[cfg.label_col] = basic[cfg.label_col].astype(str)
    basic = basic[basic[cfg.label_col].isin(keep_labels)].copy()

    merged = (
        basic.merge(micro, on="ID", how="inner", suffixes=("", "_micro"))
             .merge(brain, on="ID", how="inner", suffixes=("", "_brain"))
    )

    print("========== Data Summary ==========")
    print("basic:", basic.shape, "micro:", micro.shape, "brain:", brain.shape)
    print("merged:", merged.shape)
    print(merged[cfg.label_col].value_counts())
    print("==================================\n")
    return basic, micro, brain, merged


def make_binary_labels(diagnosis: pd.Series):
    return diagnosis.map({"Normal": 0, "MCI": 1, "Dementia": 1}).astype(int).values


def build_basic_features(df: pd.DataFrame, include_mmse=False):
    cols = ["Sex", "Age", "edu_yr", "BMI", "smoking", "drinking", "exercise_days"]
    if include_mmse:
        cols.append("MMSE")
    cols = [c for c in cols if c in df.columns]
    return safe_numeric(df[cols])


def build_brain_features(df: pd.DataFrame):
    candidate_cols = [
        "Left-Hippocampus", "Right-Hippocampus",
        "Left-Amygdala", "Right-Amygdala",
        "lh-entorhinal", "rh-entorhinal",
    ]
    brain_cols = [c for c in candidate_cols if c in df.columns]
    out = pd.DataFrame(index=df.index)
    for c in brain_cols:
        out[c] = pd.to_numeric(df[c], errors="coerce")

    pairs = {
        "Hippocampus": ("Left-Hippocampus", "Right-Hippocampus"),
        "Amygdala": ("Left-Amygdala", "Right-Amygdala"),
        "Entorhinal": ("lh-entorhinal", "rh-entorhinal"),
    }
    for name, (lcol, rcol) in pairs.items():
        if lcol in df.columns and rcol in df.columns:
            L = pd.to_numeric(df[lcol], errors="coerce")
            R = pd.to_numeric(df[rcol], errors="coerce")
            mean = (L + R) / 2.0
            out[f"{name}_mean"] = mean
            out[f"{name}_diff"] = L - R
            out[f"{name}_asymmetry"] = (L - R).abs() / (mean.abs() + 1e-8)

    norm_col = "Total_Labeled_Brain_Volume_mm3"
    if norm_col in df.columns:
        total = pd.to_numeric(df[norm_col], errors="coerce")
        for c in brain_cols:
            out[f"{c}_norm"] = pd.to_numeric(df[c], errors="coerce") / (total + 1e-8)
    return out


def get_micro_raw_aligned(merged: pd.DataFrame, micro_original: pd.DataFrame, cfg: Config):
    aligned = merged[["ID"]].merge(micro_original, on="ID", how="left")
    exclude = {"ID", cfg.label_col}
    micro_cols = [c for c in aligned.columns if c not in exclude]
    X = safe_numeric(aligned[micro_cols]).dropna(axis=1, how="all").fillna(0.0).clip(lower=0)
    return X


def select_topk_micro_global(X_raw: pd.DataFrame, cfg: Config):
    prevalence = (X_raw > 0).mean(axis=0)
    keep = prevalence[prevalence >= cfg.min_prevalence].index.tolist()
    if len(keep) == 0:
        keep = X_raw.columns.tolist()
    X = X_raw[keep]
    selected = X.var(axis=0).sort_values(ascending=False).head(min(cfg.top_k_species, X.shape[1])).index.tolist()
    return selected


def log1p_micro(X_raw: pd.DataFrame, cols: List[str]):
    return np.log1p(X_raw[cols].fillna(0.0).clip(lower=0))


def presence_micro(X_raw: pd.DataFrame, cols: List[str]):
    return (X_raw[cols].fillna(0.0) > 0).astype(float)


def clr_transform_df(X_raw: pd.DataFrame, cols: List[str], pseudo_count: float = 1e-6):
    X = X_raw[cols].fillna(0.0).clip(lower=0) + pseudo_count
    logX = np.log(X)
    gm = logX.mean(axis=1).values.reshape(-1, 1)
    clr = logX.values - gm
    return pd.DataFrame(clr, index=X.index, columns=[f"CLR_{c}" for c in cols])


def microbiome_diversity_features(X_raw: pd.DataFrame):
    X = X_raw.fillna(0.0).clip(lower=0)
    total = X.sum(axis=1).values.reshape(-1, 1)
    P = X.values / (total + 1e-12)
    richness = (X.values > 0).sum(axis=1)
    shannon = -(P * np.log(P + 1e-12)).sum(axis=1)
    simpson = 1.0 - (P ** 2).sum(axis=1)
    evenness = shannon / (np.log(richness + 1e-12) + 1e-12)
    return pd.DataFrame({
        "micro_richness": richness,
        "micro_shannon": shannon,
        "micro_simpson": simpson,
        "micro_evenness": evenness,
        "micro_total_abundance": X.sum(axis=1).values,
    }, index=X.index)


def prepare_features(merged: pd.DataFrame, micro_original: pd.DataFrame, cfg: Config):
    y = make_binary_labels(merged[cfg.label_col])
    basic_x = build_basic_features(merged, include_mmse=False).reset_index(drop=True)
    brain_x = build_brain_features(merged).reset_index(drop=True)
    brainclinical_x = pd.concat([basic_x, brain_x], axis=1).reset_index(drop=True)

    micro_raw = get_micro_raw_aligned(merged, micro_original, cfg).reset_index(drop=True)
    selected_species = select_topk_micro_global(micro_raw, cfg)

    micro_log = log1p_micro(micro_raw, selected_species).reset_index(drop=True)
    micro_clr = clr_transform_df(micro_raw, selected_species, cfg.pseudo_count).reset_index(drop=True)
    micro_presence = presence_micro(micro_raw, selected_species).reset_index(drop=True)
    micro_div = microbiome_diversity_features(micro_raw).reset_index(drop=True)

    return {
        "y": y,
        "basic_x": basic_x,
        "brain_x": brain_x,
        "brainclinical_x": brainclinical_x,
        "micro_raw": micro_raw,
        "micro_log": micro_log,
        "micro_clr": micro_clr,
        "micro_presence": micro_presence,
        "micro_div": micro_div,
        "alltabular_log": pd.concat([brainclinical_x, micro_log], axis=1).reset_index(drop=True),
        "alltabular_clr": pd.concat([brainclinical_x, micro_clr], axis=1).reset_index(drop=True),
        "alltabular_div": pd.concat([brainclinical_x, micro_div], axis=1).reset_index(drop=True),
        "alltabular_clr_div": pd.concat([brainclinical_x, micro_clr, micro_div], axis=1).reset_index(drop=True),
        "selected_species": selected_species,
    }


def get_edge_rep_df(feats: Dict, edge_rep: str):
    if edge_rep == "log1p":
        return feats["micro_log"]
    if edge_rep == "clr":
        return feats["micro_clr"]
    if edge_rep == "presence":
        return feats["micro_presence"]
    raise ValueError(f"Unknown edge_rep: {edge_rep}")


# ============================================================
# 4. Graph and models
# ============================================================

def build_heterodata(patient_df: pd.DataFrame, micro_edge_df: pd.DataFrame, y: np.ndarray, cfg: Config):
    patient_df = pd.DataFrame(patient_df).replace([np.inf, -np.inf], np.nan)
    micro_edge_df = pd.DataFrame(micro_edge_df).replace([np.inf, -np.inf], np.nan).fillna(0.0)

    patient_x = SimpleImputer(strategy="median").fit_transform(patient_df)
    patient_x = StandardScaler().fit_transform(patient_x)

    values = micro_edge_df.values.astype(np.float32)
    edge_mask_values = np.abs(values)
    valid_values = values[edge_mask_values > cfg.abundance_edge_threshold]
    edge_mean = valid_values.mean() if len(valid_values) else 0.0
    edge_std = valid_values.std() + 1e-8 if len(valid_values) else 1.0

    n_patients, n_species = values.shape
    species_prevalence = (edge_mask_values > cfg.abundance_edge_threshold).mean(axis=0)
    species_mean_abs = np.abs(values).mean(axis=0)
    species_x = np.stack([species_prevalence, species_mean_abs], axis=1)
    species_x = StandardScaler().fit_transform(species_x)

    src_pat, dst_sp, attrs = [], [], []
    for i in range(n_patients):
        nz = np.where(edge_mask_values[i] > cfg.abundance_edge_threshold)[0]
        for j in nz:
            src_pat.append(i)
            dst_sp.append(j)
            attrs.append([(values[i, j] - edge_mean) / edge_std])

    if len(src_pat) == 0:
        raise ValueError("No microbiome edges were created. Lower threshold or check data.")

    edge_index_p2s = torch.tensor([src_pat, dst_sp], dtype=torch.long)
    edge_attr_p2s = torch.tensor(attrs, dtype=torch.float32)
    edge_index_s2p = torch.tensor([dst_sp, src_pat], dtype=torch.long)

    data = HeteroData()
    data["patient"].x = torch.tensor(patient_x, dtype=torch.float32)
    data["species"].x = torch.tensor(species_x, dtype=torch.float32)
    data["patient"].y = torch.tensor(y, dtype=torch.long)
    data[("patient", "has", "species")].edge_index = edge_index_p2s
    data[("patient", "has", "species")].edge_attr = edge_attr_p2s
    data[("species", "rev_has", "patient")].edge_index = edge_index_s2p
    data[("species", "rev_has", "patient")].edge_attr = edge_attr_p2s.clone()
    return data


def randomize_micro_edges(data: HeteroData, seed: int = 42):
    rng = np.random.default_rng(seed)
    out = data.clone()
    p2s = out[("patient", "has", "species")].edge_index.cpu().numpy()
    src = p2s[0]
    n_species = out["species"].x.size(0)
    new_dst = rng.integers(0, n_species, size=len(src))
    out[("patient", "has", "species")].edge_index = torch.tensor([src, new_dst], dtype=torch.long)
    out[("species", "rev_has", "patient")].edge_index = torch.tensor([new_dst, src], dtype=torch.long)
    return out


class FocalLoss(nn.Module):
    def __init__(self, gamma=2.0, alpha=None):
        super().__init__()
        self.gamma = gamma
        self.alpha = alpha

    def forward(self, logits, target):
        ce = F.cross_entropy(logits, target, weight=self.alpha, reduction="none")
        pt = torch.exp(-ce)
        return (((1 - pt) ** self.gamma) * ce).mean()


def class_weights_tensor(y_train: np.ndarray, device):
    counts = np.bincount(y_train.astype(int), minlength=2)
    weights = counts.sum() / (counts + 1e-8)
    weights = weights / weights.mean()
    return torch.tensor(weights, dtype=torch.float32, device=device)


def kl_normal(mu, logvar):
    return -0.5 * torch.mean(torch.sum(1 + logvar - mu.pow(2) - logvar.exp(), dim=1))


class VGIBHGNN(nn.Module):
    def __init__(self, patient_in_dim, species_in_dim, hidden_dim, latent_dim,
                 num_layers=2, heads=2, dropout=0.35, use_gaussian=True):
        super().__init__()
        self.dropout = dropout
        self.use_gaussian = use_gaussian
        self.patient_encoder = Linear(patient_in_dim, hidden_dim)
        self.species_encoder = Linear(species_in_dim, hidden_dim)

        assert hidden_dim % heads == 0, "hidden_dim must be divisible by heads"
        out_per_head = hidden_dim // heads
        self.convs = nn.ModuleList()
        for _ in range(num_layers):
            self.convs.append(HeteroConv({
                ("patient", "has", "species"): GATConv(
                    (hidden_dim, hidden_dim), out_per_head,
                    heads=heads, edge_dim=1, add_self_loops=False, dropout=dropout,
                ),
                ("species", "rev_has", "patient"): GATConv(
                    (hidden_dim, hidden_dim), out_per_head,
                    heads=heads, edge_dim=1, add_self_loops=False, dropout=dropout,
                ),
            }, aggr="sum"))

        self.mu_layer = nn.Linear(hidden_dim, latent_dim)
        self.logvar_layer = nn.Linear(hidden_dim, latent_dim)
        self.det_layer = nn.Linear(hidden_dim, latent_dim)
        self.classifier = nn.Sequential(
            nn.Linear(latent_dim, hidden_dim),
            nn.ReLU(),
            nn.Dropout(dropout),
            nn.Linear(hidden_dim, 2),
        )

    def reparameterize(self, mu, logvar):
        if not self.training:
            return mu
        std = torch.exp(0.5 * logvar)
        return mu + torch.randn_like(std) * std

    def forward(self, x_dict, edge_index_dict, edge_attr_dict):
        x_dict = {
            "patient": F.relu(self.patient_encoder(x_dict["patient"])),
            "species": F.relu(self.species_encoder(x_dict["species"])),
        }
        for conv in self.convs:
            new_x = conv(x_dict, edge_index_dict, edge_attr_dict=edge_attr_dict)
            for k in x_dict.keys():
                if k in new_x:
                    x_dict[k] = F.relu(new_x[k] + x_dict[k])
                    x_dict[k] = F.dropout(x_dict[k], p=self.dropout, training=self.training)
        h = x_dict["patient"]
        if self.use_gaussian:
            mu = self.mu_layer(h)
            logvar = self.logvar_layer(h).clamp(-8, 8)
            z = self.reparameterize(mu, logvar)
        else:
            z = self.det_layer(h)
            mu = z
            logvar = torch.zeros_like(z)
        return self.classifier(z), mu, logvar


class MLPClassifier(nn.Module):
    def __init__(self, in_dim, hidden_dim=64, dropout=0.35):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden_dim),
            nn.ReLU(),
            nn.Dropout(dropout),
            nn.Linear(hidden_dim, hidden_dim),
            nn.ReLU(),
            nn.Dropout(dropout),
            nn.Linear(hidden_dim, 2),
        )

    def forward(self, x):
        return self.net(x)


class PatientOnlyVGIB(nn.Module):
    def __init__(self, in_dim, hidden_dim, latent_dim, dropout=0.35, use_gaussian=True):
        super().__init__()
        self.use_gaussian = use_gaussian
        self.encoder = nn.Sequential(
            nn.Linear(in_dim, hidden_dim),
            nn.ReLU(),
            nn.Dropout(dropout),
            nn.Linear(hidden_dim, hidden_dim),
            nn.ReLU(),
        )
        self.mu_layer = nn.Linear(hidden_dim, latent_dim)
        self.logvar_layer = nn.Linear(hidden_dim, latent_dim)
        self.det_layer = nn.Linear(hidden_dim, latent_dim)
        self.classifier = nn.Sequential(
            nn.Linear(latent_dim, hidden_dim),
            nn.ReLU(),
            nn.Dropout(dropout),
            nn.Linear(hidden_dim, 2),
        )

    def reparameterize(self, mu, logvar):
        if not self.training:
            return mu
        std = torch.exp(0.5 * logvar)
        return mu + torch.randn_like(std) * std

    def forward(self, x):
        h = self.encoder(x)
        if self.use_gaussian:
            mu = self.mu_layer(h)
            logvar = self.logvar_layer(h).clamp(-8, 8)
            z = self.reparameterize(mu, logvar)
        else:
            z = self.det_layer(h)
            mu = z
            logvar = torch.zeros_like(z)
        return self.classifier(z), mu, logvar


# ============================================================
# 5. Training helpers with fold-specific validation thresholds
# ============================================================

def train_hgnn_fold(data: HeteroData, y: np.ndarray, train_idx, test_idx, cfg: Config,
                    loss_type="focal", use_gaussian=True, use_ib=True,
                    beta=1e-4, gamma=1.0, threshold_policy="max_risk_f1", seed=42):
    set_seed(seed)
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    data = data.to(device)
    labels = data["patient"].y
    tr_sub, val_sub = train_val_split(train_idx, y, seed)

    n = len(y)
    tr_mask = torch.zeros(n, dtype=torch.bool, device=device)
    val_mask = torch.zeros(n, dtype=torch.bool, device=device)
    test_mask = torch.zeros(n, dtype=torch.bool, device=device)
    tr_mask[torch.tensor(tr_sub, dtype=torch.long, device=device)] = True
    val_mask[torch.tensor(val_sub, dtype=torch.long, device=device)] = True
    test_mask[torch.tensor(test_idx, dtype=torch.long, device=device)] = True

    model = VGIBHGNN(
        patient_in_dim=data["patient"].x.size(1),
        species_in_dim=data["species"].x.size(1),
        hidden_dim=cfg.hidden_dim,
        latent_dim=cfg.latent_dim,
        num_layers=cfg.num_layers,
        heads=cfg.heads,
        dropout=cfg.dropout,
        use_gaussian=use_gaussian,
    ).to(device)

    if loss_type == "focal":
        criterion = FocalLoss(gamma=gamma, alpha=class_weights_tensor(y[tr_sub], device))
    elif loss_type == "ce_weighted":
        criterion = nn.CrossEntropyLoss(weight=class_weights_tensor(y[tr_sub], device))
    else:
        criterion = nn.CrossEntropyLoss()

    opt = torch.optim.AdamW(model.parameters(), lr=cfg.lr, weight_decay=cfg.weight_decay)
    best_state, best_val_loss, bad = None, np.inf, 0
    t0 = time.perf_counter()

    for epoch in range(cfg.epochs):
        model.train()
        opt.zero_grad()
        logits, mu, logvar = model(data.x_dict, data.edge_index_dict, data.edge_attr_dict)
        loss = criterion(logits[tr_mask], labels[tr_mask])
        if use_ib and use_gaussian and beta > 0:
            loss = loss + beta * kl_normal(mu[tr_mask], logvar[tr_mask])
        loss.backward()
        torch.nn.utils.clip_grad_norm_(model.parameters(), 5.0)
        opt.step()

        model.eval()
        with torch.no_grad():
            logits_v, mu_v, logvar_v = model(data.x_dict, data.edge_index_dict, data.edge_attr_dict)
            vloss = criterion(logits_v[val_mask], labels[val_mask])
            if use_ib and use_gaussian and beta > 0:
                vloss = vloss + beta * kl_normal(mu_v[val_mask], logvar_v[val_mask])
            v = float(vloss.detach().cpu())

        if v < best_val_loss:
            best_val_loss = v
            best_state = {k: vv.detach().cpu().clone() for k, vv in model.state_dict().items()}
            bad = 0
        else:
            bad += 1
            if bad >= cfg.patience:
                break

    runtime = time.perf_counter() - t0
    if best_state is not None:
        model.load_state_dict({k: vv.to(device) for k, vv in best_state.items()})

    model.eval()
    with torch.no_grad():
        logits, mu, logvar = model(data.x_dict, data.edge_index_dict, data.edge_attr_dict)
        prob_all = F.softmax(logits, dim=1).detach().cpu().numpy()[:, 1]
        mu_all = mu.detach().cpu().numpy()
        logvar_all = logvar.detach().cpu().numpy()

    val_prob = prob_all[val_sub]
    val_y = y[val_sub]
    th = choose_threshold(val_y, val_prob, threshold_policy, cfg)
    test_prob = prob_all[test_idx]
    test_pred = (test_prob >= th).astype(int)

    return {
        "test_prob": test_prob,
        "test_pred": test_pred,
        "threshold": th,
        "runtime_sec": runtime,
        "epochs_used": epoch + 1,
        "prob_all_last": prob_all,
        "mu_all_last": mu_all,
        "logvar_all_last": logvar_all,
    }


def eval_hgnn_oof(data: HeteroData, y: np.ndarray, cfg: Config, seed: int, model_name: str,
                  loss_type="focal", use_gaussian=True, use_ib=True,
                  beta=1e-4, gamma=1.0, threshold_policy="max_risk_f1"):
    skf = cv_splitter(y, cfg, seed)
    oof_prob = np.zeros(len(y), dtype=float)
    oof_pred = np.zeros(len(y), dtype=int)
    thresholds = np.zeros(len(y), dtype=float)
    runtimes, epochs = [], []
    mu_last, logvar_last = None, None

    for fold, (tr, te) in enumerate(skf.split(np.zeros(len(y)), y), 1):
        print(f"[HGNN seed={seed}] {model_name} fold {fold}/{skf.get_n_splits()} | beta={beta} gamma={gamma} policy={threshold_policy}")
        res = train_hgnn_fold(
            data, y, tr, te, cfg,
            loss_type=loss_type,
            use_gaussian=use_gaussian,
            use_ib=use_ib,
            beta=beta,
            gamma=gamma,
            threshold_policy=threshold_policy,
            seed=seed + fold,
        )
        oof_prob[te] = res["test_prob"]
        oof_pred[te] = res["test_pred"]
        thresholds[te] = res["threshold"]
        runtimes.append(res["runtime_sec"])
        epochs.append(res["epochs_used"])
        mu_last = res["mu_all_last"]
        logvar_last = res["logvar_all_last"]

    metrics = binary_metrics(y, oof_prob, pred=oof_pred)
    metrics.update({
        "model": model_name,
        "seed": seed,
        "threshold_policy": threshold_policy,
        "threshold_mean": float(np.mean(thresholds)),
        "runtime_sec_total": float(np.sum(runtimes)),
        "epochs_used_mean": float(np.mean(epochs)),
        "beta": beta,
        "gamma": gamma,
    })
    return pd.DataFrame([metrics]), {model_name: {"prob": oof_prob, "pred": oof_pred, "thresholds": thresholds, "mu_last": mu_last, "logvar_last": logvar_last}}


def fit_transform_train_val_test(X, tr_sub, val_sub, te):
    X = pd.DataFrame(X).replace([np.inf, -np.inf], np.nan).reset_index(drop=True)
    imp = SimpleImputer(strategy="median")
    sc = StandardScaler()
    Xt = imp.fit_transform(X.iloc[tr_sub])
    Xv = imp.transform(X.iloc[val_sub])
    Xe = imp.transform(X.iloc[te])
    Xt = sc.fit_transform(Xt)
    Xv = sc.transform(Xv)
    Xe = sc.transform(Xe)
    return Xt, Xv, Xe


def train_mlp_fold(X, y, train_idx, test_idx, cfg: Config, seed: int, threshold_policy="max_risk_f1"):
    set_seed(seed)
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    tr_sub, val_sub = train_val_split(train_idx, y, seed)
    Xt, Xv, Xe = fit_transform_train_val_test(X, tr_sub, val_sub, test_idx)
    xt = torch.tensor(Xt, dtype=torch.float32, device=device)
    xv = torch.tensor(Xv, dtype=torch.float32, device=device)
    yt = torch.tensor(y[tr_sub], dtype=torch.long, device=device)
    yv = torch.tensor(y[val_sub], dtype=torch.long, device=device)

    model = MLPClassifier(xt.size(1), cfg.hidden_dim, cfg.dropout).to(device)
    criterion = FocalLoss(gamma=1.0, alpha=class_weights_tensor(y[tr_sub], device))
    opt = torch.optim.AdamW(model.parameters(), lr=cfg.lr, weight_decay=cfg.weight_decay)
    best_state, best_val, bad = None, np.inf, 0
    t0 = time.perf_counter()
    for epoch in range(cfg.epochs):
        model.train()
        opt.zero_grad()
        loss = criterion(model(xt), yt)
        loss.backward()
        torch.nn.utils.clip_grad_norm_(model.parameters(), 5.0)
        opt.step()
        model.eval()
        with torch.no_grad():
            vloss = criterion(model(xv), yv)
            v = float(vloss.detach().cpu())
        if v < best_val:
            best_val = v
            best_state = {k: vv.detach().cpu().clone() for k, vv in model.state_dict().items()}
            bad = 0
        else:
            bad += 1
            if bad >= cfg.patience:
                break
    runtime = time.perf_counter() - t0
    if best_state is not None:
        model.load_state_dict({k: vv.to(device) for k, vv in best_state.items()})
    model.eval()
    with torch.no_grad():
        pv = F.softmax(model(torch.tensor(Xv, dtype=torch.float32, device=device)), dim=1).cpu().numpy()[:, 1]
        pe = F.softmax(model(torch.tensor(Xe, dtype=torch.float32, device=device)), dim=1).cpu().numpy()[:, 1]
    th = choose_threshold(y[val_sub], pv, threshold_policy, cfg)
    return pe, (pe >= th).astype(int), th, runtime, epoch + 1


def eval_mlp_oof(feature_sets: Dict[str, pd.DataFrame], y: np.ndarray, cfg: Config, seed: int, threshold_policy="max_risk_f1"):
    skf = cv_splitter(y, cfg, seed)
    rows, outputs = [], {}
    for name, X in feature_sets.items():
        model_name = f"MLP-Focal-{name}"
        oof_prob = np.zeros(len(y), dtype=float)
        oof_pred = np.zeros(len(y), dtype=int)
        thresholds = np.zeros(len(y), dtype=float)
        runtimes, epochs = [], []
        for fold, (tr, te) in enumerate(skf.split(np.zeros(len(y)), y), 1):
            print(f"[MLP seed={seed}] {model_name} fold {fold}/{skf.get_n_splits()}")
            prob, pred, th, rt, ep = train_mlp_fold(X, y, tr, te, cfg, seed + fold, threshold_policy)
            oof_prob[te] = prob
            oof_pred[te] = pred
            thresholds[te] = th
            runtimes.append(rt)
            epochs.append(ep)
        m = binary_metrics(y, oof_prob, pred=oof_pred)
        m.update({"model": model_name, "seed": seed, "threshold_policy": threshold_policy, "threshold_mean": float(np.mean(thresholds)), "runtime_sec_total": float(np.sum(runtimes)), "epochs_used_mean": float(np.mean(epochs))})
        rows.append(m)
        outputs[model_name] = {"prob": oof_prob, "pred": oof_pred, "thresholds": thresholds}
    return pd.DataFrame(rows), outputs


def eval_sklearn_oof(feature_sets: Dict[str, pd.DataFrame], y: np.ndarray, cfg: Config, seed: int, threshold_policy="max_risk_f1"):
    skf = cv_splitter(y, cfg, seed)
    models = {
        "LogReg": LogisticRegression(max_iter=3000, class_weight="balanced"),
        "RF": RandomForestClassifier(n_estimators=500, random_state=seed, class_weight="balanced_subsample", min_samples_leaf=2),
    }
    rows, outputs = [], {}
    for fs_name, X in feature_sets.items():
        X = pd.DataFrame(X).replace([np.inf, -np.inf], np.nan).reset_index(drop=True)
        for model_short, clf in models.items():
            model_name = f"{model_short}-{fs_name}"
            oof_prob = np.zeros(len(y), dtype=float)
            oof_pred = np.zeros(len(y), dtype=int)
            thresholds = np.zeros(len(y), dtype=float)
            runtime_total = 0.0
            for fold, (tr, te) in enumerate(skf.split(np.zeros(len(y)), y), 1):
                tr_sub, val_sub = train_val_split(tr, y, seed + fold)
                pipe = Pipeline([
                    ("imputer", SimpleImputer(strategy="median")),
                    ("scaler", StandardScaler()),
                    ("clf", clf),
                ])
                t0 = time.perf_counter()
                pipe.fit(X.iloc[tr_sub], y[tr_sub])
                runtime_total += time.perf_counter() - t0
                pv = pipe.predict_proba(X.iloc[val_sub])[:, 1]
                pe = pipe.predict_proba(X.iloc[te])[:, 1]
                th = choose_threshold(y[val_sub], pv, threshold_policy, cfg)
                oof_prob[te] = pe
                oof_pred[te] = (pe >= th).astype(int)
                thresholds[te] = th
            m = binary_metrics(y, oof_prob, pred=oof_pred)
            m.update({"model": model_name, "seed": seed, "threshold_policy": threshold_policy, "threshold_mean": float(np.mean(thresholds)), "runtime_sec_total": runtime_total, "epochs_used_mean": np.nan})
            rows.append(m)
            outputs[model_name] = {"prob": oof_prob, "pred": oof_pred, "thresholds": thresholds}
    return pd.DataFrame(rows), outputs


# ============================================================
# 6. VGIB tuning and official evaluation
# ============================================================

def screening_selection_score(row: pd.Series, cfg: Config):
    # Primary goal: high recall under minimum precision floor.
    # This avoids selecting a model that marks everyone as Risk.
    if row["risk_precision"] >= cfg.tuning_precision_floor:
        return row["risk_recall"] + 0.05 * row["risk_f1"] + 0.01 * row["pr_auc"]
    return 0.50 * row["risk_f1"] + 0.10 * row["risk_precision"]


def tune_vgib(feats: Dict, y: np.ndarray, cfg: Config, seed: int):
    rows = []
    best_cache = None
    for edge_rep in cfg.edge_rep_grid:
        edge_df = get_edge_rep_df(feats, edge_rep)
        data = build_heterodata(feats["brainclinical_x"], edge_df, y, cfg)
        for beta in cfg.beta_grid:
            for gamma in cfg.gamma_grid:
                for policy in cfg.threshold_policy_grid:
                    model_name = f"VGIB-TUNE_edge={edge_rep}_beta={beta}_gamma={gamma}_policy={policy}"
                    df, cache = eval_hgnn_oof(
                        data, y, cfg, seed, model_name,
                        loss_type="focal", use_gaussian=True, use_ib=True,
                        beta=beta, gamma=gamma, threshold_policy=policy,
                    )
                    r = df.iloc[0].to_dict()
                    r.update({"edge_rep": edge_rep, "beta": beta, "gamma": gamma, "selected_threshold_policy": policy})
                    r["selection_score"] = screening_selection_score(pd.Series(r), cfg)
                    rows.append(r)
                    if best_cache is None or r["selection_score"] > best_cache[0]["selection_score"]:
                        best_cache = (r, cache)
    tune_df = pd.DataFrame(rows).sort_values("selection_score", ascending=False)
    best = tune_df.iloc[0].to_dict()
    selected = {
        "edge_rep": best["edge_rep"],
        "beta": float(best["beta"]),
        "gamma": float(best["gamma"]),
        "threshold_policy": best["selected_threshold_policy"],
        "selection_score": float(best["selection_score"]),
        "risk_recall": float(best["risk_recall"]),
        "risk_precision": float(best["risk_precision"]),
        "risk_f1": float(best["risk_f1"]),
        "auc": float(best["auc"]),
        "pr_auc": float(best["pr_auc"]),
    }
    return tune_df, selected


def eval_selected_vgib(feats: Dict, y: np.ndarray, cfg: Config, selected: Dict, seed: int, model_name="VGIB-HGNN-Focal-Tuned"):
    edge_df = get_edge_rep_df(feats, selected["edge_rep"])
    data = build_heterodata(feats["brainclinical_x"], edge_df, y, cfg)
    df, cache = eval_hgnn_oof(
        data, y, cfg, seed, model_name,
        loss_type="focal", use_gaussian=True, use_ib=True,
        beta=float(selected["beta"]), gamma=float(selected["gamma"]),
        threshold_policy=selected["threshold_policy"],
    )
    df["edge_rep"] = selected["edge_rep"]
    return df, cache, data


def run_official_model_suite(feats: Dict, y: np.ndarray, cfg: Config, selected: Dict, seed: int):
    rows, oof = [], {}
    # Baselines use the SAME threshold policy as the tuned VGIB, so RQ1 compares screening operating points.
    policy = selected["threshold_policy"]

    sk_df, sk_cache = eval_sklearn_oof(
        {"BrainClinical": feats["brainclinical_x"], "AllTabular": feats["alltabular_log"]},
        y, cfg, seed, threshold_policy=policy,
    )
    rows.append(sk_df)
    oof.update(sk_cache)

    mlp_df, mlp_cache = eval_mlp_oof(
        {"BrainClinical": feats["brainclinical_x"], "AllTabular": feats["alltabular_log"]},
        y, cfg, seed, threshold_policy=policy,
    )
    rows.append(mlp_df)
    oof.update(mlp_cache)

    edge_df = get_edge_rep_df(feats, selected["edge_rep"])
    data = build_heterodata(feats["brainclinical_x"], edge_df, y, cfg)

    # HGNN baselines are evaluated under the same edge representation and gamma/policy.
    graph_specs = [
        ("HGNN-CE", "ce_weighted", False, False, 0.0, float(selected["gamma"])),
        ("HGNN-Focal", "focal", False, False, 0.0, float(selected["gamma"])),
        ("HGNN-Gaussian-Focal", "focal", True, False, 0.0, float(selected["gamma"])),
        ("VGIB-HGNN-Focal-Tuned", "focal", True, True, float(selected["beta"]), float(selected["gamma"])),
    ]
    for name, loss_type, use_g, use_ib, beta, gamma in graph_specs:
        df, cache = eval_hgnn_oof(
            data, y, cfg, seed, name,
            loss_type=loss_type, use_gaussian=use_g, use_ib=use_ib,
            beta=beta, gamma=gamma, threshold_policy=policy,
        )
        df["edge_rep"] = selected["edge_rep"]
        rows.append(df)
        oof.update(cache)

    perf = pd.concat(rows, ignore_index=True)
    return perf, oof, data


# ============================================================
# 7. RQ1 bootstrap and threshold-matched comparison
# ============================================================

def metric_value(y, prob, pred, metric: str):
    y = np.asarray(y).astype(int)
    prob = np.asarray(prob).astype(float)
    pred = np.asarray(pred).astype(int)
    if metric == "auc":
        if len(np.unique(y)) < 2:
            return np.nan
        return roc_auc_score(y, prob)
    if metric == "pr_auc":
        if len(np.unique(y)) < 2:
            return np.nan
        return average_precision_score(y, prob)
    if metric == "risk_recall":
        return recall_score(y, pred, pos_label=1, zero_division=0)
    if metric == "risk_precision":
        return precision_score(y, pred, pos_label=1, zero_division=0)
    if metric == "risk_f1":
        return f1_score(y, pred, pos_label=1, zero_division=0)
    if metric == "macro_f1":
        return f1_score(y, pred, average="macro", zero_division=0)
    if metric == "brier":
        return brier_score_loss(y, prob)
    raise ValueError(metric)


def paired_bootstrap_difference(y, a, b, metric: str, cfg: Config):
    rng = np.random.default_rng(cfg.random_seed)
    prob_a, pred_a = a["prob"], a["pred"]
    prob_b, pred_b = b["prob"], b["pred"]
    n = len(y)
    observed = metric_value(y, prob_a, pred_a, metric) - metric_value(y, prob_b, pred_b, metric)
    diffs = []
    for _ in range(cfg.n_bootstrap):
        idx = rng.integers(0, n, n)
        if metric in ["auc", "pr_auc"] and len(np.unique(y[idx])) < 2:
            continue
        da = metric_value(y[idx], prob_a[idx], pred_a[idx], metric)
        db = metric_value(y[idx], prob_b[idx], pred_b[idx], metric)
        if np.isfinite(da) and np.isfinite(db):
            diffs.append(da - db)
    diffs = np.asarray(diffs)
    return {
        "metric": metric,
        "difference_A_minus_B": float(observed),
        "ci_lower": float(np.percentile(diffs, 100 * cfg.alpha / 2)),
        "ci_upper": float(np.percentile(diffs, 100 * (1 - cfg.alpha / 2))),
        "p_value": float(min(1.0, 2 * min(np.mean(diffs <= 0), np.mean(diffs >= 0)))),
        "n_bootstrap_valid": int(len(diffs)),
    }


def run_bootstrap(y: np.ndarray, oof: Dict[str, Dict], cfg: Config):
    comparisons = [
        ("VGIB-HGNN-Focal-Tuned", "RF-AllTabular"),
        ("VGIB-HGNN-Focal-Tuned", "RF-BrainClinical"),
        ("VGIB-HGNN-Focal-Tuned", "MLP-Focal-BrainClinical"),
        ("VGIB-HGNN-Focal-Tuned", "HGNN-Focal"),
        ("VGIB-HGNN-Focal-Tuned", "HGNN-Gaussian-Focal"),
        ("HGNN-Focal", "RF-AllTabular"),
        ("MLP-Focal-AllTabular", "MLP-Focal-BrainClinical"),
        ("RF-AllTabular", "RF-BrainClinical"),
    ]
    metrics = ["auc", "pr_auc", "risk_recall", "risk_precision", "risk_f1", "macro_f1", "brier"]
    rows = []
    for a, b in comparisons:
        if a not in oof or b not in oof:
            print("[Bootstrap skip] missing", a, b)
            continue
        for metric in metrics:
            res = paired_bootstrap_difference(y, oof[a], oof[b], metric, cfg)
            res.update({"model_A": a, "model_B": b})
            rows.append(res)
    return pd.DataFrame(rows)


def run_threshold_matched(y: np.ndarray, oof: Dict[str, Dict], cfg: Config):
    models = [m for m in [
        "RF-AllTabular", "RF-BrainClinical", "MLP-Focal-BrainClinical",
        "HGNN-Focal", "HGNN-Gaussian-Focal", "VGIB-HGNN-Focal-Tuned"
    ] if m in oof]
    ref_rate = np.mean(oof["RF-AllTabular"]["pred"] == 1) if "RF-AllTabular" in oof else 0.2
    rows = []
    for model in models:
        prob = oof[model]["prob"]
        settings = [
            ("default_0.5", 0.5),
            ("matched_predicted_risk_rate", choose_threshold(y, prob, "match_predicted_rate", cfg, target=ref_rate)),
            (f"recall_at_precision_{cfg.target_precision}", choose_threshold(y, prob, "recall_at_precision", cfg, target=cfg.target_precision)),
            (f"precision_at_recall_{cfg.target_recall}", choose_threshold(y, prob, "precision_at_recall", cfg, target=cfg.target_recall)),
            ("max_risk_f1", choose_threshold(y, prob, "max_risk_f1", cfg)),
        ]
        for policy, th in settings:
            m = binary_metrics(y, prob, threshold=th)
            m.update({"model": model, "threshold_policy": policy, "threshold": th, "reference_predicted_risk_rate": ref_rate})
            rows.append(m)
    return pd.DataFrame(rows)


# ============================================================
# 8. RQ2 weak alignment
# ============================================================

def weak_alignment_analysis(feats: Dict, y: np.ndarray, cfg: Config):
    Xb = standardize_matrix(feats["brain_x"])
    Xm = standardize_matrix(feats["micro_log"])
    n = Xb.shape[0]
    n_comp_b = max(1, min(5, Xb.shape[1], n - 2))
    n_comp_m = max(1, min(5, Xm.shape[1], n - 2))
    B = PCA(n_components=n_comp_b, random_state=cfg.random_seed).fit_transform(Xb)
    M = PCA(n_components=n_comp_m, random_state=cfg.random_seed).fit_transform(Xm)
    cv = max(2, min(cfg.n_splits, int(pd.Series(y).value_counts().min())))
    ridge = RidgeCV(alphas=np.logspace(-3, 3, 13))
    m2b = cross_val_score(ridge, M, B, cv=cv, scoring="r2").mean()
    b2m = cross_val_score(ridge, B, M, cv=cv, scoring="r2").mean()

    rows = [
        {"analysis": "Microbiome PCs -> Brain PCs CV R2", "value": m2b, "interpretation": "low/negative supports weak latent alignment"},
        {"analysis": "Brain PCs -> Microbiome PCs CV R2", "value": b2m, "interpretation": "low/negative supports weak latent alignment"},
    ]

    cca_components = max(1, min(3, B.shape[1], M.shape[1]))
    try:
        cca = CCA(n_components=cca_components, max_iter=5000)
        U, V = cca.fit_transform(B, M)
        for i in range(cca_components):
            rows.append({"analysis": f"CCA component {i+1}", "value": float(np.corrcoef(U[:, i], V[:, i])[0, 1]), "interpretation": "low CCA supports weak shared linear latent space"})
    except Exception:
        pass

    max_k = min(20, n - 1)
    brain_nn = NearestNeighbors(n_neighbors=max_k + 1).fit(Xb).kneighbors(Xb, return_distance=False)[:, 1:]
    micro_nn = NearestNeighbors(n_neighbors=max_k + 1).fit(Xm).kneighbors(Xm, return_distance=False)[:, 1:]
    for k in [5, 10, 20]:
        if k <= max_k:
            vals = []
            for i in range(n):
                vals.append(len(set(brain_nn[i, :k]).intersection(set(micro_nn[i, :k]))) / k)
            rows.append({"analysis": f"Neighbor overlap@{k}", "value": float(np.mean(vals)), "interpretation": "low overlap means brain-neighbors are not microbiome-neighbors"})
    return pd.DataFrame(rows)


# ============================================================
# 9. RQ3 ablation and sensitivity
# ============================================================

def eval_patientonly_vgib_oof(X: pd.DataFrame, y: np.ndarray, cfg: Config, seed: int, beta: float, gamma: float, policy: str):
    # PatientOnly-VGIB-Focal as no-micro control.
    skf = cv_splitter(y, cfg, seed)
    oof_prob = np.zeros(len(y), dtype=float)
    oof_pred = np.zeros(len(y), dtype=int)
    runtimes = []
    thresholds = np.zeros(len(y), dtype=float)
    for fold, (tr, te) in enumerate(skf.split(np.zeros(len(y)), y), 1):
        tr_sub, val_sub = train_val_split(tr, y, seed + fold)
        Xt, Xv, Xe = fit_transform_train_val_test(X, tr_sub, val_sub, te)
        device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
        model = PatientOnlyVGIB(Xt.shape[1], cfg.hidden_dim, cfg.latent_dim, cfg.dropout, use_gaussian=True).to(device)
        criterion = FocalLoss(gamma=gamma, alpha=class_weights_tensor(y[tr_sub], device))
        opt = torch.optim.AdamW(model.parameters(), lr=cfg.lr, weight_decay=cfg.weight_decay)
        xt = torch.tensor(Xt, dtype=torch.float32, device=device)
        xv = torch.tensor(Xv, dtype=torch.float32, device=device)
        yt = torch.tensor(y[tr_sub], dtype=torch.long, device=device)
        yv = torch.tensor(y[val_sub], dtype=torch.long, device=device)
        best_state, best_v, bad = None, np.inf, 0
        t0 = time.perf_counter()
        for epoch in range(cfg.epochs):
            model.train()
            opt.zero_grad()
            logits, mu, logvar = model(xt)
            loss = criterion(logits, yt) + beta * kl_normal(mu, logvar)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(model.parameters(), 5.0)
            opt.step()
            model.eval()
            with torch.no_grad():
                lv, mv, vv = model(xv)
                vloss = criterion(lv, yv) + beta * kl_normal(mv, vv)
                v = float(vloss.cpu())
            if v < best_v:
                best_v = v
                best_state = {k: vv.detach().cpu().clone() for k, vv in model.state_dict().items()}
                bad = 0
            else:
                bad += 1
                if bad >= cfg.patience:
                    break
        runtimes.append(time.perf_counter() - t0)
        if best_state is not None:
            model.load_state_dict({k: vv.to(device) for k, vv in best_state.items()})
        model.eval()
        with torch.no_grad():
            pv = F.softmax(model(torch.tensor(Xv, dtype=torch.float32, device=device))[0], dim=1).cpu().numpy()[:, 1]
            pe = F.softmax(model(torch.tensor(Xe, dtype=torch.float32, device=device))[0], dim=1).cpu().numpy()[:, 1]
        th = choose_threshold(y[val_sub], pv, policy, cfg)
        oof_prob[te] = pe
        oof_pred[te] = (pe >= th).astype(int)
        thresholds[te] = th
    m = binary_metrics(y, oof_prob, pred=oof_pred)
    m.update({"model": "NoMicro-PatientOnly-VGIB-Focal", "seed": seed, "threshold_policy": policy, "threshold_mean": float(np.mean(thresholds)), "runtime_sec_total": float(np.sum(runtimes)), "beta": beta, "gamma": gamma})
    return pd.DataFrame([m]), {"NoMicro-PatientOnly-VGIB-Focal": {"prob": oof_prob, "pred": oof_pred, "thresholds": thresholds}}


def run_rq3(feats: Dict, y: np.ndarray, cfg: Config, selected: Dict):
    seed = cfg.random_seed
    edge_df = get_edge_rep_df(feats, selected["edge_rep"])
    data_real = build_heterodata(feats["brainclinical_x"], edge_df, y, cfg)
    data_rand = randomize_micro_edges(data_real, seed)
    beta, gamma, policy = float(selected["beta"]), float(selected["gamma"]), selected["threshold_policy"]
    rows = []

    # A. Component ablation under selected config.
    specs = [
        ("RQ3A_HGNN-CE", "ce_weighted", False, False, 0.0, gamma),
        ("RQ3A_HGNN-Focal", "focal", False, False, 0.0, gamma),
        ("RQ3A_HGNN-Gaussian-Focal", "focal", True, False, 0.0, gamma),
        ("RQ3A_VGIB-HGNN-Focal-Tuned", "focal", True, True, beta, gamma),
    ]
    for name, loss_type, use_g, use_ib, b, g in specs:
        df, _ = eval_hgnn_oof(data_real, y, cfg, seed, name, loss_type, use_g, use_ib, b, g, policy)
        df["rq3_section"] = "A_component_ablation"
        df["edge_rep"] = selected["edge_rep"]
        rows.append(df)

    # B. Modality / data ablation.
    df_real, _ = eval_hgnn_oof(data_real, y, cfg, seed + 101, "RQ3B_RealMicroEdges-VGIB", "focal", True, True, beta, gamma, policy)
    df_rand, _ = eval_hgnn_oof(data_rand, y, cfg, seed + 102, "RQ3B_RandomizedMicroEdges-VGIB", "focal", True, True, beta, gamma, policy)
    df_nomicro, _ = eval_patientonly_vgib_oof(feats["brainclinical_x"], y, cfg, seed + 103, beta, gamma, policy)
    for df in [df_real, df_rand, df_nomicro]:
        df["rq3_section"] = "B_modality_data_ablation"
        df["edge_rep"] = selected["edge_rep"]
        rows.append(df)

    # C. MLP feature sensitivity.
    mlp_sets = {
        "BrainClinical": feats["brainclinical_x"],
        "AllTabularLog": feats["alltabular_log"],
        "AllTabularCLR": feats["alltabular_clr"],
        "MicroDiversity": feats["alltabular_div"],
        "CLRplusDiversity": feats["alltabular_clr_div"],
    }
    df_mlp, _ = eval_mlp_oof(mlp_sets, y, cfg, seed + 104, threshold_policy=policy)
    df_mlp["rq3_section"] = "C_mlp_feature_sensitivity"
    rows.append(df_mlp)

    return pd.concat(rows, ignore_index=True)


# ============================================================
# 10. RQ4 profile analysis with microbiome
# ============================================================

def cohen_d(a, b):
    a = pd.to_numeric(pd.Series(a), errors="coerce").dropna().values
    b = pd.to_numeric(pd.Series(b), errors="coerce").dropna().values
    if len(a) < 2 or len(b) < 2:
        return np.nan
    pooled = np.sqrt(((len(a) - 1) * np.var(a, ddof=1) + (len(b) - 1) * np.var(b, ddof=1)) / (len(a) + len(b) - 2))
    return float((np.mean(a) - np.mean(b)) / (pooled + 1e-8))


def compare_groups(df, group_col, group_a, group_b, feature_cols):
    rows = []
    A = df[df[group_col] == group_a]
    B = df[df[group_col] == group_b]
    for c in feature_cols:
        a = pd.to_numeric(A[c], errors="coerce").dropna()
        b = pd.to_numeric(B[c], errors="coerce").dropna()
        if len(a) < 2 or len(b) < 2:
            u, p = np.nan, np.nan
        else:
            try:
                u, p = mannwhitneyu(a, b, alternative="two-sided")
            except Exception:
                u, p = np.nan, np.nan
        rows.append({
            "comparison": f"{group_a} vs {group_b}",
            "feature": c,
            "n_A": int(len(a)),
            "n_B": int(len(b)),
            "mean_A": float(a.mean()) if len(a) else np.nan,
            "mean_B": float(b.mean()) if len(b) else np.nan,
            "median_A": float(a.median()) if len(a) else np.nan,
            "median_B": float(b.median()) if len(b) else np.nan,
            "cohen_d_A_minus_B": cohen_d(a, b),
            "mannwhitney_u": u,
            "p_value": p,
        })
    out = pd.DataFrame(rows)
    valid = out["p_value"].notna()
    out["q_value_fdr"] = np.nan
    if valid.sum() > 0:
        out.loc[valid, "q_value_fdr"] = multipletests(out.loc[valid, "p_value"], method="fdr_bh")[1]
    return out


def run_rq4(merged, feats, y, oof, cfg: Config):
    prob = oof[cfg.rq4_model_name]["prob"]
    pred = oof[cfg.rq4_model_name]["pred"]
    group = pd.DataFrame({
        "ID": merged["ID"].values,
        cfg.label_col: merged[cfg.label_col].values,
        "y_true": y,
        "prob_risk": prob,
        "pred_risk": pred,
    })
    group["risk_direction_group"] = "Correct_or_Other"
    group.loc[(group["y_true"] == 0) & (group["pred_risk"] == 1), "risk_direction_group"] = "Normal_to_Risk"
    group.loc[(group["y_true"] == 1) & (group["pred_risk"] == 0), "risk_direction_group"] = "Risk_to_Normal"
    group.loc[(group["y_true"] == 0) & (group["pred_risk"] == 0), "risk_direction_group"] = "Correct_Normal"
    group.loc[(group["y_true"] == 1) & (group["pred_risk"] == 1), "risk_direction_group"] = "Correct_Risk"

    basic = build_basic_features(merged, include_mmse=True).reset_index(drop=True)
    brain = build_brain_features(merged).reset_index(drop=True)
    clinical_brain_profile = pd.concat([group, basic, brain], axis=1)
    cb_cols = [c for c in clinical_brain_profile.columns if c not in ["ID", cfg.label_col, "y_true", "prob_risk", "pred_risk", "risk_direction_group"]]

    micro_profile = pd.concat([
        group,
        feats["micro_div"],
        feats["micro_log"].add_prefix("LOG_"),
        feats["micro_clr"],
    ], axis=1)
    micro_cols = [c for c in micro_profile.columns if c not in ["ID", cfg.label_col, "y_true", "prob_risk", "pred_risk", "risk_direction_group"]]

    comparisons = [
        ("Normal_to_Risk", "Correct_Normal"),
        ("Risk_to_Normal", "Correct_Risk"),
        ("Normal_to_Risk", "Risk_to_Normal"),
    ]
    cb_results = pd.concat([compare_groups(clinical_brain_profile, "risk_direction_group", a, b, cb_cols) for a, b in comparisons], ignore_index=True)
    micro_results = pd.concat([compare_groups(micro_profile, "risk_direction_group", a, b, micro_cols) for a, b in comparisons], ignore_index=True)

    cb_results = cb_results.sort_values(["comparison", "q_value_fdr", "p_value"], na_position="last")
    micro_results = micro_results.sort_values(["comparison", "q_value_fdr", "p_value"], na_position="last")
    counts = group["risk_direction_group"].value_counts().reset_index()
    counts.columns = ["group", "count"]
    return group, counts, cb_results, micro_results


# ============================================================
# 11. Complexity and runtime
# ============================================================

def complexity_analysis(graph_data: HeteroData, cfg: Config, runtime_df: pd.DataFrame):
    N = graph_data["patient"].x.size(0)
    S = graph_data["species"].x.size(0)
    E = graph_data[("patient", "has", "species")].edge_index.size(1)
    d_p = graph_data["patient"].x.size(1)
    h = cfg.hidden_dim
    z = cfg.latent_dim
    L = cfg.num_layers
    A = cfg.heads
    C = 2
    comp = pd.DataFrame([
        {"component": "Feature preprocessing", "complexity": "O(N(d_p + S))", "instantiated_terms": f"N={N}, d_p={d_p}, S={S}"},
        {"component": "Patient-species graph construction", "complexity": "O(NS)", "instantiated_terms": f"N={N}, S={S}"},
        {"component": "HGNN message passing", "complexity": "O(L A E h)", "instantiated_terms": f"L={L}, A={A}, E={E}, h={h}"},
        {"component": "Gaussian latent projection", "complexity": "O(N h z)", "instantiated_terms": f"N={N}, h={h}, z={z}"},
        {"component": "KL regularization", "complexity": "O(N z)", "instantiated_terms": f"N={N}, z={z}"},
        {"component": "Classification", "complexity": "O(N z C)", "instantiated_terms": f"N={N}, z={z}, C={C}"},
        {"component": "Total per epoch", "complexity": "O(L A E h + N h z + N z C)", "instantiated_terms": f"L={L}, A={A}, E={E}, h={h}, N={N}, z={z}, C={C}"},
    ])
    rt = runtime_df.groupby("model", as_index=False).agg(
        runtime_sec_total_mean=("runtime_sec_total", "mean"),
        runtime_sec_total_std=("runtime_sec_total", "std"),
        epochs_used_mean=("epochs_used_mean", "mean"),
        auc_mean=("auc", "mean"),
        risk_recall_mean=("risk_recall", "mean"),
        risk_precision_mean=("risk_precision", "mean"),
        risk_f1_mean=("risk_f1", "mean"),
    )
    return comp, rt


# ============================================================
# 12. Main
# ============================================================

def main(cfg: Config = CFG):
    set_seed(cfg.random_seed)
    ensure_dir(cfg.output_dir)

    basic, micro, brain, merged = load_and_merge(cfg)
    feats = prepare_features(merged, micro, cfg)
    y = feats["y"]

    inventory = pd.DataFrame([
        {"item": "N", "value": len(y)},
        {"item": "Normal_count", "value": int(np.sum(y == 0))},
        {"item": "Risk_count_MCI_plus_Dementia", "value": int(np.sum(y == 1))},
        {"item": "selected_species", "value": len(feats["selected_species"])},
        {"item": "brainclinical_dim", "value": feats["brainclinical_x"].shape[1]},
    ])
    save_csv(inventory, os.path.join(cfg.output_dir, "00_dataset_inventory.csv"))

    # ---------- Stage 1: tune VGIB ----------
    if cfg.run_tuning:
        print("\n========== Stage 1: Tune VGIB-HGNN-Focal for screening ==========")
        tune_df, selected = tune_vgib(feats, y, cfg, cfg.random_seed)
        save_csv(tune_df, os.path.join(cfg.output_dir, "RQ1_00_vgib_tuning_grid.csv"))
        with open(os.path.join(cfg.output_dir, "RQ1_00_selected_vgib_config.json"), "w", encoding="utf-8") as f:
            json.dump(selected, f, indent=2, ensure_ascii=False)
        print("Selected VGIB config:", selected)
    else:
        selected = {
            "edge_rep": "log1p",
            "beta": 0.0,
            "gamma": 0.5,
            "threshold_policy": "max_risk_f1",
        }

    # ---------- RQ1: official main OOF ----------
    print("\n========== RQ1: Official model suite with tuned VGIB ==========")
    main_perf, main_oof, main_graph = run_official_model_suite(feats, y, cfg, selected, cfg.random_seed)
    main_perf = main_perf.sort_values(["risk_recall", "risk_f1", "auc"], ascending=False)
    save_csv(main_perf, os.path.join(cfg.output_dir, "RQ1_01_main_official_performance.csv"))

    oof_df = pd.DataFrame({"ID": merged["ID"].values, "Diagnosis": merged[cfg.label_col].values, "y_true": y})
    for name, rec in main_oof.items():
        oof_df[f"prob_{name}"] = rec["prob"]
        oof_df[f"pred_{name}"] = rec["pred"]
    save_csv(oof_df, os.path.join(cfg.output_dir, "RQ1_02_oof_predictions.csv"))

    # ---------- RQ1 repeated-seed ----------
    if cfg.run_repeated_seed:
        print("\n========== RQ1: Repeated-seed robustness ==========")
        reps = []
        for seed in cfg.seeds:
            perf, _, _ = run_official_model_suite(feats, y, cfg, selected, seed)
            reps.append(perf)
        reps_raw = pd.concat(reps, ignore_index=True)
        save_csv(reps_raw, os.path.join(cfg.output_dir, "RQ1_03_repeated_seed_raw.csv"))
        reps_summary = aggregate_rows(reps_raw, ["model"])
        reps_summary = reps_summary.sort_values(["risk_recall", "risk_f1", "auc"], ascending=False)
        save_csv(reps_summary, os.path.join(cfg.output_dir, "RQ1_04_repeated_seed_summary.csv"))
    else:
        reps_raw = main_perf.copy()

    # ---------- RQ1 bootstrap ----------
    if cfg.run_bootstrap:
        print("\n========== RQ1: Paired bootstrap with tuned VGIB ==========")
        boot_df = run_bootstrap(y, main_oof, cfg)
        save_csv(boot_df, os.path.join(cfg.output_dir, "RQ1_05_paired_bootstrap_tuned.csv"))

    # ---------- RQ1 threshold matched ----------
    if cfg.run_threshold_matched:
        print("\n========== RQ1: Threshold-matched comparison ==========")
        th_df = run_threshold_matched(y, main_oof, cfg)
        save_csv(th_df, os.path.join(cfg.output_dir, "RQ1_06_threshold_matched_comparison.csv"))

    # ---------- RQ2 weak alignment ----------
    print("\n========== RQ2: Weak alignment ==========")
    weak_df = weak_alignment_analysis(feats, y, cfg)
    save_csv(weak_df, os.path.join(cfg.output_dir, "RQ2_weak_alignment_metrics.csv"))

    # ---------- RQ3 ablation ----------
    if cfg.run_rq3:
        print("\n========== RQ3: Ablation and sensitivity under selected config ==========")
        rq3_df = run_rq3(feats, y, cfg, selected)
        rq3_df = rq3_df.sort_values(["rq3_section", "risk_recall", "risk_f1", "auc"], ascending=[True, False, False, False])
        save_csv(rq3_df, os.path.join(cfg.output_dir, "RQ3_ablation_and_sensitivity_tuned.csv"))

    # ---------- RQ4 disagreement profile ----------
    if cfg.run_rq4:
        print("\n========== RQ4: Disagreement / boundary-case profile with microbiome ==========")
        group, counts, cb_results, micro_results = run_rq4(merged, feats, y, main_oof, cfg)
        save_csv(group, os.path.join(cfg.output_dir, "RQ4_01_disagreement_groups.csv"))
        save_csv(counts, os.path.join(cfg.output_dir, "RQ4_02_group_counts.csv"))
        save_csv(cb_results, os.path.join(cfg.output_dir, "RQ4_03_clinical_brain_profile_tests.csv"))
        save_csv(micro_results, os.path.join(cfg.output_dir, "RQ4_04_microbiome_profile_tests.csv"))
        top_micro = micro_results.groupby("comparison").head(cfg.rq4_top_species_report)
        save_csv(top_micro, os.path.join(cfg.output_dir, "RQ4_05_top_microbiome_differences.csv"))

    # ---------- 5.2 Complexity and runtime ----------
    print("\n========== 5.2 Complexity and runtime ==========")
    comp_df, rt_df = complexity_analysis(main_graph, cfg, reps_raw if cfg.run_repeated_seed else main_perf)
    save_csv(comp_df, os.path.join(cfg.output_dir, "5_2_01_complexity_table.csv"))
    save_csv(rt_df, os.path.join(cfg.output_dir, "5_2_02_empirical_runtime_summary.csv"))

    readme = f"""
Tuned VGIB-HGNN ICDM suite completed.

Output folder:
{cfg.output_dir}

Most important files:
1. RQ1_00_vgib_tuning_grid.csv
   Full VGIB tuning grid over edge representation, beta, gamma, threshold policy.

2. RQ1_00_selected_vgib_config.json
   Selected VGIB-HGNN-Focal configuration. This is the official proposed model.

3. RQ1_01_main_official_performance.csv
   Main performance table using the tuned VGIB and matching screening policy.

4. RQ1_04_repeated_seed_summary.csv
   Robustness across seeds.

5. RQ1_05_paired_bootstrap_tuned.csv
   Paired bootstrap based on the tuned VGIB setting.

6. RQ2_weak_alignment_metrics.csv
   Cross-modal R2, CCA, neighbor overlap.

7. RQ3_ablation_and_sensitivity_tuned.csv
   Ablations are now done under the selected VGIB configuration.

8. RQ4_05_top_microbiome_differences.csv
   Boundary-case microbiome profile analysis.

9. 5_2_01_complexity_table.csv and 5_2_02_empirical_runtime_summary.csv
   Complexity and runtime analysis.

Important framing:
- The proposed model is VGIB-HGNN-Focal-Tuned.
- Do NOT report a fixed beta=1e-3, gamma=2.0, threshold=0.5 VGIB as the main model.
- This suite evaluates VGIB as a screening framework with validation-selected operating points.
"""
    with open(os.path.join(cfg.output_dir, "README_experiment_outputs.txt"), "w", encoding="utf-8") as f:
        f.write(readme)
    print("Saved:", os.path.join(cfg.output_dir, "README_experiment_outputs.txt"))
    print("\nAll done. Outputs saved to:", cfg.output_dir)


if __name__ == "__main__":
    main(CFG)